-- Переклади статей журналу та story/solution проєктних пропозицій (pl/en/de/lt).
-- Згенеровано scripts/stone-i18n-sql.mjs з data/stone/i18n/*.json. Ідемпотентно: i18n перезаписується цілком.
begin;
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Quarz oder Granit für die Arbeitsplatte: Was ist 2026 besser?","h1":"Quarz oder Granit für die Küchenarbeitsplatte — was wählen?","description":"Quarz oder Granit für die Arbeitsplatte? Wir vergleichen Festigkeit, Pflege, Hitze, Zeichnung und Preis, damit Sie das Material für Ihre Küche wählen können.","dek":"Die zwei beliebtesten Materialien für die Küche: wo jedes gewinnt und wo es verliert.","intro":"Quarz und Granit decken die meisten Anfragen für eine Küchenarbeitsplatte ab, aber auf unterschiedliche Weise. Granit ist ein natürliches Gestein mit einzigartiger Zeichnung, das heißes Kochgeschirr gelassen verträgt und seine Politur jahrelang behält. Quarz ist ein Verbundwerkstoff aus Quarzsand und Harz: porenfrei, farbstabil und einfacher in der täglichen Pflege. Unten erklären wir den Unterschied an Beispielen aus unserer Fertigung in Kostopil.","sections":[{"heading":"Was wählen — Quarz oder Granit?","body":"Die kurze Antwort: Wenn Sie viel kochen, Heißes direkt auf die Platte stellen und die Küche einen natürlichen Charakter haben soll, wählen Sie Granit. Wenn Ihnen eine gleichmäßige Farbe, völlige Porenfreiheit und minimale Pflege wichtiger sind und Sie Heißes ohnehin auf einen Untersetzer stellen, wählen Sie Quarz.\n\nEs ist keine Frage von „besser oder schlechter“, sondern eine Frage des Szenarios. Beide Materialien halten Jahrzehnte, beide werden mit derselben Technik geschnitten, poliert und montiert. Der Unterschied liegt im Verhalten während der Nutzung, und genau das sollte man vor der Bestellung abwägen."},{"heading":"Worin unterscheidet sich Quarzkomposit von Granit?","body":"Granit wird in Blöcken aus dem Steinbruch gewonnen, in Rohplatten gesägt und poliert. Alles, was Sie auf der Oberfläche sehen, hat die Natur geschaffen: Kristalle aus Feldspat, Quarz und Glimmer, Adern, Einschlüsse. Zwei Platten aus einem Block sind ähnlich, aber nicht gleich.\n\nQuarzkomposit entsteht in der Fabrik: Etwa 90–93 % gemahlener Quarz wird mit Harz und Pigmenten unter Vakuum verpresst. Daraus folgen die Haupteigenschaften: eine porenfreie Oberfläche, stabile Farbe innerhalb einer Charge, Dekore in „Marmor-“ oder „Betonoptik“. Das Harz setzt auch die Grenzen: Das Material mag keine Temperaturen über etwa 150 °C und ist nicht für den Außenbereich bestimmt, da UV-Licht den Farbton mit der Zeit verändert."},{"heading":"Was ist fester und praktischer im Alltag?","body":"In der Härte liegen beide Materialien nah beieinander: 6–7 auf der Mohs-Skala, ein Messer zerkratzt sie also nicht. Der Unterschied liegt anderswo. Auf Granit kann man eine heiße Pfanne vergessen, und nichts passiert. Auf Quarz hinterlässt ein heißer Boden einen matten Fleck, der sich zu Hause nicht auspolieren lässt, daher ist ein Untersetzer Pflicht.\n\nQuarz hat den Vorteil an der Spüle und in der Kochzone: Er nimmt weder Wasser noch Öl, Wein oder Rote-Bete-Saft auf. Granit mit guter Imprägnierung verhält sich fast genauso, aber die Imprägnierung muss regelmäßig erneuert werden. Abplatzungen an Ecken sind in beiden Fällen möglich und werden in beiden Fällen vor Ort repariert."},{"heading":"Was braucht weniger Pflege?","body":"Quarz: weiches Tuch, warmes Wasser, bei Bedarf ein neutrales Mittel. Keine Imprägnierung, kein Wachsen. Die einzige Regel: keine Scheuermittel und keine aggressive Chemie wie Backofenreiniger.\n\nGranit: dieselbe tägliche Routine plus eine Kontrolle der Imprägnierung alle paar Monate. Der Test ist einfach: ein Wassertropfen auf der Oberfläche; erscheint nach 10–15 Minuten darunter ein dunkler Fleck, ist es Zeit, den Schutz zu erneuern. Wir zeigen bei der Übergabe, wie das geht."},{"heading":"Für wen ist Granit, für wen Quarz?","body":"Granit ist für alle, die eine natürliche Zeichnung schätzen und nicht an Hitze denken wollen. Er passt in Häuser mit großer Küche, wo die Arbeitsplatte als Werktisch dient, und in Interieurs, in denen die Textur des Steins zählt.\n\nQuarz ist für helle minimalistische Küchen, für lange Platten ohne sichtbare Fugen zwischen gleichen Elementen, für Familien, die eine maximal einfache Nutzung wollen. Er ist auch praktisch, wenn die Farbe exakt zu den Fronten passen muss: Der Katalog hat Dutzende wiederholbarer Dekore von Caesarstone, Vicostone und Silestone."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Porosität","Quarz porenfrei","Granit braucht alle 1–3 Jahre Imprägnierung"],["Heißes","Quarz nur mit Untersetzer","Granit verträgt heißes Kochgeschirr"],["Zeichnung","Quarz wiederholbar","Granit einzigartig, Platte freigeben"],["Außenbereich","Quarz nicht für außen","Granit eignet sich für Terrassen und Vorbauten"],["Reparatur","Beide werden vor Ort repariert","Granitpolitur wird vollständig wiederhergestellt"]]},"faq":[{"question":"Muss Granit imprägniert werden?","answer":"Ja, polierter Granit wird nach der Montage mit einem Schutzmittel imprägniert, und der Vorgang wird je nach Wassertest wiederholt, meist alle ein bis drei Jahre. Das dauert eine halbe Stunde und braucht keinen Fachmann."},{"question":"Fürchtet Quarz heißes Kochgeschirr?","answer":"Kurzer Kontakt mit einem warmen Topf ist unbedenklich, aber eine Pfanne vom Herd oder ein Blech aus dem Ofen kann wegen des Harzes einen matten Fleck hinterlassen. Benutzen Sie einen Untersetzer."},{"question":"Was ist teurer?","answer":"Das hängt vom konkreten Stein ab. Ukrainische Granite sind meist günstiger als Markenquarz, während importierter Granit in seltener Farbe teurer sein kann. Vergleichen Sie Ihr Maß im Rechner."},{"question":"Was ist besser für eine Familie mit Kindern?","answer":"Beide Varianten sind sicher und hygienisch. Quarz ist einfacher, weil er keine Poren hat; Granit verzeiht Hitze und Stöße. Für eine helle Küche mit viel Kochen wählt man häufiger Quarz, für eine dunkle oder natürliche Küche Granit."}]},"en":{"title":"Quartz or granite for a countertop: which is better in 2026","h1":"Quartz or granite for a kitchen countertop — which to choose?","description":"Quartz or granite for a countertop? We compare strength, care, heat, pattern and price to help you choose the material for your kitchen.","dek":"The two most popular kitchen materials: where each wins and where it loses.","intro":"Quartz and granite cover most requests for a kitchen countertop, but they do it differently. Granite is a natural rock with a unique pattern that calmly takes hot pans and keeps its polish for years. Quartz is an engineered material of quartz sand and resin: non-porous, consistent in colour and simpler in daily care. Below we break down the difference with examples from our workshop in Kostopil.","sections":[{"heading":"What to choose — quartz or granite?","body":"The short answer: if you cook a lot, put hot pans straight on the counter and want the kitchen to have a natural character, choose granite. If an even colour, a total absence of pores and minimal care matter more, and you are used to putting hot things on a trivet, choose quartz.\n\nThis is not a question of “better or worse” but of scenario. Both materials last for decades, both are cut, polished and installed with the same technology. The difference is in how they behave in use, and that is exactly what to weigh before ordering."},{"heading":"How does engineered quartz differ from granite?","body":"Granite is quarried in blocks, sawn into slabs and polished. Everything you see on the surface was made by nature: crystals of feldspar, quartz and mica, veins, inclusions. Two slabs from one block are similar but not identical.\n\nEngineered quartz is made in a factory: roughly 90–93 % ground quartz is pressed with resin and pigments under vacuum. Hence its main properties: a surface without pores, a stable colour within a batch, “marble-look” or “concrete-look” decors. The resin also sets the limits: the material dislikes temperatures above about 150 °C and is not meant for outdoors, because ultraviolet changes the shade over time."},{"heading":"Which is stronger and more practical day to day?","body":"In hardness the two materials are close: 6–7 on the Mohs scale, meaning a knife will not scratch them. The difference lies elsewhere. On granite you can forget a hot frying pan and nothing will happen. On quartz a hot base leaves a matte mark that cannot be polished out at home, so a trivet is mandatory.\n\nQuartz has the advantage near the sink and in the cooking zone: it does not absorb water, oil, wine or beetroot juice. Granite with a good sealant behaves almost the same, but the sealant needs periodic renewal. Chips on corners are possible in both cases, and in both cases they are repaired on site."},{"heading":"Which needs less care?","body":"Quartz: a soft cloth, warm water, a neutral cleaner if needed. No sealing or waxing. The only rule is no abrasives and no aggressive chemicals such as oven cleaners.\n\nGranite: the same daily routine plus a sealant check every few months. The test is simple: a drop of water on the surface; if a dark spot appears under it after 10–15 minutes, it is time to renew the protection. We show how to do it when handing over the piece."},{"heading":"Who is granite for, and who is quartz for?","body":"Granite is for those who value a natural pattern and do not want to think about heat. It belongs in homes with a large kitchen where the counter works as a worktable, and in interiors where the texture of stone matters.\n\nQuartz is for light minimalist kitchens, for long counters without visible joints between identical slabs, for families who want the simplest possible use. It is also convenient when the colour must match the cabinet fronts exactly: the catalogue has dozens of repeatable decors from Caesarstone, Vicostone and Silestone."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Porosity","Quartz is non-porous","Granite needs sealing every 1–3 years"],["Heat","Quartz only via a trivet","Granite takes hot pans"],["Pattern","Quartz is repeatable","Granite is unique, approve the slab"],["Outdoors","Quartz is not for exteriors","Granite suits terraces and porches"],["Repair","Both are repaired on site","Granite polish is fully restored"]]},"faq":[{"question":"Does granite need sealing?","answer":"Yes, polished granite is treated with a protective sealant after installation and the procedure is repeated based on the water test, usually every one to three years. It takes half an hour and needs no professional."},{"question":"Is quartz afraid of hot pans?","answer":"Brief contact with a warm pot is safe, but a frying pan from the hob or a tray from the oven can leave a matte mark because of the resin. Use a trivet."},{"question":"Which is more expensive?","answer":"It depends on the specific stone. Ukrainian granites are usually more affordable than branded quartz, while an imported granite in a rare colour can cost more. Compare your size in the calculator."},{"question":"Which is better for a family with children?","answer":"Both options are safe and hygienic. Quartz is simpler because it has no pores; granite forgives heat and accidental knocks. For a light kitchen with active cooking people more often choose quartz, for a dark or natural kitchen — granite."}]},"lt":{"title":"Kvarcas ar granitas stalviršiui: kas geriau 2026 metais","h1":"Kvarcas ar granitas virtuvės stalviršiui — ką rinktis?","description":"Kvarcas ar granitas stalviršiui? Lyginame tvirtumą, priežiūrą, atsparumą karščiui, raštą ir kainą, kad išsirinktumėte medžiagą savo virtuvei.","dek":"Dvi populiariausios medžiagos virtuvei: kur kiekviena laimi, o kur pralaimi.","intro":"Kvarcas ir granitas patenkina daugumą virtuvės stalviršio užklausų, bet daro tai skirtingai. Granitas — natūrali uoliena su unikaliu raštu, kuri ramiai atlaiko karštus indus ir metų metus išlaiko poliravimą. Kvarcas — inžinerinė medžiaga iš kvarcinio smėlio ir dervos: neporėtas, pastovios spalvos ir paprastesnis kasdienėje priežiūroje. Toliau aiškinamės skirtumą pavyzdžiais iš mūsų gamybos Kostopilyje.","sections":[{"heading":"Ką rinktis — kvarcą ar granitą?","body":"Trumpas atsakymas: jei daug gaminate, statote karštus indus tiesiai ant stalviršio ir norite, kad virtuvė turėtų natūralų charakterį, rinkitės granitą. Jei jums svarbiau vienoda spalva, visiškas porų nebuvimas ir minimali priežiūra, o karštus indus esate įpratę statyti ant padėklo, rinkitės kvarcą.\n\nTai ne klausimas „geriau ar blogiau“, o scenarijaus klausimas. Abi medžiagos tarnauja dešimtmečius, abi pjaunamos, poliruojamos ir montuojamos ta pačia technologija. Skirtumas — elgesyje naudojimo metu, ir būtent jį verta pasverti prieš užsakant."},{"heading":"Kuo kvarco aglomeratas skiriasi nuo granito?","body":"Granitas kasamas blokais iš karjero, pjaunamas į plokštes ir poliruojamas. Visa, ką matote paviršiuje, sukūrė gamta: lauko špato, kvarco ir žėručio kristalai, gyslos, intarpai. Dvi plokštės iš vieno bloko panašios, bet ne vienodos.\n\nKvarco aglomeratas gaminamas gamykloje: apie 90–93 % malto kvarco presuojama su derva ir pigmentais vakuume. Iš čia pagrindinės savybės: paviršius be porų, stabili spalva partijoje, „marmuro“ ar „betono“ dekorai. Derva taip pat nustato ribas: medžiaga nemėgsta temperatūros virš maždaug 150 °C ir neskirta laukui, nes ultravioletas laikui bėgant keičia atspalvį."},{"heading":"Kas tvirtesnis ir praktiškesnis buityje?","body":"Kietumu abi medžiagos artimos: 6–7 pagal Moso skalę, tai yra peilis jų nesubraižys. Skirtumas kitur. Ant granito galima pamiršti karštą keptuvę ir nieko neatsitiks. Ant kvarco nuo karšto dugno lieka matinė žymė, kurios namuose nenupoliruosi, todėl padėklas privalomas.\n\nKvarcas turi pranašumą prie plautuvės ir gaminimo zonoje: jis neįgeria vandens, aliejaus, vyno ir burokėlių sulčių. Granitas su kokybišku impregnavimu elgiasi beveik taip pat, bet impregnavimą reikia periodiškai atnaujinti. Nuskilimai kampuose galimi abiem atvejais, ir abiem atvejais jie restauruojami vietoje."},{"heading":"Kam reikia mažiau priežiūros?","body":"Kvarcas: minkšta šluostė, šiltas vanduo, esant reikalui neutrali priemonė. Jokio impregnavimo ir vaškavimo. Vienintelė taisyklė — be abrazyvų ir be agresyvios chemijos, tokios kaip orkaičių valikliai.\n\nGranitas: ta pati kasdienė rutina plius impregnavimo patikra kartą per kelis mėnesius. Testas paprastas: vandens lašas ant paviršiaus; jei po 10–15 minučių po juo atsirado tamsi dėmė, laikas atnaujinti apsaugą. Parodome, kaip tai padaryti, perduodant gaminį."},{"heading":"Kam tinka granitas, o kam kvarcas?","body":"Granitas tiems, kas vertina natūralų raštą ir nenori galvoti apie karštį. Jis tinkamas namuose su didele virtuve, kur stalviršis dirba kaip darbastalis, ir interjeruose, kur svarbi akmens faktūra.\n\nKvarcas — šviesioms minimalistinėms virtuvėms, ilgiems stalviršiams be matomų siūlių tarp vienodų plokščių, šeimoms, kurios nori maksimaliai paprasto naudojimo. Jis taip pat patogus, kai spalvą reikia tiksliai suderinti su fasadais: kataloge dešimtys kartojamų Caesarstone, Vicostone ir Silestone dekorų."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Porėtumas","Kvarcas neporėtas","Granitą reikia impregnuoti kartą per 1–3 metus"],["Karštis","Kvarcas tik per padėklą","Granitas atlaiko karštus indus"],["Raštas","Kvarcas kartojamas","Granitas unikalus, suderinkite plokštę"],["Laukas","Kvarcas ne eksterjerui","Granitas tinka terasoms ir prieangiams"],["Remontas","Abu restauruojami vietoje","Granito poliravimas atkuriamas visiškai"]]},"faq":[{"question":"Ar reikia impregnuoti granitą?","answer":"Taip, poliruotas granitas po montavimo impregnuojamas apsaugine priemone, o procedūra kartojama pagal vandens testo rezultatus, paprastai kartą per vienerius–trejus metus. Tai užima pusvalandį ir meistro nereikia."},{"question":"Ar kvarcas bijo karštų indų?","answer":"Trumpas kontaktas su šiltu puodu saugus, bet keptuvė nuo viryklės ar skarda iš orkaitės gali palikti matinę žymę dėl dervos sudėtyje. Naudokite padėklą."},{"question":"Kas brangiau?","answer":"Priklauso nuo konkretaus akmens. Ukrainietiški granitai paprastai prieinamesni už firminį kvarcą, o importuotas retos spalvos granitas gali kainuoti brangiau. Palyginkite savo matmenis skaičiuoklėje."},{"question":"Kas geriau šeimai su vaikais?","answer":"Abu variantai saugūs ir higieniški. Kvarcas paprastesnis, nes neturi porų; granitas atleidžia karštį ir atsitiktinius smūgius. Šviesiai virtuvei su aktyviu gaminimu dažniau renkamas kvarcas, tamsiai ar natūraliai — granitas."}]},"pl":{"title":"Kwarc czy granit na blat: co lepsze w 2026 roku","h1":"Kwarc czy granit na blat kuchenny — co wybrać?","description":"Kwarc czy granit na blat? Porównujemy wytrzymałość, pielęgnację, odporność na ciepło, rysunek i cenę, aby dobrać materiał do Twojej kuchni.","dek":"Dwa najpopularniejsze materiały do kuchni: gdzie każdy wygrywa, a gdzie przegrywa.","intro":"Kwarc i granit zamykają większość zapytań o blat kuchenny, ale robią to inaczej. Granit to skała naturalna z unikalnym rysunkiem, która spokojnie znosi gorące naczynia i przez lata trzyma połysk. Kwarc to materiał inżynieryjny z piasku kwarcowego i żywicy: nieporowaty, powtarzalny w kolorze i prostszy w codziennej pielęgnacji. Poniżej rozkładamy różnicę na przykładach z naszej produkcji w Kostopolu.","sections":[{"heading":"Co wybrać — kwarc czy granit?","body":"Krótka odpowiedź: jeśli dużo gotujesz, stawiasz gorące bezpośrednio na blat i chcesz, by kuchnia miała naturalny charakter, wybierz granit. Jeśli ważniejszy jest jednolity kolor, całkowity brak porów i minimum pielęgnacji, a gorące i tak stawiasz na podkładce, wybierz kwarc.\n\nTo nie pytanie „lepsze czy gorsze”, lecz pytanie o scenariusz. Oba materiały służą dekady, oba są cięte, polerowane i montowane tą samą technologią. Różnica tkwi w zachowaniu podczas użytkowania i to właśnie warto zważyć przed zamówieniem."},{"heading":"Czym konglomerat kwarcowy różni się od granitu?","body":"Granit wydobywa się blokami ze złoża, przecina na sląby i poleruje. Wszystko, co widzisz na powierzchni, stworzyła natura: kryształy skalenia, kwarcu i miki, żyłki, wtrącenia. Dwa sląby z jednego bloku są podobne, ale nie identyczne.\n\nKonglomerat kwarcowy powstaje w fabryce: około 90–93 % mielonego kwarcu prasuje się z żywicą i pigmentami pod próżnią. Stąd główne właściwości: powierzchnia bez porów, stabilny kolor w partii, dekory „pod marmur” lub „pod beton”. Żywica wyznacza też ograniczenia: materiał nie lubi temperatur powyżej około 150 °C i nie jest przeznaczony na zewnątrz, bo ultrafiolet z czasem zmienia odcień."},{"heading":"Co jest mocniejsze i praktyczniejsze na co dzień?","body":"Pod względem twardości oba materiały są zbliżone: 6–7 w skali Mohsa, czyli nóż ich nie zarysuje. Różnica jest gdzie indziej. Na granicie można zapomnieć gorącą patelnię i nic się nie stanie. Na kwarcu gorące dno zostawia matowy ślad, którego nie da się wypolerować w domu, dlatego podkładka jest obowiązkowa.\n\nKwarc ma przewagę przy zlewie i w strefie gotowania: nie chłonie wody, oleju, wina ani soku z buraków. Granit z dobrą impregnacją zachowuje się niemal tak samo, ale impregnację trzeba okresowo odnawiać. Odpryski na narożnikach są możliwe w obu przypadkach i w obu naprawia się je na miejscu."},{"heading":"Co wymaga mniej pielęgnacji?","body":"Kwarc: miękka ściereczka, ciepła woda, w razie potrzeby środek neutralny. Żadnej impregnacji i woskowania. Jedyna zasada: bez środków ściernych i bez agresywnej chemii w rodzaju preparatów do piekarników.\n\nGranit: ta sama codzienna rutyna plus kontrola impregnacji raz na kilka miesięcy. Test jest prosty: kropla wody na powierzchni; jeśli po 10–15 minutach pojawi się pod nią ciemna plama, czas odnowić ochronę. Pokazujemy, jak to zrobić, przy odbiorze wyrobu."},{"heading":"Komu pasuje granit, a komu kwarc?","body":"Granit dla tych, którzy cenią naturalny rysunek i nie chcą myśleć o gorącym. Jest na miejscu w domach z dużą kuchnią, gdzie blat pracuje jak stół roboczy, i we wnętrzach, w których liczy się faktura kamienia.\n\nKwarc do jasnych kuchni w stylu minimalistycznym, do długich blatów bez widocznych spoin między jednakowymi płytami, dla rodzin, które chcą maksymalnie prostego użytkowania. Jest też wygodny, gdy kolor trzeba dokładnie dopasować do frontów: w katalogu są dziesiątki powtarzalnych dekorów Caesarstone, Vicostone i Silestone."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Porowatość","Kwarc nieporowaty","Granit wymaga impregnacji raz na 1–3 lata"],["Gorące","Kwarc tylko przez podkładkę","Granit znosi gorące naczynia"],["Rysunek","Kwarc powtarzalny","Granit unikalny, uzgadniaj sląb"],["Zewnątrz","Kwarc nie na zewnątrz","Granit nadaje się na tarasy i ganki"],["Naprawa","Oba naprawia się na miejscu","Połysk granitu odnawia się w pełni"]]},"faq":[{"question":"Czy granit trzeba impregnować?","answer":"Tak, polerowany granit impregnuje się środkiem ochronnym po montażu i powtarza zabieg według wyniku testu wodnego, zwykle raz na jeden–trzy lata. Zajmuje to pół godziny i nie wymaga fachowca."},{"question":"Czy kwarc boi się gorących naczyń?","answer":"Krótki kontakt z ciepłym garnkiem jest bezpieczny, ale patelnia z kuchenki lub blacha z piekarnika może zostawić matowy ślad z powodu żywicy w składzie. Używaj podkładki."},{"question":"Co jest droższe?","answer":"Zależy od konkretnego kamienia. Ukraińskie granity są zwykle tańsze od markowego kwarcu, a importowany granit w rzadkim kolorze może kosztować więcej. Porównaj swój wymiar w kalkulatorze."},{"question":"Co lepsze dla rodziny z dziećmi?","answer":"Oba warianty są bezpieczne i higieniczne. Kwarc jest prostszy, bo nie ma porów; granit wybacza gorące i przypadkowe uderzenia. Do jasnej kuchni z intensywnym gotowaniem częściej wybiera się kwarc, do ciemnej lub naturalnej — granit."}]}}'::jsonb) where slug = 'kvarc-chy-granit-stilnytsia';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Arbeitsplatte aus Quarzit Taj Mahal: Eigenschaften und Pflege","h1":"Quarzit Taj Mahal für die Arbeitsplatte — was man wissen sollte","description":"Quarzit Taj Mahal: natürliche Zeichnung, Härte, Hitze- und Fleckenbeständigkeit, Pflege. Wie man die Platte freigibt und die Arbeitsplatte kalkuliert.","dek":"Ein heller Naturquarzit, der wie Marmor aussieht und wie Granit funktioniert.","intro":"Taj Mahal ist ein brasilianischer Quarzit in cremebeigem Ton mit weichen goldenen Adern. Man wählt ihn statt Marmor, wenn man eine helle natürliche Oberfläche ohne Angst vor Zitrone und Wein möchte. Er ist eines der härtesten Naturmaterialien in unserem Katalog, aber mit einigen Nuancen, die man vor dem Zuschnitt kennen sollte.","sections":[{"heading":"Was ist Quarzit und worin unterscheidet er sich von Marmor?","body":"Quarzit ist ein metamorphes Gestein, das unter Druck und Temperatur aus Sandstein entstanden ist. Die Quarzkörner sind zu einer dichten Masse verwachsen, deshalb ist das Material hart, kratzfest und reagiert kaum auf Säuren. Äußerlich erinnert es durch wellige Adern oft an Marmor, und genau deshalb werden beide verwechselt.\n\nMarmor besteht aus Kalzit. Kalzit ist weich und löst sich in Säuren: Ein Tropfen Zitronensaft hinterlässt auf poliertem Marmor in wenigen Minuten einen matten Fleck. Quarzit verändert sich in derselben Situation nicht. Beide Steine fühlen sich kühl an, aber Quarzit lässt sich selbst mit einem Messer kaum zerkratzen."},{"heading":"Warum wählt man Taj Mahal statt Marmor?","body":"Der Hauptgrund ist Praktikabilität ohne Verlust an Optik. Der helle warme Ton und die ruhige Zeichnung lassen Küche oder Insel wie ein Marmorinterieur wirken, doch die Oberfläche hält tägliches Kochen aus. Das Material passt gut zu Holz, Messing und warmen Fronten.\n\nDer zweite Grund ist Stabilität. Taj Mahal wird in großen Blöcken gewonnen, daher messen die Platten etwa 3 × 1,8 m. Für lange Arbeitsplatten und Inseln bedeutet das weniger Fugen, und die Adern lassen sich bei einer verleimten 40-mm-Kante von der Fläche auf die Kante fortführen."},{"heading":"Wie fest und fleckenbeständig ist er?","body":"Die Härte von Taj Mahal liegt bei etwa 7 nach Mohs, das ist Granitniveau und darüber. Heißes Kochgeschirr schadet ihm nicht, Abplatzungen an Ecken sind bei richtigem Kantenprofil selten.\n\nZu Flecken: Quarzit hat Mikroporen, deshalb imprägnieren wir die Oberfläche nach der Montage immer. Ohne Imprägnierung können Öl oder Wein einen Schatten hinterlassen, mit Imprägnierung verhält sich die Oberfläche wie Quarz. Wichtig: Nicht alle Steine mit dem Namen „Quarzit“ sind gleich. Manche weichen Varianten enthalten Kalzit und verhalten sich wie Marmor, deshalb prüfen wir jede Platte vor dem Zuschnitt mit einem Säuretest am Rand."},{"heading":"Wie pflegt man Quarzit?","body":"Täglich: warmes Wasser, weiches Tuch, neutraler Steinreiniger. Verschüttetes sofort aufnehmen, besonders farbige Flüssigkeiten auf heller Fläche. Scheuerpulver und Metallschwämme sind unnötig und schaden der Politur.\n\nAlle sechs Monate einen Wassertest machen. Zieht der Tropfen in 10–15 Minuten ein, Imprägnierung erneuern: Das Mittel wird mit einem Schwamm aufgetragen, einwirken gelassen und trocken abgewischt. Eine matte (honed) Oberfläche wird häufiger imprägniert als eine polierte, weil sie offener ist."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Härte","Quarzit etwa 7 nach Mohs","Marmor 3–4, mit dem Messer zerkratzbar"],["Säuren","Taj Mahal beständig","Marmor verliert die Politur"],["Heißes","Verträgt Geschirr vom Herd","Marmor auch, dunkelt aber schneller nach"],["Pflege","Imprägnierung alle 1–2 Jahre","Marmor braucht schonende Chemie"],["Plattenmaß","Etwa 3 × 1,8 m","Weniger Fugen auf langer Platte"]]},"faq":[{"question":"Ist Quarzit natürlich oder künstlich?","answer":"Natürlich. Er wird oft mit Kunstquarz (Komposit) verwechselt, aber Quarzit wird in Blöcken aus dem Steinbruch gewonnen und nicht in der Fabrik hergestellt."},{"question":"Kann man Heißes abstellen?","answer":"Ja. Quarzit verträgt heißes Kochgeschirr ohne Folgen. Vorsicht gilt nur bei plötzlicher lokaler Erhitzung an einer verleimten Fuge, deshalb setzen wir neben dem Kochfeld keine Stöße."},{"question":"Dunkelt er durch Wasser nach?","answer":"Nicht imprägnierter Quarzit kann durch Wasser vorübergehend nachdunkeln wie Granit und ohne Spur trocknen. Nach der Imprägnierung bleibt Wasser als Tropfen auf der Oberfläche. Das ist der Test, ob der Schutz erneuert werden muss."},{"question":"Eignet er sich für eine Insel?","answer":"Er ist eine der besten Optionen für eine Insel: Das große Plattenformat erlaubt eine Arbeitsplatte von 2,5–3 m ohne Fugen, und eine verleimte Kante von 40–60 mm gibt eine massive Optik ohne zusätzliches Gewicht."}]},"en":{"title":"Taj Mahal quartzite countertop: properties and care","h1":"Taj Mahal quartzite for a countertop — what to know","description":"Taj Mahal quartzite: natural pattern, hardness, resistance to heat and stains, care. How to approve a slab and price a countertop.","dek":"A light natural quartzite that looks like marble and works like granite.","intro":"Taj Mahal is a Brazilian quartzite of a cream-beige tone with soft golden veins. It is chosen instead of marble when you want a light natural surface without fear of lemon and wine. It is one of the hardest natural materials in our catalogue, but with a few nuances worth knowing before cutting.","sections":[{"heading":"What is quartzite and how does it differ from marble?","body":"Quartzite is a metamorphic rock formed from sandstone under pressure and heat. The quartz grains have fused into a dense mass, so the material is hard, scratch-resistant and hardly reacts to acids. Outwardly it often resembles marble thanks to its wavy veins, which is exactly why the two are confused.\n\nMarble consists of calcite. Calcite is soft and dissolves in acids: a drop of lemon juice leaves a matte spot on polished marble within minutes. Quartzite in the same situation does not change. Both stones feel cold to the touch, but quartzite is harder to scratch even with a knife."},{"heading":"Why choose Taj Mahal instead of marble?","body":"The main reason is practicality without losing the look. The light warm tone and calm pattern make a kitchen or island resemble a marble interior, but the surface withstands daily cooking. The material pairs well with wood, brass and warm cabinet fronts.\n\nThe second reason is stability. Taj Mahal is quarried in large blocks, so slabs measure about 3 × 1.8 m. For long counters and islands this means fewer joints, and the veins can be continued from the top onto the edge with a 40 mm laminated edge."},{"heading":"How strong and stain-resistant is it?","body":"Taj Mahal''s hardness is around 7 on the Mohs scale, the level of granite and above. Hot pans do not harm it, and chips on corners are rare given a correct edge profile.\n\nAs for stains: quartzite has micropores, so after installation we always seal the surface. Without sealing, oil or wine can leave a shadow; with sealing the surface behaves like quartz. Important: not all stones called “quartzite” are the same. Some soft varieties contain calcite and behave like marble, so we check every slab with an acid test on the edge before cutting."},{"heading":"How do you care for quartzite?","body":"Daily: warm water, a soft cloth, a neutral stone cleaner. Wipe up spills right away, especially coloured liquids on a light surface. Abrasive powders and metal scourers are unnecessary and harmful to the polish.\n\nEvery six months do a water test. If a drop soaks in within 10–15 minutes, renew the sealant: apply it with a sponge, let it work and wipe dry. A honed finish is sealed more often than a polished one, because its surface is more open."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Hardness","Quartzite about 7 on Mohs","Marble 3–4, scratched by a knife"],["Acids","Taj Mahal is resistant","Marble loses its polish"],["Heat","Takes pans from the hob","Marble too, but darkens faster"],["Care","Sealing every 1–2 years","Marble needs gentle chemistry"],["Slab size","About 3 × 1.8 m","Fewer joints on a long counter"]]},"faq":[{"question":"Is quartzite natural or artificial?","answer":"Natural. It is often confused with engineered quartz, but quartzite is quarried in blocks, not made in a factory."},{"question":"Can I put hot things on it?","answer":"Yes. Quartzite takes hot pans without consequences. The only caution concerns sudden local heating at a glued joint, which is why we do not place joints next to the hob."},{"question":"Does it darken from water?","answer":"Unsealed quartzite can temporarily darken from water, like granite, and dry without a trace. After sealing, water stays as a drop on the surface. That is the test for whether the protection needs renewing."},{"question":"Is it suitable for an island?","answer":"It is one of the best options for an island: the large slab format allows a 2.5–3 m counter without joints, and a 40–60 mm laminated edge gives a massive look without extra weight."}]},"lt":{"title":"Stalviršis iš kvarcito Taj Mahal: savybės ir priežiūra","h1":"Kvarcitas Taj Mahal stalviršiui — ką verta žinoti","description":"Kvarcitas Taj Mahal: natūralus raštas, kietumas, atsparumas karščiui ir dėmėms, priežiūra. Kaip suderinti plokštę ir apskaičiuoti stalviršį.","dek":"Šviesus natūralus kvarcitas, kuris atrodo kaip marmuras, o dirba kaip granitas.","intro":"Taj Mahal — braziliškas kreminio smėlinio tono kvarcitas su švelniomis auksinėmis gyslomis. Jį renkasi vietoj marmuro, kai norisi šviesaus natūralaus paviršiaus be baimės dėl citrinos ir vyno. Tai viena kiečiausių natūralių medžiagų mūsų kataloge, bet su keliais niuansais, kuriuos verta žinoti prieš pjaustymą.","sections":[{"heading":"Kas yra kvarcitas ir kuo jis skiriasi nuo marmuro?","body":"Kvarcitas — metamorfinė uoliena, susidariusi iš smiltainio veikiant slėgiui ir temperatūrai. Kvarco grūdeliai suaugo į tankią masę, todėl medžiaga kieta, atspari įbrėžimams ir beveik nereaguoja į rūgštis. Išoriškai jis dažnai primena marmurą dėl banguotų gyslų, ir būtent todėl juos painioja.\n\nMarmuras sudarytas iš kalcito. Kalcitas minkštas ir tirpsta rūgštyse: citrinos sulčių lašas per kelias minutes palieka ant poliruoto marmuro matinę dėmę. Kvarcitas tokioje pat situacijoje nesikeičia. Liečiant abu akmenys šalti, bet kvarcitą sunkiau subraižyti net peiliu."},{"heading":"Kodėl Taj Mahal renkasi vietoj marmuro?","body":"Pagrindinė priežastis — praktiškumas neprarandant išvaizdos. Šviesus šiltas tonas ir ramus raštas daro virtuvę ar salą panašią į marmurinį interjerą, bet paviršius atlaiko kasdienį gaminimą. Medžiaga gerai derinasi su mediena, žalvariu ir šiltais fasadais.\n\nAntra priežastis — stabilumas. Taj Mahal kasamas dideliais blokais, todėl plokštės yra apie 3 × 1,8 m. Ilgiems stalviršiams ir saloms tai reiškia mažiau siūlių, o gyslas galima pratęsti iš horizontalės į kraštą su suklijuotu 40 mm kraštu."},{"heading":"Kiek jis tvirtas ir atsparus dėmėms?","body":"Taj Mahal kietumas — apie 7 pagal Mosą, tai granito lygis ir aukščiau. Karšti indai jam nekenkia, nuskilimai kampuose pasitaiko retai, jei krašto profilis teisingas.\n\nDėl dėmių: kvarcitas turi mikroporų, todėl po montavimo būtinai impregnuojame paviršių. Be impregnavimo aliejus ar vynas gali palikti šešėlį, su impregnavimu paviršius elgiasi kaip kvarcas. Svarbu: ne visi akmenys, vadinami „kvarcitu“, vienodi. Kai kurios minkštos atmainos turi kalcito ir elgiasi kaip marmuras, todėl kiekvieną plokštę prieš pjaustymą tikriname rūgšties testu plokštės krašte."},{"heading":"Kaip prižiūrėti kvarcitą?","body":"Kasdien: šiltas vanduo, minkšta šluostė, neutrali akmens priemonė. Išsipylusius skysčius nuvalykite iš karto, ypač spalvotus ant šviesaus paviršiaus. Abrazyviniai milteliai ir metalinės kempinės nereikalingi ir kenkia poliravimui.\n\nKartą per pusmetį darykite vandens testą. Jei lašas įsigeria per 10–15 minučių, atnaujinkite impregnavimą: priemonė tepama kempine, palaikoma ir nušluostoma sausai. Matinė (honed) apdaila impregnuojama dažniau nei poliruota, nes jos paviršius atviresnis."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Kietumas","Kvarcitas apie 7 pagal Mosą","Marmuras 3–4, braižomas peiliu"],["Rūgštys","Taj Mahal atsparus","Marmuras praranda poliravimą"],["Karštis","Atlaiko indus nuo viryklės","Marmuras taip pat, bet greičiau tamsėja"],["Priežiūra","Impregnavimas kartą per 1–2 metus","Marmurui reikia švelnios chemijos"],["Plokštės dydis","Apie 3 × 1,8 m","Mažiau siūlių ilgame stalviršyje"]]},"faq":[{"question":"Kvarcitas natūralus ar dirbtinis?","answer":"Natūralus. Jį dažnai painioja su dirbtiniu kvarcu (aglomeratu), bet kvarcitas kasamas iš karjero blokais, o ne gaminamas gamykloje."},{"question":"Ar galima statyti karštus indus?","answer":"Taip. Kvarcitas atlaiko karštus indus be pasekmių. Vienintelis atsargumas — dėl staigaus vietinio įkaitimo suklijuotos siūlės vietoje, todėl prie kaitlentės siūlių nedarome."},{"question":"Ar tamsėja nuo vandens?","answer":"Neimpregnuotas kvarcitas gali laikinai patamsėti nuo vandens, kaip ir granitas, ir išdžiūti be pėdsakų. Po impregnavimo vanduo lieka lašu ant paviršiaus. Tai ir yra testas, ar reikia atnaujinti apsaugą."},{"question":"Ar tinka salai?","answer":"Tai vienas geriausių variantų salai: didelis plokštės formatas leidžia pagaminti 2,5–3 m stalviršį be siūlių, o suklijuotas 40–60 mm kraštas suteikia masyvią išvaizdą be papildomo svorio."}]},"pl":{"title":"Blat z kwarcytu Taj Mahal: właściwości i pielęgnacja","h1":"Kwarcyt Taj Mahal na blat — co warto wiedzieć","description":"Kwarcyt Taj Mahal: naturalny rysunek, twardość, odporność na ciepło i plamy, pielęgnacja. Jak uzgodnić sląb i wyliczyć blat.","dek":"Jasny naturalny kwarcyt, który wygląda jak marmur, a pracuje jak granit.","intro":"Taj Mahal to brazylijski kwarcyt w kremowo-beżowym tonie z miękkimi złocistymi żyłkami. Wybiera się go zamiast marmuru, gdy chce się jasnej naturalnej powierzchni bez strachu przed cytryną i winem. To jeden z najtwardszych materiałów naturalnych w naszym katalogu, ale z kilkoma niuansami, które warto znać przed rozkrojem.","sections":[{"heading":"Czym jest kwarcyt i czym różni się od marmuru?","body":"Kwarcyt to skała metamorficzna, która powstała z piaskowca pod ciśnieniem i w wysokiej temperaturze. Ziarna kwarcu zrosły się w gęstą masę, dlatego materiał jest twardy, odporny na zarysowania i prawie nie reaguje na kwasy. Z wyglądu często przypomina marmur dzięki falistym żyłkom i właśnie dlatego bywa z nim mylony.\n\nMarmur składa się z kalcytu. Kalcyt jest miękki i rozpuszcza się w kwasach: kropla soku z cytryny zostawia na polerowanym marmurze matową plamę w kilka minut. Kwarcyt w tej samej sytuacji się nie zmienia. W dotyku oba kamienie są chłodne, ale kwarcyt trudniej zarysować nawet nożem."},{"heading":"Dlaczego Taj Mahal wybiera się zamiast marmuru?","body":"Główny powód to praktyczność bez utraty wyglądu. Jasny ciepły ton i spokojny rysunek sprawiają, że kuchnia lub wyspa wyglądają jak marmurowe wnętrze, ale powierzchnia wytrzymuje codzienne gotowanie. Materiał dobrze łączy się z drewnem, mosiądzem i ciepłymi frontami.\n\nDrugi powód to stabilność. Taj Mahal wydobywa się dużymi blokami, więc sląby mają wymiar około 3 × 1,8 m. Dla długich blatów i wysp oznacza to mniej spoin, a żyłki można poprowadzić z płaszczyzny na krawędź przy klejonej krawędzi 40 mm."},{"heading":"Jak bardzo jest mocny i odporny na plamy?","body":"Twardość Taj Mahal to około 7 w skali Mohsa, czyli poziom granitu i wyżej. Gorące naczynia mu nie szkodzą, odpryski na narożnikach zdarzają się rzadko przy prawidłowym profilu krawędzi.\n\nCo do plam: kwarcyt ma mikropory, dlatego po montażu obowiązkowo impregnujemy powierzchnię. Bez impregnacji olej lub wino mogą zostawić cień, z impregnacją powierzchnia zachowuje się jak kwarc. Ważne: nie wszystkie kamienie o nazwie „kwarcyt” są jednakowe. Niektóre miękkie odmiany zawierają kalcyt i zachowują się jak marmur, dlatego każdy sląb sprawdzamy testem kwasowym na brzegu płyty przed rozkrojem."},{"heading":"Jak pielęgnować kwarcyt?","body":"Codziennie: ciepła woda, miękka ściereczka, neutralny środek do kamienia. Rozlane sprzątaj od razu, zwłaszcza kolorowe płyny na jasnej powierzchni. Proszki ścierne i metalowe gąbki nie są potrzebne i szkodzą połyskowi.\n\nRaz na pół roku zrób test wodny. Jeśli kropla wsiąka w 10–15 minut, odnów impregnację: środek nanosi się gąbką, odczekuje i wyciera do sucha. Wykończenie matowe (honed) impregnuje się częściej niż polerowane, bo jego powierzchnia jest bardziej otwarta."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Twardość","Kwarcyt około 7 w skali Mohsa","Marmur 3–4, rysuje się nożem"],["Kwasy","Taj Mahal odporny","Marmur traci połysk"],["Gorące","Wytrzymuje naczynia z kuchenki","Marmur też, ale szybciej ciemnieje"],["Pielęgnacja","Impregnacja raz na 1–2 lata","Marmur wymaga delikatnej chemii"],["Wymiar sląba","Około 3 × 1,8 m","Mniej spoin na długim blacie"]]},"faq":[{"question":"Kwarcyt jest naturalny czy sztuczny?","answer":"Naturalny. Często myli się go ze sztucznym kwarcem (konglomeratem), ale kwarcyt wydobywa się z kamieniołomu blokami, a nie produkuje w fabryce."},{"question":"Czy można stawiać gorące?","answer":"Tak. Kwarcyt wytrzymuje gorące naczynia bez konsekwencji. Jedyna ostrożność dotyczy gwałtownego miejscowego nagrzania w miejscu klejonej spoiny, dlatego przy płycie grzewczej nie robimy łączeń."},{"question":"Czy ciemnieje od wody?","answer":"Niezaimpregnowany kwarcyt może przejściowo ciemnieć od wody, jak granit, i schnąć bez śladu. Po impregnacji woda zostaje kroplą na powierzchni. To właśnie test na potrzebę odnowienia ochrony."},{"question":"Czy nadaje się na wyspę?","answer":"To jeden z najlepszych wariantów na wyspę: duży format sląba pozwala zrobić blat 2,5–3 m bez spoin, a klejona krawędź 40–60 mm daje masywny wygląd bez zbędnej wagi."}]}}'::jsonb) where slug = 'stilnytsia-z-kvarcytu-taj-mahal';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Dicke der Steinarbeitsplatte: 20 oder 30 mm?","h1":"Welche Plattendicke wählen — 20 oder 30 mm?","description":"20 oder 30 mm für die Steinarbeitsplatte: Steifigkeit, Gewicht, Überstände, Kantenoptik und Kosten. Wann 20 mm genügen und wie man eine dicke Kante macht.","dek":"Dicke als konstruktive und optische Entscheidung für die Arbeitsplatte.","intro":"Der meiste Naturstein in der Ukraine wird in Platten von 20 und 30 mm verkauft, Quarz in 20 und 30 mm, Feinsteinzeug in 6, 12 und 20 mm. Die Dicke bestimmt nicht nur die Kantenoptik, sondern auch Gewicht, zulässige Überstände, Anforderungen an den Küchenkorpus und den Preis. Wir erklären, wie wir die Dicke in der Fertigung wählen und wann eine „dünne“ Platte tatsächlich besser ist.","sections":[{"heading":"Welche Dicke ist optimal?","body":"Für eine Küchenarbeitsplatte auf Standardschränken mit 600 mm Tiefe sind 20 mm optimal. Diese Dicke reicht für Festigkeit, Ausschnitte für Spüle und Kochfeld, und das Gewicht bleibt moderat: etwa 55 kg pro laufenden Meter bei Granit.\n\n30 mm wählt man aus zwei Gründen: konstruktiv (lange Überstände, Treppen, Außendetails, schwere Spülen auf breiten Spannweiten) oder optisch (massive Kante ohne Verleimung). Geht es nur um die Optik, ist es günstiger und leichter, 20 mm mit einer verleimten Kante bis 40–60 mm zu machen."},{"heading":"Wovon hängt die Plattendicke ab?","body":"Vom Material, den Spannweiten zwischen den Auflagern und davon, was auf der Platte stehen wird. Granit und Quarzit sind steif, Quarz ist elastischer und funktioniert bei 20 mm auch mit langen Überständen gut. Marmor ist weicher, deshalb bevorzugen wir bei breiten Spannweiten 30 mm oder verstärken 20 mm von unten mit einem Aluminiumprofil.\n\nAuch die Auflager zählen: durchgehende Schrankoberseite oder nur ein Rahmen, gibt es eine Barkonsole ohne Beine, sind Einbaugeräte mit Ausschnitt direkt an der Kante geplant. Jeder Ausschnitt schwächt die Platte, und der Steg daneben darf nicht schmaler als 50–70 mm sein."},{"heading":"Worin unterscheiden sich 20 mm von 30 mm?","body":"Gewicht: 30 mm sind anderthalbmal schwerer. Bei einer langen Insel sind das mehrere Dutzend Kilogramm, die der Korpus tragen und die ohne Aufzug ins Stockwerk müssen.\n\nÜberstände: Ohne Verstärkung erlauben 20 mm eine Auskragung von etwa 250–300 mm, 30 mm bis 350–400 mm. Für größere Barüberstände braucht es Stahlplatten in Nuten oder Konsolen.\n\nOptik: Eine 30-mm-Kante wirkt massiv, 20 mm leicht und modern. Das Kantenprofil bei 30 mm hat mehr Varianten: Halbrund, Ogee, Vollrund."},{"heading":"Wie beeinflusst die Dicke Optik und Kosten?","body":"Eine 30-mm-Platte kostet mehr als 20 mm, und die Kantenbearbeitung an der dicken Platte dauert länger. Bei den meisten Küchen beträgt der Unterschied im Gesamtpreis 20 bis 40 %, deshalb schlagen wir 30 mm nur dort vor, wo die Konstruktion es rechtfertigt.\n\nEine verleimte 40-mm-Kante aus 20-mm-Material gibt die Optik einer dicken Platte für weniger Geld und Gewicht. Bei richtigem Zuschnitt ist die Fuge fast unsichtbar, besonders bei gleichmäßigen Materialien und Quarz. Bei Steinen mit ausgeprägten Adern wählen wir den Streifen aus derselben Zone der Platte, damit die Zeichnung weiterläuft."},{"heading":"Was ist bei Kochfeld und Spüle zu beachten?","body":"Eine Unterbauspüle hängen wir mit Halterungen an die Platte, deshalb lassen wir um den Ausschnitt mindestens 60 mm Stein bis zur Kante und runden die Ecken mit 10–15 mm Radius, um Spannungen abzubauen. Diese Regel gilt für 20 und 30 mm gleich.\n\nKochfeld: Der Ausschnitt muss 50–70 mm von der Hinterkante entfernt sein, und zwischen Kochfeld und Spüle braucht es ein durchgehendes Stück von mindestens 300 mm, sonst muss die Platte geteilt werden. Bei Induktion prüfen wir zusätzlich die Tiefe des Schranks darunter, damit das Gehäuse nicht am Rahmen anstößt."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Steifigkeit","20 mm für Küche, 30 mm für Treppen","Abhängig von Auflagern und Gestein"],["Gewicht","Etwa 55 und 80 kg pro lfm Granit","Korpus und Transport prüfen"],["Überstände ohne Auflager","20 mm bis 300 mm, 30 mm bis 400 mm","Darüber Verstärkung nötig"],["Optik","Leichte oder massive Kante","Verleimte Kante 40–60 mm"],["Kosten","30 mm 20–40 % teurer","Material und Kantenbearbeitung"]]},"faq":[{"question":"Reichen 20 mm für die Küche?","answer":"Ja, in den allermeisten Küchen sind 20 mm Standard: Sie tragen Spüle, Kochfeld und die tägliche Belastung. 30 mm braucht es für lange Konsolen oder einen massiven Stil."},{"question":"Wie wird eine dicke Kante gemacht?","answer":"An die Unterseite der 20-mm-Platte wird ein Streifen desselben Steins geklebt, die Kante poliert, und es entsteht ein 40-mm-Rand. Die Fuge verläuft an der Unterkante und ist auf Augenhöhe nicht sichtbar."},{"question":"Was passt besser zum Minimalismus?","answer":"Für eine dünne moderne Optik wählt man 20 mm oder Feinsteinzeug 12 mm mit gerader Kante. Für einen „schweren“ skandinavischen oder Loft-Stil 30 mm oder verleimte 60 mm."},{"question":"Ist eine Sonderdicke möglich?","answer":"Ja: Durch Verleimen von zwei oder drei Lagen erhält man Kanten von 60, 80 und sogar 100 mm. Die Platte selbst bleibt 20 mm dick, das Gewicht wächst also nicht proportional."}]},"en":{"title":"Stone countertop thickness: 20 or 30 mm?","h1":"Which countertop thickness to choose — 20 or 30 mm?","description":"20 or 30 mm for a stone countertop: rigidity, weight, overhangs, edge look and cost. When 20 mm is enough and how to make a thick edge.","dek":"Thickness as a structural and visual decision for a countertop.","intro":"Most natural stone in Ukraine is sold in 20 and 30 mm slabs, quartz in 20 and 30 mm, porcelain in 6, 12 and 20 mm. Thickness determines not only the look of the edge but also weight, permissible overhangs, requirements for the kitchen carcass and price. We explain how we choose thickness in the workshop and when a “thin” countertop is actually better.","sections":[{"heading":"Which thickness is optimal?","body":"For a kitchen countertop on standard 600 mm deep units, 20 mm is optimal. That thickness is enough for strength, cut-outs for the sink and hob, and the weight stays moderate: about 55 kg per linear metre for granite.\n\n30 mm is chosen for two reasons: structural (long overhangs, stairs, exterior details, heavy sinks on wide spans) or visual (a massive edge without lamination). If only the look is needed, it is cheaper and lighter to make 20 mm with a laminated edge of up to 40–60 mm."},{"heading":"What does countertop thickness depend on?","body":"On the material, the spans between supports and what will stand on the counter. Granite and quartzite are rigid, quartz is more flexible and works well at 20 mm even with long overhangs. Marble is softer, so on wide spans we prefer 30 mm or reinforce 20 mm with an aluminium profile underneath.\n\nThe supports matter too: a solid top on the units or just a frame, whether there is a bar console without legs, whether built-in appliances with a cut-out right at the edge are planned. Every cut-out weakens the slab, and the bridge next to it must be no narrower than 50–70 mm."},{"heading":"How does 20 mm differ from 30 mm?","body":"Weight: 30 mm is one and a half times heavier. For a long island that is a difference of several tens of kilograms that the carcass must bear and that must be carried upstairs without a lift.\n\nOverhangs: without reinforcement 20 mm safely gives a cantilever of about 250–300 mm, 30 mm — up to 350–400 mm. Bar overhangs beyond that need steel plates in grooves or brackets.\n\nLook: a 30 mm edge reads as massive, 20 mm as light and modern. The edge profile on 30 mm has more options: half bullnose, ogee, full bullnose."},{"heading":"How does thickness affect the look and cost?","body":"A 30 mm slab costs more than 20 mm, and edge work on a thick slab takes longer. For most kitchens the difference in the final estimate is 20 to 40 %, so we offer 30 mm only where the structure justifies it.\n\nA 40 mm laminated edge from 20 mm material gives the look of a thick slab for less money and weight. With correct cutting the joint is almost invisible, especially on uniform materials and quartz. On stones with pronounced veins we select a strip from the same zone of the slab so the pattern continues."},{"heading":"What to consider for the hob and sink?","body":"We hang an undermount sink from the slab on brackets, so around the cut-out we leave at least 60 mm of stone to the edge and round the corners with a 10–15 mm radius to relieve stress. This rule is the same for 20 and 30 mm.\n\nHob: the cut-out must be set back 50–70 mm from the rear edge, and between the hob and the sink a solid section of at least 300 mm is needed, otherwise the slab has to be split. For induction we additionally check the depth of the unit under it so the body does not press against the frame."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Rigidity","20 mm for kitchens, 30 mm for stairs","Depends on supports and rock"],["Weight","About 55 and 80 kg per lin. m of granite","Check the carcass and the carry-in"],["Unsupported overhangs","20 mm up to 300 mm, 30 mm up to 400 mm","Beyond that, reinforcement is needed"],["Look","Light or massive edge","Laminated edge 40–60 mm"],["Cost","30 mm is 20–40 % more expensive","Material and edge work"]]},"faq":[{"question":"Is 20 mm enough for a kitchen?","answer":"Yes, in the vast majority of kitchens 20 mm is the standard: it takes the sink, the hob and daily load. 30 mm is needed for long consoles or a massive style."},{"question":"How is a thick edge made?","answer":"A strip of the same stone is glued to the underside of the 20 mm slab, the edge is polished and you get a 40 mm edge. The joint runs along the bottom edge and is not visible at eye level."},{"question":"What is better for minimalism?","answer":"For a thin modern look choose 20 mm or 12 mm porcelain with a straight edge. For a “heavy” Scandinavian or loft style — 30 mm or laminated 60 mm."},{"question":"Is a non-standard thickness possible?","answer":"Yes: by laminating two or three layers you get an edge of 60, 80 or even 100 mm. The slab itself stays 20 mm, so the weight does not grow proportionally."}]},"lt":{"title":"Akmens stalviršio storis: 20 ar 30 mm?","h1":"Kokį stalviršio storį rinktis — 20 ar 30 mm?","description":"20 ar 30 mm akmens stalviršiui: standumas, svoris, iškyšos, krašto išvaizda ir kaina. Kada pakanka 20 mm ir kaip padaryti storą kraštą.","dek":"Storis kaip konstrukcinis ir vizualinis stalviršio sprendimas.","intro":"Dauguma natūralaus akmens Ukrainoje parduodama 20 ir 30 mm plokštėmis, kvarcas — 20 ir 30 mm, keraminis granitas — 6, 12 ir 20 mm. Storis lemia ne tik krašto išvaizdą, bet ir svorį, leistinas iškyšas, reikalavimus virtuvės karkasui ir kainą. Pasakojame, kaip storį renkame gamyboje ir kada „plonas“ stalviršis iš tikrųjų geresnis.","sections":[{"heading":"Koks storis optimalus?","body":"Virtuvės stalviršiui ant standartinių 600 mm gylio modulių optimalūs 20 mm. Tokio storio pakanka tvirtumui, išpjovoms plautuvei ir kaitlentei, o svoris lieka vidutinis: apie 55 kg vienam granito metrui.\n\n30 mm renkasi dėl dviejų priežasčių: konstrukcinės (ilgos iškyšos, laiptai, išorės detalės, sunkios plautuvės plačiuose tarpuose) arba vizualinės (masyvus kraštas be klijavimo). Jei reikia tik išvaizdos, pigiau ir lengviau padaryti 20 mm su suklijuotu kraštu iki 40–60 mm."},{"heading":"Nuo ko priklauso stalviršio storis?","body":"Nuo medžiagos, tarpų tarp atramų ir to, kas stovės ant stalviršio. Granitas ir kvarcitas standūs, kvarcas lankstesnis ir gerai dirba 20 mm net su ilgomis iškyšomis. Marmuras minkštesnis, todėl plačiuose tarpuose teikiame pirmenybę 30 mm arba sustipriname 20 mm aliuminio profiliu iš apačios.\n\nSvarbios ir atramos: vientisas modulių paviršius ar tik rėmas, ar yra baro konsolė be kojų, ar planuojama įmontuojama technika su išpjova prie pat krašto. Kiekviena išpjova silpnina plokštę, ir tiltelis šalia jos neturi būti siauresnis nei 50–70 mm."},{"heading":"Kuo 20 mm skiriasi nuo 30 mm?","body":"Svoris: 30 mm pusantro karto sunkesni. Ilgai salai tai kelių dešimčių kilogramų skirtumas, kurį turi atlaikyti karkasas ir kurį reikia užkelti į aukštą be lifto.\n\nIškyšos: be sustiprinimo 20 mm saugiai leidžia apie 250–300 mm konsolę, 30 mm — iki 350–400 mm. Baro iškyšoms, didesnėms už tai, reikia plieninių plokštelių grioveliuose arba laikiklių.\n\nIšvaizda: 30 mm kraštas skaitomas kaip masyvus, 20 mm — kaip lengvas ir modernus. Krašto profilis 30 mm turi daugiau variantų: pusapvalis, ogee, pilnas apvalinimas."},{"heading":"Kaip storis veikia išvaizdą ir kainą?","body":"30 mm plokštė kainuoja brangiau nei 20 mm, o krašto apdirbimas storoje plokštėje trunka ilgiau. Daugumai virtuvių skirtumas galutinėje sąmatoje siekia 20–40 %, todėl 30 mm siūlome tik ten, kur tai pateisina konstrukcija.\n\nSuklijuotas 40 mm kraštas iš 20 mm medžiagos suteikia storos plokštės išvaizdą už mažesnę kainą ir svorį. Siūlė teisingai pjaustant beveik nematoma, ypač vienalytėse medžiagose ir kvarce. Akmenyse su ryškiomis gyslomis parenkame juostelę iš tos pačios plokštės zonos, kad raštas tęstųsi."},{"heading":"Į ką atsižvelgti dėl kaitlentės ir plautuvės?","body":"Apatinio montavimo plautuvę kabiname prie plokštės tvirtinimais, todėl aplink išpjovą paliekame ne mažiau kaip 60 mm akmens iki krašto ir suapvaliname kampus 10–15 mm spinduliu, kad sumažintume įtempius. Ši taisyklė vienoda 20 ir 30 mm.\n\nKaitlentė: išpjova turi būti atitraukta nuo užpakalinio krašto 50–70 mm, o tarp kaitlentės ir plautuvės reikia vientiso ne mažiau kaip 300 mm fragmento, kitaip plokštę teks dalyti. Indukcijai papildomai tikriname modulio gylį po ja, kad korpusas neatsiremtų į karkasą."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Standumas","20 mm virtuvei, 30 mm laiptams","Priklauso nuo atramų ir uolienos"],["Svoris","Apie 55 ir 80 kg granito metrui","Patikrinti karkasą ir užkėlimą"],["Iškyšos be atramų","20 mm iki 300 mm, 30 mm iki 400 mm","Toliau reikia sustiprinimo"],["Išvaizda","Lengvas arba masyvus kraštas","Suklijuotas kraštas 40–60 mm"],["Kaina","30 mm 20–40 % brangiau","Medžiaga ir krašto apdirbimas"]]},"faq":[{"question":"Ar pakanka 20 mm virtuvei?","answer":"Taip, daugumoje virtuvių 20 mm yra standartas: atlaiko plautuvę, kaitlentę ir kasdienę apkrovą. 30 mm reikia ilgoms konsolėms arba masyviam stiliui."},{"question":"Kaip daromas storas kraštas?","answer":"Prie 20 mm plokštės apatinės dalies priklijuojama to paties akmens juostelė, kraštas nupoliruojamas ir gaunamas 40 mm kraštas. Siūlė eina per apatinę briauną ir iš akių aukščio nematoma."},{"question":"Kas geriau minimalizmui?","answer":"Plonai moderniai išvaizdai renkasi 20 mm arba 12 mm keraminį granitą su tiesiu kraštu. „Sunkiam“ skandinaviškam ar loft stiliui — 30 mm arba suklijuotus 60 mm."},{"question":"Ar galimas nestandartinis storis?","answer":"Taip: suklijavus du ar tris sluoksnius gaunamas 60, 80 ir net 100 mm kraštas. Pačios plokštės storis lieka 20 mm, todėl svoris neauga proporcingai."}]},"pl":{"title":"Grubość blatu z kamienia: 20 czy 30 mm?","h1":"Jaką grubość blatu wybrać — 20 czy 30 mm?","description":"20 czy 30 mm na blat kamienny: sztywność, waga, nawisy, wygląd krawędzi i koszt. Kiedy wystarczy 20 mm i jak zrobić grubą krawędź.","dek":"Grubość jako decyzja konstrukcyjna i wizualna dla blatu.","intro":"Większość kamienia naturalnego w Ukrainie sprzedaje się w sląbach 20 i 30 mm, kwarc — 20 i 30 mm, gres — 6, 12 i 20 mm. Grubość określa nie tylko wygląd krawędzi, ale i wagę, dopuszczalne nawisy, wymagania wobec korpusu kuchni i cenę. Opowiadamy, jak dobieramy grubość na produkcji i kiedy „cienki” blat jest naprawdę lepszy.","sections":[{"heading":"Jaka grubość jest optymalna?","body":"Dla blatu kuchennego na standardowych szafkach o głębokości 600 mm optymalne jest 20 mm. Taka grubość wystarcza dla wytrzymałości, wycięć pod zlew i płytę grzewczą, a waga pozostaje umiarkowana: około 55 kg na metr bieżący granitu.\n\n30 mm wybiera się z dwóch powodów: konstrukcyjnego (długie nawisy, schody, detale zewnętrzne, ciężkie zlewy na szerokich rozpiętościach) lub wizualnego (masywna krawędź bez klejenia). Jeśli chodzi tylko o wygląd, taniej i lżej zrobić 20 mm z klejoną krawędzią do 40–60 mm."},{"heading":"Od czego zależy grubość blatu?","body":"Od materiału, rozpiętości między podporami i tego, co na blacie będzie stać. Granit i kwarcyt są sztywne, kwarc bardziej elastyczny i dobrze pracuje w 20 mm nawet z długimi nawisami. Marmur jest miększy, dlatego na szerokich rozpiętościach wolimy 30 mm lub wzmacniamy 20 mm profilem aluminiowym od spodu.\n\nWażne są też podpory: pełna powierzchnia szafek czy tylko rama, czy jest konsola barowa bez nóg, czy planowany jest sprzęt do zabudowy z wycięciem tuż przy krawędzi. Każde wycięcie osłabia płytę, a mostek obok niego nie może być węższy niż 50–70 mm."},{"heading":"Czym 20 mm różni się od 30 mm?","body":"Waga: 30 mm jest półtora raza cięższe. Dla długiej wyspy to różnica kilkudziesięciu kilogramów, które musi wytrzymać korpus i które trzeba wnieść na piętro bez windy.\n\nNawisy: bez wzmocnienia 20 mm bezpiecznie daje konsolę około 250–300 mm, 30 mm — do 350–400 mm. Dla nawisów barowych większych niż to potrzebne są stalowe płaskowniki w rowkach lub wsporniki.\n\nWygląd: krawędź 30 mm czyta się jako masywna, 20 mm jako lekka i nowoczesna. Profil krawędzi przy 30 mm ma więcej wariantów: półokrągły, ogee, pełny promień."},{"heading":"Jak grubość wpływa na wygląd i koszt?","body":"Sląb 30 mm kosztuje więcej niż 20 mm, a obróbka krawędzi na grubej płycie trwa dłużej. Dla większości kuchni różnica w końcowym kosztorysie wynosi od 20 do 40 %, dlatego 30 mm proponujemy tylko tam, gdzie uzasadnia to konstrukcja.\n\nKlejona krawędź 40 mm z materiału 20 mm daje wygląd grubej płyty za mniejszą cenę i wagę. Spoina przy prawidłowym rozkroju jest prawie niewidoczna, zwłaszcza na materiałach jednolitych i kwarcu. Na kamieniach z wyraźnymi żyłkami dobieramy pasek z tej samej strefy sląba, aby rysunek był kontynuowany."},{"heading":"Co uwzględnić przy płycie grzewczej i zlewie?","body":"Zlew podwieszany mocujemy do płyty na uchwytach, dlatego wokół wycięcia pozostawiamy nie mniej niż 60 mm kamienia do krawędzi i zaokrąglamy narożniki promieniem 10–15 mm, aby zdjąć naprężenia. Ta zasada jest taka sama dla 20 i 30 mm.\n\nPłyta grzewcza: wycięcie musi być odsunięte od tylnej krawędzi o 50–70 mm, a między płytą i zlewem potrzebny jest pełny fragment co najmniej 300 mm, inaczej blat trzeba dzielić. Przy indukcji dodatkowo sprawdzamy głębokość szafki pod nią, aby korpus nie opierał się o ramę."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Sztywność","20 mm do kuchni, 30 mm na schody","Zależy od podpór i skały"],["Waga","Około 55 i 80 kg na m.b. granitu","Sprawdzić korpus i wnoszenie"],["Nawisy bez podpór","20 mm do 300 mm, 30 mm do 400 mm","Dalej potrzebne wzmocnienie"],["Wygląd","Lekka lub masywna krawędź","Klejona krawędź 40–60 mm"],["Koszt","30 mm o 20–40 % drożej","Materiał i obróbka krawędzi"]]},"faq":[{"question":"Czy 20 mm wystarczy do kuchni?","answer":"Tak, w zdecydowanej większości kuchni 20 mm to standard: wytrzymuje zlew, płytę grzewczą i codzienne obciążenie. 30 mm potrzebne jest do długich konsol lub masywnego stylu."},{"question":"Jak robi się grubą krawędź?","answer":"Do dolnej części płyty 20 mm przykleja się pasek z tego samego kamienia, poleruje krawędź i wychodzi brzeg 40 mm. Spoina przebiega po dolnej krawędzi i z wysokości oczu jej nie widać."},{"question":"Co lepsze do minimalizmu?","answer":"Dla cienkiego nowoczesnego wyglądu wybiera się 20 mm lub gres 12 mm z prostą krawędzią. Dla „ciężkiego” stylu skandynawskiego lub loftowego — 30 mm albo klejone 60 mm."},{"question":"Czy można niestandardową grubość?","answer":"Tak: przez sklejenie dwóch lub trzech warstw uzyskuje się krawędź 60, 80 a nawet 100 mm. Grubość samej płyty pozostaje 20 mm, więc waga nie rośnie proporcjonalnie."}]}}'::jsonb) where slug = 'tovshchyna-stilnytsi-20-30-mm';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Ukrainische Granite: Vergleich der Sorten und Farben","h1":"Ukrainische Granite — welcher passt zu Ihrem Projekt","description":"Überblick über ukrainische Granite: Pokostivka, Gabbro, Labradorit, Maple Red, Rosso Santiago und andere. Farben, Eigenschaften, Strahlungsklasse, Anwendung.","dek":"Zehn ukrainische Gesteine für Interieur, Fassade und Landschaft.","intro":"Die Ukraine hat einige der größten Granitvorkommen Europas, und die meisten Steinbrüche liegen in der Region Schytomyr, wenige Stunden von unserer Fertigung. Der heimische Stein ist günstiger als Import, qualitativ nicht schlechter und hat eine dokumentierte Strahlungsklasse. Wir erklären, worin sich die zehn Gesteine unseres Katalogs unterscheiden und wo jedes sinnvoll eingesetzt wird.","sections":[{"heading":"Welchen ukrainischen Granit wählen?","body":"Für Arbeitsplatten, Treppen und jedes Detail, das man täglich berührt, wählt man meist den Pokostivka-Granit Grey Ukraine: ruhiger hellgrauer Ton, feines Korn, stabile Qualität. Für kontrastreiche schwarze Flächen — Gabbro Kometa Black. Für einen Akzent mit kristallinem Glanz — Labradorit Volga Blue.\n\nRote und rosa Gesteine (Maple Red, Rosso Santiago, Star of Ukraine, Flower of Ukraine, Leopard) funktionieren an Fassaden, Sockeln, Treppen und im Pflaster, wo eine warme Farbe und hohe Verschleißfestigkeit gefragt sind."},{"heading":"Worin unterscheiden sich Pokostivka, Gabbro und Labradorit?","body":"Pokostivka-Granit ist ein klassisches Granitgestein: Quarz, Feldspat und Glimmer, ein hellgrauer feinkörniger Körper. Er lässt sich gut polieren, verträgt Flammen und eignet sich für außen und innen. Der universellste Stein des Katalogs.\n\nGabbro (Kometa Black) ist ein dunkles magmatisches Gestein mit feinem Korn. Die polierte Oberfläche ist fast schwarz mit feinen grauen Einschlüssen. Geflammter Gabbro wird dunkelgrau und matt und funktioniert hervorragend auf Eingangsstufen.\n\nLabradorit (Volga Blue, Irina Blue) ist ein Gestein mit großen Kristallen, die im Winkel blau oder grün aufblitzen. Er ist ein dekorativer Stein für Arbeitsplatten, Tresen und Kaminverkleidungen. In der Härte steht er Granit nicht nach, braucht aber wegen der großen Kristalle ein vorsichtiges Kantenprofil."},{"heading":"Welche Farben gibt es?","body":"Grau: Grey Ukraine (Pokostivka). Schwarz: Kometa Black (Gabbro). Schwarzblau: Volga Blue, Irina Blue. Rot: Maple Red (Leznyky), Rosso Santiago (Kapustyne), Carpazi (Tokivske). Rosa und braunrosa: Star of Ukraine (Didkovychi), Flower of Ukraine (Mezhyrich), Leopard (Kornyn).\n\nDer Farbton innerhalb eines Vorkommens schwankt von Charge zu Charge, deshalb zeigen wir in der Fertigung Foto und Video genau jener Platte, die in Ihr Stück geht, und große Fassadenchargen wählen wir aus einem Block."},{"heading":"Was ist mit der Strahlungsklasse und wo darf man ihn einsetzen?","body":"Jeder Naturstein enthält Spuren natürlicher Radionuklide. Nach den DSTU-Normen werden Baustoffe in Klassen eingeteilt: Klasse I (bis 370 Bq/kg) ist für jede Anwendung zugelassen, auch für Wohnräume; Klasse II (bis 740 Bq/kg) nur für Straßen- und Industriebau sowie Außenarbeiten.\n\nDie meisten Granite unseres Katalogs haben Klasse I, bestätigt durch ein Protokoll für die Charge. Der Tokivske-Granit Carpazi gehört zu Klasse II, deshalb verkaufen wir ihn ausschließlich für außen: Pflaster, Sockel, Stützmauern. Das Protokoll für die konkrete Charge liefern wir mit der Rechnung."},{"heading":"Welcher Granit für innen, welcher für außen?","body":"Interieur: Grey Ukraine, Kometa Black, Volga Blue, Irina Blue, Maple Red, Rosso Santiago, Star of Ukraine — poliert oder matt, Arbeitsplatten, Fensterbänke, Treppen, Kaminportale.\n\nAußenbereich: alle genannten plus Flower of Ukraine, Leopard und Carpazi. Für außen wählen Sie eine geflammte oder gestockte Oberfläche: Sie ist bei Regen und Frost nicht rutschig, und die Farbe wird ruhiger, ein bis zwei Töne heller als poliert."}],"table":{"headers":["Stein","Farbe","Wo einsetzen"],"rows":[["Grey Ukraine","hellgrau","Universell: innen und außen"],["Kometa Black","schwarz","Arbeitsplatten, Portale, Eingangsstufen"],["Volga Blue / Irina Blue","schwarzblau mit Glanz","Arbeitsplatten, Tresen, Kamine"],["Maple Red / Rosso Santiago / Star of Ukraine","rotrosa","Treppen, Fassaden, Arbeitsplatten"],["Flower of Ukraine / Leopard","rosa","Fassaden, Sockel, Pflaster"],["Carpazi","rotbraun","Nur außen, Strahlungsklasse II"]]},"faq":[{"question":"Welcher Granit ist am härtesten?","answer":"Gabbro und Labradorit sind etwas dichter als klassische Granite, aber in der Praxis ist der Unterschied nicht spürbar: Alle Gesteine des Katalogs haben eine Härte von 6–7 nach Mohs und eine Druckfestigkeit über 180 MPa."},{"question":"Welche Farbe ist am beliebtesten?","answer":"Für Arbeitsplatten und Treppen in Privathäusern der graue Grey Ukraine, für Akzente der schwarze Kometa Black. Rote Gesteine gehen häufiger an Fassaden und ins Pflaster."},{"question":"Ist Granit im Haus unbedenklich?","answer":"Ja, wenn es ein Stein der Strahlungsklasse I mit Protokoll für die Charge ist. In Innenräumen verwenden wir keine Materialien der Klasse II und liefern zu jeder Lieferung ein Dokument."},{"question":"Welcher Granit für die Fassade?","answer":"Jeder aus dem Katalog, sofern geflammt oder gestockt und mechanisch befestigt. Am häufigsten wählt man Grey Ukraine wegen der ruhigen Farbe und Maple Red für kontrastreiche Sockel."}]},"en":{"title":"Ukrainian granites: comparing types and colours","h1":"Ukrainian granites — which to choose for your project","description":"An overview of Ukrainian granites: Pokostivka, gabbro, labradorite, Maple Red, Rosso Santiago and others. Colours, properties, radiation class, applications.","dek":"Ten Ukrainian stones for interiors, facades and landscaping.","intro":"Ukraine has some of the largest granite reserves in Europe, and most quarries are in the Zhytomyr region, a few hours from our workshop. Local stone is cheaper than imports, no worse in quality and has a documented radiation class. We explain how the ten stones in our catalogue differ and where each is best used.","sections":[{"heading":"Which Ukrainian granite to choose?","body":"For countertops, stairs and any detail touched daily, the most common choice is Pokostivka granite Grey Ukraine: a calm light grey tone, fine grain, stable quality. For contrasting black surfaces — Kometa Black gabbro. For an accent with crystalline sparkle — Volga Blue labradorite.\n\nRed and pink stones (Maple Red, Rosso Santiago, Star of Ukraine, Flower of Ukraine, Leopard) work on facades, plinths, stairs and paving, where a warm colour and high wear resistance are needed."},{"heading":"How do Pokostivka, gabbro and labradorite differ?","body":"Pokostivka granite is a classic granite rock: quartz, feldspar and mica, a light grey fine-grained body. It polishes well, tolerates flaming, and suits both exterior and interior. The most versatile stone in the catalogue.\n\nGabbro (Kometa Black) is a dark igneous rock with fine grain. The polished surface is almost black with thin grey inclusions. Flamed gabbro becomes dark grey and matte and works excellently on entrance steps.\n\nLabradorite (Volga Blue, Irina Blue) is a rock with large crystals that flash blue or green at an angle. It is a decorative stone for countertops, bar tops and fireplace cladding. In hardness it is no less than granite, but because of the large crystals it needs a careful edge profile."},{"heading":"Which colours are available?","body":"Grey: Grey Ukraine (Pokostivka). Black: Kometa Black (gabbro). Black-blue: Volga Blue, Irina Blue. Reds: Maple Red (Leznyky), Rosso Santiago (Kapustyne), Carpazi (Tokivske). Pinks and brown-pinks: Star of Ukraine (Didkovychi), Flower of Ukraine (Mezhyrich), Leopard (Kornyn).\n\nThe shade within one quarry varies from batch to batch, so at the workshop we show photos and video of the very slab that will go into your piece, and large facade batches are selected from one block."},{"heading":"What about the radiation class and where can it be used?","body":"Every natural stone contains traces of natural radionuclides. Under the DSTU standards building materials are divided into classes: class I (up to 370 Bq/kg) is allowed for any use, including housing; class II (up to 740 Bq/kg) — only for road and industrial construction and exterior work.\n\nMost granites in our catalogue are class I, confirmed by a certificate for the batch. Tokivske granite Carpazi belongs to class II, so we sell it exclusively for outdoors: paving, plinths, retaining walls. The certificate for the specific batch is provided with the invoice."},{"heading":"Which granite for interiors and which for exteriors?","body":"Interior: Grey Ukraine, Kometa Black, Volga Blue, Irina Blue, Maple Red, Rosso Santiago, Star of Ukraine — polished or honed finish, countertops, window sills, stairs, fireplace surrounds.\n\nExterior: all of the above plus Flower of Ukraine, Leopard and Carpazi. For outdoors choose a flamed or bush-hammered finish: it is not slippery in rain and frost, and the colour becomes calmer, one or two tones lighter than polished."}],"table":{"headers":["Stone","Colour","Where to use"],"rows":[["Grey Ukraine","light grey","Versatile: interior and exterior"],["Kometa Black","black","Countertops, surrounds, entrance steps"],["Volga Blue / Irina Blue","black-blue with sparkle","Countertops, bar tops, fireplaces"],["Maple Red / Rosso Santiago / Star of Ukraine","red-pink","Stairs, facades, countertops"],["Flower of Ukraine / Leopard","pink","Facades, plinths, paving"],["Carpazi","red-brown","Exterior only, radiation class II"]]},"faq":[{"question":"Which granite is the hardest?","answer":"Gabbro and labradorite are slightly denser than classic granites, but in practice the difference is not noticeable: all stones in the catalogue have a hardness of 6–7 on Mohs and a compressive strength above 180 MPa."},{"question":"Which colour is the most popular?","answer":"For countertops and stairs in private homes — grey Grey Ukraine, for accents — black Kometa Black. Red stones more often go to facades and paving."},{"question":"Is granite safe in the home?","answer":"Yes, if it is radiation class I stone with a certificate for the batch. We do not use class II materials in interiors and provide a document with every delivery."},{"question":"Which granite for a facade?","answer":"Any from the catalogue, provided it has a flamed or bush-hammered finish and mechanical fixing. Most often Grey Ukraine is chosen for its calm colour and Maple Red for contrasting plinths."}]},"lt":{"title":"Ukrainietiški granitai: rūšių ir spalvų palyginimas","h1":"Ukrainietiški granitai — kurį rinktis jūsų projektui","description":"Ukrainietiškų granitų apžvalga: Pokostivkos, gabras, labradoritas, Maple Red, Rosso Santiago ir kiti. Spalvos, savybės, radiacijos klasė, pritaikymas.","dek":"Dešimt ukrainietiškų uolienų interjerui, fasadui ir kraštovaizdžiui.","intro":"Ukraina turi vienus didžiausių Europoje granito išteklių, o dauguma karjerų yra Žytomyro srityje, už kelių valandų nuo mūsų gamybos. Vietinis akmuo pigesnis už importą, kokybe ne prastesnis ir turi dokumentuotą radiacijos klasę. Paaiškiname, kuo skiriasi dešimt uolienų iš mūsų katalogo ir kur kiekvieną verta taikyti.","sections":[{"heading":"Kurį ukrainietišką granitą rinktis?","body":"Stalviršiui, laiptams ir bet kuriai detalei, kurią liečiate kasdien, dažniausiai renkamas Pokostivkos granitas Grey Ukraine: ramus šviesiai pilkas tonas, smulkus grūdas, stabili kokybė. Kontrastingiems juodiems paviršiams — gabras Kometa Black. Akcentui su kristaliniu blizgesiu — labradoritas Volga Blue.\n\nRaudonos ir rožinės uolienos (Maple Red, Rosso Santiago, Star of Ukraine, Flower of Ukraine, Leopard) dirba fasaduose, cokoliuose, laiptuose ir grindinyje, kur reikia šiltos spalvos ir didelio atsparumo dilimui."},{"heading":"Kuo skiriasi Pokostivkos, gabras ir labradoritas?","body":"Pokostivkos granitas — klasikinė granito uoliena: kvarcas, lauko špatas ir žėrutis, šviesiai pilkas smulkiagrūdis kūnas. Gerai poliruojasi, atlaiko terminį apdirbimą, tinka laukui ir interjerui. Universaliausias katalogo akmuo.\n\nGabras (Kometa Black) — tamsi magminė uoliena su smulkiu grūdu. Poliruotas paviršius beveik juodas su plonais pilkais intarpais. Degintas gabras tampa tamsiai pilkas ir matinis, puikiai tinka įėjimo laiptams.\n\nLabradoritas (Volga Blue, Irina Blue) — uoliena su dideliais kristalais, kurie kampu sužimba mėlynai arba žaliai. Tai dekoratyvinis akmuo stalviršiams, baro stalams ir židinio apdailai. Kietumu nenusileidžia granitui, bet dėl didelių kristalų reikalauja atsargaus krašto profilio."},{"heading":"Kokios spalvos prieinamos?","body":"Pilka: Grey Ukraine (Pokostivka). Juoda: Kometa Black (gabras). Juodai mėlyna: Volga Blue, Irina Blue. Raudonos: Maple Red (Leznykai), Rosso Santiago (Kapustynė), Carpazi (Tokivskė). Rožinės ir rudai rožinės: Star of Ukraine (Didkovyčiai), Flower of Ukraine (Mežyričas), Leopard (Kornynas).\n\nAtspalvis viename karjere svyruoja nuo partijos iki partijos, todėl gamyboje rodome būtent tos plokštės, kuri pateks į jūsų gaminį, nuotraukas ir vaizdo įrašus, o dideles fasadų partijas parenkame iš vieno bloko."},{"heading":"Kas dėl radiacijos klasės ir kur galima taikyti?","body":"Kiekvienas natūralus akmuo turi natūralių radionuklidų pėdsakų. Pagal DSTU statybinės medžiagos skirstomos į klases: I klasė (iki 370 Bq/kg) leidžiama bet kokiam taikymui, įskaitant gyvenamąsias patalpas; II klasė (iki 740 Bq/kg) — tik kelių ir pramoninei statybai bei išorės darbams.\n\nDauguma mūsų katalogo granitų turi I klasę, patvirtintą partijos protokolu. Tokivskės granitas Carpazi priklauso II klasei, todėl parduodame jį tik laukui: grindinys, cokoliai, atraminės sienos. Konkrečios partijos protokolą pateikiame kartu su sąskaita."},{"heading":"Kuris granitas interjerui, o kuris eksterjerui?","body":"Interjeras: Grey Ukraine, Kometa Black, Volga Blue, Irina Blue, Maple Red, Rosso Santiago, Star of Ukraine — poliruota arba matinė apdaila, stalviršiai, palangės, laiptai, portalai.\n\nEksterjeras: visi išvardyti plius Flower of Ukraine, Leopard ir Carpazi. Laukui rinkitės degintą arba kalstytą apdailą: ji neslidi lyjant ir šąlant, o spalva tampa ramesnė, vienu–dviem tonais šviesesnė už poliruotą."}],"table":{"headers":["Akmuo","Spalva","Kur taikyti"],"rows":[["Grey Ukraine","šviesiai pilkas","Universalus: interjeras ir eksterjeras"],["Kometa Black","juodas","Stalviršiai, portalai, įėjimo laiptai"],["Volga Blue / Irina Blue","juodai mėlynas su blizgesiu","Stalviršiai, baro stalai, židiniai"],["Maple Red / Rosso Santiago / Star of Ukraine","raudonai rožiniai","Laiptai, fasadai, stalviršiai"],["Flower of Ukraine / Leopard","rožiniai","Fasadai, cokoliai, grindinys"],["Carpazi","raudonai rudas","Tik eksterjeras, II radiacijos klasė"]]},"faq":[{"question":"Kuris granitas kiečiausias?","answer":"Gabras ir labradoritas kiek tankesni už klasikinius granitus, bet praktiškai skirtumas nejuntamas: visos katalogo uolienos turi 6–7 kietumą pagal Mosą ir gniuždymo stiprį virš 180 MPa."},{"question":"Kuri spalva populiariausia?","answer":"Stalviršiams ir laiptams privačiuose namuose — pilkas Grey Ukraine, akcentams — juodas Kometa Black. Raudonos uolienos dažniau imamos fasadams ir grindiniui."},{"question":"Ar granitas namuose saugus?","answer":"Taip, jei tai I radiacijos klasės akmuo su partijos protokolu. Interjere II klasės medžiagų nenaudojame ir su kiekvienu tiekimu pateikiame dokumentą."},{"question":"Kuris granitas fasadui?","answer":"Bet kuris iš katalogo, jei apdaila deginta arba kalstyta ir tvirtinimas mechaninis. Dažniausiai imamas Grey Ukraine dėl ramios spalvos ir Maple Red kontrastingiems cokoliams."}]},"pl":{"title":"Ukraińskie granity: porównanie rodzajów i kolorów","h1":"Ukraińskie granity — który wybrać do Twojego projektu","description":"Przegląd ukraińskich granitów: Pokostiwka, gabro, labradoryt, Maple Red, Rosso Santiago i inne. Kolory, właściwości, klasa radiacji, zastosowanie.","dek":"Dziesięć ukraińskich skał do wnętrz, elewacji i krajobrazu.","intro":"Ukraina ma jedne z największych w Europie zasobów granitu, a większość złóż leży na Żytomierszczyźnie, kilka godzin od naszej produkcji. Lokalny kamień jest tańszy od importu, nie gorszy jakościowo i ma udokumentowaną klasę radiacji. Wyjaśniamy, czym różni się dziesięć skał z naszego katalogu i gdzie każdą warto zastosować.","sections":[{"heading":"Który ukraiński granit wybrać?","body":"Na blat, schody i każdy detal, którego dotyka się codziennie, najczęściej wybiera się granit pokostiwski Grey Ukraine: spokojny jasnoszary ton, drobne ziarno, stabilna jakość. Na kontrastowe czarne powierzchnie — gabro Kometa Black. Na akcent z krystalicznym połyskiem — labradoryt Volga Blue.\n\nSkały czerwone i różowe (Maple Red, Rosso Santiago, Star of Ukraine, Flower of Ukraine, Leopard) pracują na elewacjach, cokołach, schodach i w kostce, gdzie potrzebny jest ciepły kolor i wysoka odporność na ścieranie."},{"heading":"Czym różnią się Pokostiwka, gabro i labradoryt?","body":"Granit pokostiwski to klasyczna skała granitowa: kwarc, skaleń i mika, jasnoszare drobnoziarniste tło. Dobrze się poleruje, wytrzymuje płomieniowanie, nadaje się na zewnątrz i do wnętrz. Najbardziej uniwersalny kamień katalogu.\n\nGabro (Kometa Black) to ciemna skała magmowa o drobnym ziarnie. Powierzchnia polerowana jest niemal czarna z cienkimi szarymi wtrąceniami. Płomieniowane gabro staje się ciemnoszare i matowe, świetnie pracuje na schodach wejściowych.\n\nLabradoryt (Volga Blue, Irina Blue) to skała z dużymi kryształami, które dają niebieski lub zielony błysk pod kątem. To kamień dekoracyjny na blaty, bary i okładziny kominka. Twardością nie ustępuje granitowi, ale przez duże kryształy wymaga ostrożnego profilu krawędzi."},{"heading":"Jakie kolory są dostępne?","body":"Szary: Grey Ukraine (Pokostiwka). Czarny: Kometa Black (gabro). Czarno-niebieski: Volga Blue, Irina Blue. Czerwone: Maple Red (Leznyky), Rosso Santiago (Kapustyne), Carpazi (Tokiwske). Różowe i brązowo-różowe: Star of Ukraine (Didkowyczi), Flower of Ukraine (Meżyricz), Leopard (Kornyn).\n\nOdcień w obrębie jednego złoża waha się od partii do partii, dlatego na produkcji pokazujemy zdjęcia i wideo właśnie tego sląba, który pójdzie do Twojego wyrobu, a duże partie elewacyjne dobieramy z jednego bloku."},{"heading":"Co z klasą radiacji i gdzie można stosować?","body":"Każdy kamień naturalny zawiera śladowe ilości naturalnych radionuklidów. Według norm DSTU materiały budowlane dzieli się na klasy: klasa I (do 370 Bq/kg) dozwolona do każdego zastosowania, w tym mieszkalnego; klasa II (do 740 Bq/kg) — tylko do budownictwa drogowego, przemysłowego i prac zewnętrznych.\n\nWiększość granitów naszego katalogu ma klasę I potwierdzoną protokołem na partię. Granit tokiwski Carpazi należy do klasy II, dlatego sprzedajemy go wyłącznie na zewnątrz: kostka, cokoły, mury oporowe. Protokół na konkretną partię przekazujemy razem z fakturą."},{"heading":"Który granit do wnętrz, a który na zewnątrz?","body":"Wnętrza: Grey Ukraine, Kometa Black, Volga Blue, Irina Blue, Maple Red, Rosso Santiago, Star of Ukraine — wykończenie polerowane lub matowe, blaty, parapety, schody, portale.\n\nZewnątrz: wszystkie wymienione plus Flower of Ukraine, Leopard i Carpazi. Na zewnątrz wybieraj wykończenie płomieniowane lub groszkowane: nie jest śliskie w deszczu i mrozie, a kolor staje się spokojniejszy, o jeden–dwa tony jaśniejszy od polerowanego."}],"table":{"headers":["Kamień","Kolor","Gdzie stosować"],"rows":[["Grey Ukraine","jasnoszary","Uniwersalny: wnętrza i zewnątrz"],["Kometa Black","czarny","Blaty, portale, schody wejściowe"],["Volga Blue / Irina Blue","czarno-niebieski z połyskiem","Blaty, bary, kominki"],["Maple Red / Rosso Santiago / Star of Ukraine","czerwono-różowe","Schody, elewacje, blaty"],["Flower of Ukraine / Leopard","różowe","Elewacje, cokoły, kostka"],["Carpazi","czerwono-brązowy","Tylko zewnątrz, klasa II radiacji"]]},"faq":[{"question":"Który granit jest najtwardszy?","answer":"Gabro i labradoryt są nieco gęstsze od klasycznych granitów, ale w praktyce różnica jest niewyczuwalna: wszystkie skały katalogu mają twardość 6–7 w skali Mohsa i wytrzymałość na ściskanie powyżej 180 MPa."},{"question":"Który kolor jest najpopularniejszy?","answer":"Na blaty i schody w domach prywatnych — szary Grey Ukraine, na akcenty — czarny Kometa Black. Skały czerwone częściej trafiają na elewacje i kostkę."},{"question":"Czy granit w domu jest bezpieczny?","answer":"Tak, jeśli to kamień klasy I radiacji z protokołem na partię. We wnętrzach nie stosujemy materiałów klasy II i dostarczamy dokument do każdej dostawy."},{"question":"Który granit na elewację?","answer":"Każdy z katalogu pod warunkiem wykończenia płomieniowanego lub groszkowanego i mocowania mechanicznego. Najczęściej wybiera się Grey Ukraine za spokojny kolor i Maple Red na kontrastowe cokoły."}]}}'::jsonb) where slug = 'ukrainski-granity-porivnyannya';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Arbeitsplatte aus Feinsteinzeug Laminam/Neolith: Vor- und Nachteile","h1":"Feinsteinzeug für die Arbeitsplatte — wann es die beste Wahl ist","description":"Feinsteinzeug Laminam, Neolith, Dekton für die Arbeitsplatte: Hitzebeständigkeit, geringe Dicke, UV-Stabilität, Abplatzrisiko und Montageanforderungen.","dek":"Großformatige dünne Platten in Arbeitsplatten und Fassaden.","intro":"Großformatiges Feinsteinzeug kam von den Fassaden in die Küchen: Eine Platte von 1600 × 3200 mm mit 6–12 mm Dicke wiegt halb so viel wie Stein und fürchtet nichts von dem, was in einer Küche passiert. Zugleich ist es das montagetechnisch anspruchsvollste Material in unserem Katalog. Wir erklären, wann es sich lohnt und wann Quarz oder Granit besser sind.","sections":[{"heading":"Für wen eignet sich Feinsteinzeug?","body":"Für alle, die eine Oberfläche brauchen, auf der man Heißes abstellen, ohne Brett schneiden und nicht an Flecken denken muss. Feinsteinzeug wird bei über 1200 °C gesintert und hat deshalb weder Harze noch Poren: Weder Pfanne noch Wein noch UV-Licht wirken darauf.\n\nEs eignet sich auch für lange Arbeitsplatten mit minimalen Fugen, für dünne „schwebende“ Regale und Fassaden, bei denen das Gewicht zählt. Eine 12-mm-Platte wirkt in der Küche leicht und modern, und die Dekore imitieren Marmor, Beton oder Metall."},{"heading":"Welche Vorteile haben Großformatplatten?","body":"Das Format 3200 × 1600 mm deckt die Arbeitsplatte einer L-Küche mit einer Fuge ab. Eine dünne Kante von 12 oder 20 mm wirkt grafisch, und eine auf Gehrung verleimte Kante verdeckt den weißen Plattenkern.\n\nGewicht: Eine 12-mm-Platte wiegt etwa 30 kg pro m² gegenüber 55–60 kg bei Granit. Das erleichtert die Montage auf alten Möbeln, an Wänden und in Wohnungen ohne Aufzug. Das Dekor ist innerhalb der Charge stabil, sodass die Küche ein Jahr später mit derselben Kollektion ergänzt werden kann."},{"heading":"Welche Nachteile gibt es und worauf ist zu achten?","body":"Sprödigkeit an den Kanten. Feinsteinzeug hält Stöße auf die Fläche aus, platzt aber bei einem Schlag auf die Kante ab, besonders bei gerader Kante. Deshalb empfehlen wir Fase oder Rundung und machen keine scharfen Außenecken.\n\nAnforderungen an den Untergrund. Eine 6-mm-Platte braucht vollflächige Auflage, 12 mm trägt der Schrankrahmen, aber bei Ausschnitten sind trotzdem Unterlagen nötig. Ausschnitte für Spüle und Kochfeld werden nur an der wassergekühlten Maschine geschnitten, vor Ort kann nichts nachgeschnitten werden.\n\nReparatur. Eine Abplatzung an Feinsteinzeug lässt sich schlechter ausbessern als an Stein: Der Polymereinsatz fällt bei gleichmäßigen Dekoren auf. Deshalb ist Vorsicht im Gebrauch wichtiger als bei Granit."},{"heading":"Warum sind Laminam und Neolith besser als normale Fliesen?","body":"Gewöhnliches Bodenfeinsteinzeug ist eine Fliese 600 × 600 mm mit 8–10 mm Dicke, zum Verlegen auf Kleber gedacht. Großformatplatten von Laminam, Neolith und Dekton werden auf anderen Anlagen hergestellt: Sie haben über die ganze Länge eine ebene Geometrie, in manchen Kollektionen eine Durchfärbung und eine Zertifizierung für den Lebensmittelkontakt.\n\nDekton ist technisch kein Feinsteinzeug, sondern eine ultrakompakte Oberfläche aus gesinterten Mineralien, verhält sich in Eigenschaften und Montage aber gleich. Alle drei Marken geben eine Materialgarantie unter der Bedingung der Montage durch einen zertifizierten Verarbeiter, was auch unsere Werkstatt ist."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Heißes","Feinsteinzeug verträgt es vollständig","Quarz nur mit Untersetzer"],["Dicke","6, 12 oder 20 mm","Dünne Platten brauchen vollflächige Auflage"],["Fugen","Eine Fuge pro L-Küche","Format 3200 × 1600 mm"],["Kanten","Abplatzrisiko an scharfer Kante","Fase oder Rundung"],["Außenbereich","UV-stabil","Geeignet für Außenküche und Fassade"]]},"faq":[{"question":"Kann man Heißes abstellen?","answer":"Ja, ohne Einschränkung: Das Material enthält keine Harze und verändert sich bei den Temperaturen einer Haushaltsküche nicht."},{"question":"Zerkratzt es?","answer":"Die Oberfläche ist härter als Messerstahl und zerkratzt nicht. Ausnahme sind matte und strukturierte Dekore, auf denen Metallgeschirr graue, abwaschbare Spuren hinterlassen kann."},{"question":"Welche Dicke?","answer":"Für Arbeitsplatten nehmen wir 12 mm mit verleimter Kante oder 20 mm massiv. 6 mm verwenden wir für Wandverkleidungen, Möbelfronten und Spritzschutz."},{"question":"Eignet es sich für Fassade und außen?","answer":"Ja, es ist eines der besten Materialien für hinterlüftete Fassaden und Außenküchen: Es verblasst nicht, nimmt kein Wasser auf und hält Frost aus."}]},"en":{"title":"Laminam/Neolith porcelain countertop: pros and cons","h1":"Porcelain for a countertop — when it is the best choice","description":"Laminam, Neolith, Dekton porcelain for a countertop: heat resistance, thinness, UV stability, chipping risk and installation requirements.","dek":"Large-format thin slabs in countertops and facades.","intro":"Large-format porcelain came to kitchens from facades: a 1600 × 3200 mm slab 6–12 mm thick weighs half as much as stone and fears nothing that happens in a kitchen. At the same time it is the most demanding material in our catalogue to install. We break down when it is justified and when quartz or granite is the better choice.","sections":[{"heading":"Who is porcelain for?","body":"For those who need a surface you can put hot things on, cut on without a board and not think about stains. Porcelain is sintered at over 1200 °C, so it has no resins or pores: neither a frying pan, nor wine, nor ultraviolet affects it.\n\nIt also suits long countertops with a minimum of joints, thin “floating” shelves and facades where weight matters. A 12 mm slab in a kitchen looks light and modern, and the decors mimic marble, concrete or metal."},{"heading":"What are the advantages of large-format slabs?","body":"The 3200 × 1600 mm format covers an L-shaped kitchen countertop with one joint. A thin 12 mm or 20 mm edge gives a graphic look, and a 45° mitred laminated edge hides the white body of the slab.\n\nWeight: a 12 mm slab weighs about 30 kg per m² versus 55–60 kg for granite. This eases installation on old furniture, on walls and in flats without a lift. The decor is stable within a batch, so the kitchen can be extended a year later with the same collection."},{"heading":"What are the drawbacks and what to watch for?","body":"Brittle edges. Porcelain withstands impact on the face but chips from a blow to the edge, especially on a straight edge. So we recommend a bevel or rounding and do not make sharp external corners.\n\nSubstrate requirements. A 6 mm slab needs continuous support over the whole area; 12 mm takes the frame of the units, but pads are still needed near cut-outs. Cut-outs for the sink and hob are cut only on a water-cooled machine; nothing can be trimmed on site.\n\nRepair. A chip on porcelain repairs worse than on stone: a polymer insert is noticeable on uniform decors. So care in use matters more than with granite."},{"heading":"How are Laminam and Neolith better than ordinary tiles?","body":"Ordinary floor porcelain is a 600 × 600 mm tile 8–10 mm thick, designed to be laid on adhesive. Large-format Laminam, Neolith and Dekton slabs are made on different equipment: they have flat geometry along the whole length, through-body colour in some collections and certification for food contact.\n\nDekton is technically not porcelain but an ultra-compact surface of sintered minerals, yet in properties and installation it behaves the same. All three brands give a material warranty on condition of installation by a certified fabricator, which our workshop is."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Heat","Porcelain takes it fully","Quartz only via a trivet"],["Thickness","6, 12 or 20 mm","Thin slabs need a continuous substrate"],["Joints","One joint for an L-kitchen","Format 3200 × 1600 mm"],["Edges","Chipping risk on a sharp edge","Bevel or rounding"],["Outdoors","UV-stable","Suits outdoor kitchens and facades"]]},"faq":[{"question":"Can I put hot things on it?","answer":"Yes, without limits: the material contains no resins and does not change at the temperatures a home kitchen produces."},{"question":"Does it scratch?","answer":"The surface is harder than a knife blade and does not scratch. The exception is matte and textured decors, on which metal cookware can leave grey marks that wash off."},{"question":"What thickness?","answer":"For countertops we take 12 mm with a laminated edge or 20 mm solid. 6 mm we use for wall cladding, furniture fronts and splashbacks."},{"question":"Is it suitable for facades and outdoors?","answer":"Yes, it is one of the best materials for ventilated facades and outdoor kitchens: it does not fade, does not absorb water and withstands frost."}]},"lt":{"title":"Stalviršis iš keraminio granito Laminam/Neolith: privalumai ir trūkumai","h1":"Keraminis granitas stalviršiui — kada tai geriausias pasirinkimas","description":"Keraminis granitas Laminam, Neolith, Dekton stalviršiui: atsparumas karščiui, plonumas, UV stabilumas, nuskilimų rizika ir montavimo reikalavimai.","dek":"Didelio formato plonos plokštės stalviršiuose ir fasaduose.","intro":"Didelio formato keraminis granitas į virtuves atėjo iš fasadų: 1600 × 3200 mm plokštė 6–12 mm storio sveria perpus mažiau nei akmuo ir nebijo nieko iš to, kas vyksta virtuvėje. Kartu tai reikliausia montavimui medžiaga mūsų kataloge. Aiškinamės, kada ji pateisinama, o kada geriau imti kvarcą ar granitą.","sections":[{"heading":"Kam tinka keraminis granitas?","body":"Tiems, kam reikia paviršiaus, ant kurio galima statyti karštus indus, pjaustyti be lentelės ir negalvoti apie dėmes. Keraminis granitas sukepinamas aukštesnėje nei 1200 °C temperatūroje, todėl neturi dervų ir porų: nei keptuvė, nei vynas, nei ultravioletas jo neveikia.\n\nJis taip pat tinka ilgiems stalviršiams su minimaliu siūlių skaičiumi, plonoms „skraidančioms“ lentynoms ir fasadams, kur svarbus svoris. 12 mm plokštė virtuvėje atrodo lengva ir moderni, o dekorai kartoja marmurą, betoną ar metalą."},{"heading":"Kokie didelio formato plokščių privalumai?","body":"3200 × 1600 mm formatas uždengia L formos virtuvės stalviršį su viena siūle. Plonas 12 mm ar 20 mm kraštas suteikia grafišką išvaizdą, o suklijuotas „45° kampu“ kraštas paslepia baltą plokštės pagrindą.\n\nSvoris: 12 mm plokštė sveria apie 30 kg/m² prieš 55–60 kg granito. Tai palengvina montavimą ant senų baldų, ant sienų ir butuose be lifto. Dekoras stabilus partijoje, todėl virtuvę po metų galima papildyti ta pačia kolekcija."},{"heading":"Kokie trūkumai ir į ką atkreipti dėmesį?","body":"Kraštų trapumas. Keraminis granitas atlaiko smūgį į plokštumą, bet nuskyla nuo smūgio į briauną, ypač tiesiame krašte. Todėl rekomenduojame nuožulną arba suapvalinimą ir nedarome aštrių išorinių kampų.\n\nReikalavimai pagrindui. 6 mm plokštei reikia vientisos atramos visame plote, 12 mm atlaiko modulių rėmą, bet prie išpjovų vis tiek reikia pakladų. Išpjova plautuvei ir kaitlentei pjaunama tik staklėmis su vandens aušinimu, objekte papjauti negalima.\n\nRemontas. Nuskilimas ant keraminio granito restauruojamas prasčiau nei ant akmens: polimerinis įdėklas pastebimas vienalyčiuose dekoruose. Todėl atsargumas naudojant svarbesnis nei su granitu."},{"heading":"Kuo Laminam ir Neolith geresni už paprastas plyteles?","body":"Paprastas grindų keraminis granitas — tai 600 × 600 mm plytelė 8–10 mm storio, skirta klijuoti. Didelio formato Laminam, Neolith ir Dekton plokštės gaminamos kita įranga: jos turi lygią geometriją per visą ilgį, kai kuriose kolekcijose — pilną prasidažymą ir sertifikatą kontaktui su maistu.\n\nDekton techniškai ne keraminis granitas, o ultrakompaktinis paviršius iš sukepintų mineralų, bet pagal savybes ir montavimą elgiasi taip pat. Visi trys prekių ženklai suteikia medžiagos garantiją, jei montuoja sertifikuotas gamintojas, koks yra ir mūsų dirbtuvės."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Karštis","Keraminis granitas atlaiko visiškai","Kvarcas tik per padėklą"],["Storis","6, 12 arba 20 mm","Plonoms plokštėms reikia vientiso pagrindo"],["Siūlės","Viena siūlė L virtuvei","Formatas 3200 × 1600 mm"],["Kraštai","Nuskilimų rizika aštrioje briaunoje","Nuožulna arba suapvalinimas"],["Laukas","UV stabilus","Tinka vasaros virtuvei ir fasadui"]]},"faq":[{"question":"Ar galima statyti karštus indus?","answer":"Taip, be apribojimų: medžiaga neturi dervų ir nesikeičia nuo temperatūros, kurią sukuria namų virtuvė."},{"question":"Ar braižosi?","answer":"Paviršius kietesnis už peilio plieną ir nesibraižo. Išimtis — matiniai ir struktūriniai dekorai, ant kurių metaliniai indai gali palikti pilkas žymes, kurios nusiplauna."},{"question":"Koks storis?","answer":"Stalviršiams imame 12 mm su suklijuotu kraštu arba 20 mm monolitinį. 6 mm naudojame sienų apdailai, baldų fasadams ir sienelėms virš stalviršio."},{"question":"Ar tinka fasadui ir laukui?","answer":"Taip, tai viena geriausių medžiagų vėdinamiems fasadams ir vasaros virtuvėms: neblunka, neįgeria vandens, atlaiko šaltį."}]},"pl":{"title":"Blat z gresu Laminam/Neolith: plusy i minusy","h1":"Gres na blat — kiedy to najlepszy wybór","description":"Gres Laminam, Neolith, Dekton na blat: odporność termiczna, cienkość, stabilność UV, ryzyko odprysków i wymagania montażowe.","dek":"Wielkoformatowe cienkie płyty w blatach i elewacjach.","intro":"Wielkoformatowy gres trafił do kuchni z elewacji: płyta 1600 × 3200 mm o grubości 6–12 mm waży o połowę mniej niż kamień i nie boi się nic z tego, co zdarza się w kuchni. Zarazem to najbardziej wymagający w montażu materiał w naszym katalogu. Rozkładamy, kiedy jest uzasadniony, a kiedy lepiej wziąć kwarc lub granit.","sections":[{"heading":"Komu pasuje gres?","body":"Tym, którzy potrzebują powierzchni, na której można stawiać gorące, kroić bez deski i nie myśleć o plamach. Gres spieka się w temperaturze powyżej 1200 °C, dlatego nie ma żywic ani porów: ani patelnia, ani wino, ani ultrafiolet na niego nie działają.\n\nNadaje się też na długie blaty z minimum spoin, na cienkie „lewitujące” półki i elewacje, gdzie waga ma znaczenie. Płyta 12 mm w kuchni wygląda lekko i nowocześnie, a dekory naśladują marmur, beton lub metal."},{"heading":"Jakie są zalety płyt wielkoformatowych?","body":"Format 3200 × 1600 mm zamyka blat kuchni w kształcie L jedną spoiną. Cienka krawędź 12 mm lub 20 mm daje graficzny wygląd, a klejona krawędź „pod kątem 45°” ukrywa biały spód płyty.\n\nWaga: płyta 12-milimetrowa waży około 30 kg na m² wobec 55–60 kg granitu. To ułatwia montaż na starych meblach, na ścianach i w mieszkaniach bez windy. Dekor jest stabilny w partii, więc kuchnię można uzupełnić po roku tą samą kolekcją."},{"heading":"Jakie są wady i na co zwrócić uwagę?","body":"Kruchość krawędzi. Gres wytrzymuje uderzenie w płaszczyznę, ale odpryskuje od uderzenia w krawędź, zwłaszcza na prostym brzegu. Dlatego zalecamy fazę lub zaokrąglenie i nie robimy ostrych narożników zewnętrznych.\n\nWymagania wobec podłoża. Płyta 6 mm potrzebuje pełnego podparcia na całej powierzchni, 12 mm wytrzymuje ramę szafek, ale przy wycięciach i tak potrzebne są podkładki. Wycięcie pod zlew i płytę grzewczą tnie się tylko na maszynie z chłodzeniem wodnym, na obiekcie dociąć nie można.\n\nNaprawa. Odprysk na gresie naprawia się gorzej niż na kamieniu: wstawka polimerowa jest widoczna na jednolitych dekorach. Dlatego ostrożność w użytkowaniu jest ważniejsza niż przy granicie."},{"heading":"Czym Laminam i Neolith są lepsze od zwykłych płytek?","body":"Zwykły gres podłogowy to płytka 600 × 600 mm o grubości 8–10 mm, przewidziana do układania na klej. Wielkoformatowe płyty Laminam, Neolith i Dekton produkuje się na innych liniach: mają równą geometrię na całej długości, pełny przekrój barwiony w części kolekcji i certyfikację do kontaktu z żywnością.\n\nDekton technicznie nie jest gresem, lecz ultrakompaktową powierzchnią ze spiekanych minerałów, ale pod względem właściwości i montażu zachowuje się tak samo. Wszystkie trzy marki dają gwarancję na materiał pod warunkiem montażu przez certyfikowanego wykonawcę, którym jest także nasza pracownia."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Gorące","Gres wytrzymuje w pełni","Kwarc tylko przez podkładkę"],["Grubość","6, 12 lub 20 mm","Cienkie płyty wymagają pełnego podłoża"],["Spoiny","Jedna spoina na kuchnię w L","Format 3200 × 1600 mm"],["Krawędzie","Ryzyko odprysków na ostrym brzegu","Faza lub zaokrąglenie"],["Zewnątrz","Stabilny na UV","Nadaje się do kuchni letniej i na elewację"]]},"faq":[{"question":"Czy można stawiać gorące?","answer":"Tak, bez ograniczeń: materiał nie zawiera żywic i nie zmienia się od temperatur występujących w domowej kuchni."},{"question":"Czy się rysuje?","answer":"Powierzchnia jest twardsza od stali noża i nie rysuje się. Wyjątek to dekory matowe i strukturalne, na których metalowe naczynia mogą zostawiać szare ślady, które się zmywają."},{"question":"Jaka grubość?","answer":"Na blaty bierzemy 12 mm z klejoną krawędzią lub 20 mm w monolicie. 6 mm stosujemy do okładzin ścian, frontów mebli i fartuchów."},{"question":"Czy nadaje się na elewację i na zewnątrz?","answer":"Tak, to jeden z najlepszych materiałów na elewacje wentylowane i kuchnie letnie: nie blaknie, nie chłonie wody, wytrzymuje mróz."}]}}'::jsonb) where slug = 'keramogranit-laminam-neolith-stilnytsia';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Marmor im Badezimmer: Pro und Kontra","h1":"Marmor im Bad — lohnt es sich und wie wählt man","description":"Marmor im Bad: Vorteile, Risiken, Pflege und welche Sorten wählen. Bianco Carrara, Crema Marfil oder Nero Marquina — was ist besser für den Nassbereich.","dek":"Wie man einen Nassbereich mit Naturmarmor plant.","intro":"Das Badezimmer ist der beste Ort für Marmor im Haus. Hier gibt es kein heißes Geschirr und keine Messer, sondern Wasser, weiches Licht und den Wunsch nach Ruhe, für den dieser Stein geschaffen ist. Probleme mit Marmor im Bad entstehen nicht durch das Material, sondern durch falsche Details, säurehaltige Kosmetik und Sanitärreiniger. Wir erklären, wie man das vermeidet.","sections":[{"heading":"Eignet sich Marmor für das Bad?","body":"Ja, unter drei Bedingungen. Erstens: Die Oberfläche ist mit einem Schutzmittel imprägniert, und dieses wird einmal im Jahr erneuert. Zweitens: Alle Fugen an der Platte und zu den Wänden sind abgedichtet, und der Boden hat Gefälle zum Ablauf. Drittens: Im Haus werden keine säurehaltigen Mittel gegen Kalk auf dem Stein verwendet.\n\nUnter diesen Bedingungen halten eine Marmorwaschtischplatte, eine Fensterbank oder eine Wandverkleidung Jahrzehnte. Italienische und spanische Bäder mit hundertjährigem Marmor sind der Beweis."},{"heading":"Welche Vorteile hat Marmor im Bad?","body":"Zeichnung. Kein Verbundwerkstoff wiederholt die Tiefe der Carrara-Adern oder die Wärme von Crema Marfil. Marmor gibt selbst einem kleinen Raum Spa-Gefühl.\n\nKühle und Hygiene. Polierter Marmor lässt sich leicht abwischen, sammelt keinen Staub, und eine Platte für ein Aufsatzwaschbecken wird ohne Fugen auf der sichtbaren Fläche gefertigt.\n\nKombinierbarkeit. Marmor passt zu Messing, Chrom, Holz und Mikrozement. Ein Stein lässt sich über Waschtisch, Fensterbank und Duschablage führen, und der Raum wird zu einem Ganzen."},{"heading":"Welche Risiken gibt es und wie vermeidet man sie?","body":"Säureätzung. Zitrone, Essig, Kalkentferner und manche Kosmetik hinterlassen auf poliertem Marmor matte Flecken. Lösung: neutrale Steinchemie und eine matte Oberfläche, auf der Spuren kaum sichtbar sind.\n\nFlecken von Ölen und Farbstoffen. Körperöle, Haarfarbe, Creme können in die Poren eindringen. Lösung: Imprägnierung nach der Montage und schnelles Abwischen.\n\nWasser in den Fugen. Das ist ein Problem der Fugen, nicht des Marmors. Lösung: Epoxid- oder Silikonfuge, Abdichtung des Untergrunds unter den Fliesen, Gefälle am Boden. Waschtischplatten fertigen wir je nach Detail mit oder ohne Aufkantung."},{"heading":"Welche Sorten wählen — Bianco Carrara, Crema Marfil oder Nero Marquina?","body":"Bianco Carrara: hellgrauer Grund mit weichen grauen Adern. Der universellste, verbirgt Wasser und Spuren, sieht matt gut aus. Geeignet für Platten und Wände.\n\nCrema Marfil: cremebeige, warm, fast ohne Kontrast. Lässt den Raum größer wirken, verbirgt Kalkablagerungen. Einer der praktischsten Marmore für Nassbereiche.\n\nNero Marquina: schwarz mit weißen Adern. Sehr effektvoll, aber jeder Tropfen zeigt sich nach dem Trocknen, ebenso Säurespuren. Wir empfehlen ihn für Wände, Ablagen und Akzente, für die Waschtischplatte nur, wenn Sie bereit sind, trocken zu wischen."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Bianco Carrara","hell mit grauen Adern","Platten, Wände, matte Oberfläche"],["Crema Marfil","warmes Beige","Am praktischsten für den Nassbereich"],["Nero Marquina","dunkel, kontrastreich","Wasser- und Säurespuren sichtbar"],["Emperador Dark","dunkelbraun","Akzentwände, Ablagen"]]},"faq":[{"question":"Fürchtet Marmor Wasser?","answer":"Nein. Wasser zerstört Marmor nicht; Säuren und Schmutz in den Poren schaden. Imprägnierter Stein verhält sich im Bad wie jede andere Oberfläche."},{"question":"Wie oft imprägnieren?","answer":"Einmal im Jahr für Platte und Boden, alle zwei Jahre für Wände. Orientierung ist der Wassertest: Zieht der Tropfen in wenigen Minuten ein, ist es Zeit, den Schutz zu erneuern."},{"question":"Was tun bei einem Säurefleck?","answer":"Ein matter Säurefleck ist kein Schmutz, sondern eine geätzte Oberfläche. Kleine Spuren auf mattem Marmor sind kaum sichtbar; auf poliertem entfernt sie ein Fachmann durch Schleifen und Polieren vor Ort."},{"question":"Womit kann man Marmor ersetzen?","answer":"Mit Quarzit Taj Mahal, wenn ein heller Naturstein ohne Säureempfindlichkeit gewünscht ist, oder mit Quarz bzw. Feinsteinzeug in Marmordekor, wenn völlige Porenfreiheit zählt."}]},"en":{"title":"Marble in the bathroom: pros and cons","h1":"Marble in the bathroom — is it worth it and how to choose","description":"Marble in the bathroom: advantages, risks, care and which varieties to choose. Bianco Carrara, Crema Marfil or Nero Marquina — which is better for a wet zone.","dek":"How to design a wet zone with natural marble.","intro":"The bathroom is the best place for marble in the home. There are no hot pans or knives here, but there is water, soft light and a desire for calm, which this stone was made for. Problems with marble in the bathroom arise not from the material but from the wrong detailing, acidic cosmetics and cleaners for sanitary ware. We explain how to avoid them.","sections":[{"heading":"Is marble suitable for a bathroom?","body":"Yes, on three conditions. First: the surface is treated with a protective sealant and it is renewed once a year. Second: all joints on the countertop and at the walls are sealed, and the floor slopes to the drain. Third: no acid-based products are used in the home to remove limescale from the stone.\n\nUnder these conditions a marble vanity top, window sill or wall cladding lasts for decades. Italian and Spanish bathrooms with century-old marble are the proof."},{"heading":"What are the advantages of marble in a bathroom?","body":"Pattern. No engineered material repeats the depth of Carrara veins or the warmth of Crema Marfil. Marble gives a spa feeling even in a small room.\n\nCoolness and hygiene. Polished marble wipes easily, does not collect dust, and a top for a countertop basin is made without joints on the visible plane.\n\nCompatibility. Marble pairs with brass, chrome, wood and microcement. One stone can run across the vanity top, window sill and shower shelf, and the room becomes whole."},{"heading":"What are the risks and how to avoid them?","body":"Acid etching. Lemon, vinegar, limescale removers and some cosmetics leave matte spots on polished marble. Solution: neutral stone chemistry and a honed finish, on which marks are almost invisible.\n\nStains from oils and dyes. Body oils, hair dye, cream can penetrate the pores. Solution: sealing after installation and quick wiping.\n\nWater in the joints. This is a problem of joints, not marble. Solution: an epoxy or silicone joint, waterproofing of the substrate under tiles, a slope on the floor. We make vanity tops with or without an upstand, depending on the detail."},{"heading":"Which varieties to choose — Bianco Carrara, Crema Marfil or Nero Marquina?","body":"Bianco Carrara: a light grey background with soft grey veins. The most versatile, hides water and marks, looks good honed. Suitable for tops and walls.\n\nCrema Marfil: cream-beige, warm, almost without contrast. Makes the room look bigger, hides limescale. One of the most practical marbles for wet zones.\n\nNero Marquina: black with white veins. Very striking, but every drop shows on it after drying, as do acid marks. We recommend it for walls, shelves and accents, and for a vanity top only if you are ready to wipe it dry."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Bianco Carrara","light with grey veins","Tops, walls, honed finish"],["Crema Marfil","warm beige","The most practical for a wet zone"],["Nero Marquina","dark, contrasting","Water and acid marks show"],["Emperador Dark","dark brown","Accent walls, shelves"]]},"faq":[{"question":"Is marble afraid of water?","answer":"No. Water does not destroy marble; acids and dirt entering the pores do. Sealed stone in a bathroom behaves like any other surface."},{"question":"How often to seal?","answer":"Once a year for the top and floor, once every two years for walls. The guide is the water test: if a drop soaks in within a few minutes, it is time to renew the protection."},{"question":"What to do with an acid mark?","answer":"A matte acid mark is not dirt but an etched surface. Small marks on honed marble are barely visible; on polished marble a craftsman removes them by grinding and polishing on site."},{"question":"What can replace marble?","answer":"Taj Mahal quartzite, if you need a light natural stone without acid sensitivity, or quartz or porcelain with a marble decor, if a total absence of pores matters."}]},"lt":{"title":"Marmuras vonios kambaryje: už ir prieš","h1":"Marmuras vonioje — ar verta ir kaip rinktis","description":"Marmuras vonioje: privalumai, rizikos, priežiūra ir kurias rūšis rinktis. Bianco Carrara, Crema Marfil ar Nero Marquina — kas geriau drėgnai zonai.","dek":"Kaip suprojektuoti drėgną zoną su natūraliu marmuru.","intro":"Vonios kambarys — geriausia vieta marmurui namuose. Čia nėra karštų indų ir peilių, bet yra vanduo, švelni šviesa ir ramybės troškimas, kuriam šis akmuo ir sukurtas. Problemos su marmuru vonioje kyla ne dėl medžiagos, o dėl neteisingo mazgo, kosmetikos su rūgštimis ir santechnikos valiklių. Pasakojame, kaip to išvengti.","sections":[{"heading":"Ar marmuras tinka voniai?","body":"Taip, trimis sąlygomis. Pirma: paviršius impregnuotas apsaugine priemone, ir ji atnaujinama kartą per metus. Antra: visos siūlės ant stalviršio ir prie sienų užsandarintos, o grindys turi nuolydį į trapą. Trečia: namuose nenaudojamos priemonės su rūgštimi kalkių nuosėdoms nuo akmens valyti.\n\nŠiomis sąlygomis marmurinis stalviršis po praustuvu, palangė ar sienos apdaila tarnauja dešimtmečius. Itališkos ir ispaniškos vonios su šimtmečio senumo marmuru — tam patvirtinimas."},{"heading":"Kokie marmuro privalumai vonioje?","body":"Raštas. Jokia inžinerinė medžiaga nepakartoja Carrara gyslų gylio ar Crema Marfil šilumos. Marmuras suteikia SPA pojūtį net mažame kambaryje.\n\nVėsa ir higiena. Poliruotas marmuras lengvai nušluostomas, nekaupia dulkių, o stalviršis po pastatomu praustuvu gaminamas be siūlių matomoje plokštumoje.\n\nSuderinamumas. Marmuras derinasi su žalvariu, chromu, mediena ir mikrocementu. Vieną akmenį galima pratęsti per stalviršį, palangę ir lentyną duše, ir kambarys taps vientisas."},{"heading":"Kokios rizikos ir kaip jų išvengti?","body":"Ėsdinimas rūgštimis. Citrina, actas, kalkių nuosėdų valikliai ir kai kuri kosmetika palieka ant poliruoto marmuro matines dėmes. Sprendimas: neutrali akmens chemija ir matinė apdaila, ant kurios žymės beveik nematomos.\n\nDėmės nuo aliejų ir dažiklių. Kūno aliejai, plaukų dažai, kremas gali prasiskverbti į poras. Sprendimas: impregnavimas po montavimo ir greitas nušluostymas.\n\nVanduo siūlėse. Tai ne marmuro, o siūlių problema. Sprendimas: epoksidinė arba silikoninė siūlė, pagrindo hidroizoliacija po plytelėmis, nuolydis grindyse. Stalviršius po praustuvu gaminame su bortu arba be jo, priklausomai nuo mazgo."},{"heading":"Kurias rūšis rinktis — Bianco Carrara, Crema Marfil ar Nero Marquina?","body":"Bianco Carrara: šviesiai pilkas fonas su švelniomis pilkomis gyslomis. Universaliausias, paslepia vandenį ir žymes, gerai atrodo matinėje apdailoje. Tinka stalviršiams ir sienoms.\n\nCrema Marfil: kreminis smėlinis, šiltas, beveik be kontrasto. Vizualiai padidina kambarį, paslepia kalkių nuosėdas. Vienas praktiškiausių marmurų drėgnoms zonoms.\n\nNero Marquina: juodas su baltomis gyslomis. Labai efektingas, bet ant jo matosi kiekvienas išdžiūvęs lašas ir rūgšties pėdsakai. Rekomenduojame sienoms, lentynoms ir akcentams, o stalviršiui po praustuvu — tik jei pasiryžę šluostyti sausai."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Bianco Carrara","šviesus su pilkomis gyslomis","Stalviršiai, sienos, matinė apdaila"],["Crema Marfil","šiltas smėlinis","Praktiškiausias drėgnai zonai"],["Nero Marquina","tamsus kontrastingas","Matomi vandens ir rūgščių pėdsakai"],["Emperador Dark","tamsiai rudas","Akcentinės sienos, lentynos"]]},"faq":[{"question":"Ar marmuras bijo vandens?","answer":"Ne. Vanduo marmuro nenaikina; kenkia rūgštys ir nešvarumai, patenkantys į poras. Impregnuotas akmuo vonioje elgiasi kaip bet kuris kitas paviršius."},{"question":"Kaip dažnai impregnuoti?","answer":"Kartą per metus stalviršį ir grindis, kartą per dvejus metus sienas. Orientyras — vandens testas: jei lašas įsigeria per kelias minutes, laikas atnaujinti apsaugą."},{"question":"Ką daryti su rūgšties dėme?","answer":"Matinis rūgšties pėdsakas — ne nešvarumas, o išėsdintas paviršius. Smulkūs pėdsakai ant matinio marmuro mažai pastebimi; ant poliruoto juos pašalina meistras šlifuodamas ir poliruodamas vietoje."},{"question":"Kuo pakeisti marmurą?","answer":"Kvarcitu Taj Mahal, jei reikia šviesaus natūralaus akmens be jautrumo rūgštims, arba kvarcu ar keraminiu granitu su marmuro dekoru, jei svarbus visiškas porų nebuvimas."}]},"pl":{"title":"Marmur w łazience: za i przeciw","h1":"Marmur w łazience — czy warto i jak wybrać","description":"Marmur w łazience: zalety, ryzyka, pielęgnacja i które odmiany wybrać. Bianco Carrara, Crema Marfil czy Nero Marquina — co lepsze do strefy mokrej.","dek":"Jak zaprojektować strefę mokrą z naturalnym marmurem.","intro":"Łazienka to najlepsze miejsce dla marmuru w domu. Nie ma tu gorących naczyń i noży, jest woda, miękkie światło i pragnienie spokoju, dla którego ten kamień został stworzony. Problemy z marmurem w łazience wynikają nie z materiału, lecz z niewłaściwego detalu, kosmetyków z kwasami i środków do czyszczenia sanitariatów. Opowiadamy, jak tego uniknąć.","sections":[{"heading":"Czy marmur nadaje się do łazienki?","body":"Tak, pod trzema warunkami. Pierwszy: powierzchnia jest zaimpregnowana środkiem ochronnym, a impregnację odnawia się raz w roku. Drugi: wszystkie spoiny na blacie i przy ścianach są uszczelnione, a na podłodze jest spadek do odpływu. Trzeci: w domu nie używa się środków z kwasem do usuwania osadu z kamienia.\n\nPrzy tych warunkach marmurowy blat pod umywalkę, parapet lub okładzina ściany służą dekady. Włoskie i hiszpańskie łazienki z marmurem sprzed stu lat są tego potwierdzeniem."},{"heading":"Jakie są zalety marmuru w łazience?","body":"Rysunek. Żaden materiał inżynieryjny nie powtarza głębi żyłek Carrary ani ciepła Crema Marfil. Marmur daje poczucie spa nawet w małym pomieszczeniu.\n\nChłód i higiena. Polerowany marmur łatwo się wyciera, nie zbiera kurzu, a blat pod umywalkę nablatową wykonuje się bez spoin na widocznej płaszczyźnie.\n\nZgodność. Marmur łączy się z mosiądzem, chromem, drewnem i mikrocementem. Jeden kamień można poprowadzić po blacie, parapecie i półce w prysznicu, a pomieszczenie stanie się spójne."},{"heading":"Jakie są ryzyka i jak ich uniknąć?","body":"Wytrawianie kwasami. Cytryna, ocet, środki na osad wapienny i część kosmetyków zostawiają na polerowanym marmurze matowe plamy. Rozwiązanie: neutralna chemia do kamienia i wykończenie matowe, na którym ślady prawie nie są widoczne.\n\nPlamy z olejów i barwników. Olejki do ciała, farba do włosów, krem mogą wniknąć w pory. Rozwiązanie: impregnacja po montażu i szybkie wycieranie.\n\nWoda w spoinach. To problem nie marmuru, lecz spoin. Rozwiązanie: spoina epoksydowa lub silikonowa, hydroizolacja podłoża pod płytkami, spadek na podłodze. Blaty pod umywalkę wykonujemy z obrzeżem lub bez, zależnie od detalu."},{"heading":"Które odmiany wybrać — Bianco Carrara, Crema Marfil czy Nero Marquina?","body":"Bianco Carrara: jasnoszare tło z miękkimi szarymi żyłkami. Najbardziej uniwersalny, ukrywa wodę i ślady, dobrze wygląda w wykończeniu matowym. Nadaje się na blaty i ściany.\n\nCrema Marfil: kremowo-beżowy, ciepły, niemal bez kontrastu. Optycznie powiększa pomieszczenie, ukrywa osad wapienny. Jeden z najpraktyczniejszych marmurów do stref mokrych.\n\nNero Marquina: czarny z białymi żyłkami. Bardzo efektowny, ale widać na nim każdą kroplę po wyschnięciu i ślady kwasu. Polecamy na ściany, półki i akcenty, a na blat pod umywalkę — tylko przy gotowości wycierania do sucha."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Bianco Carrara","jasny z szarymi żyłami","Blaty, ściany, wykończenie matowe"],["Crema Marfil","ciepły beż","Najpraktyczniejszy do strefy mokrej"],["Nero Marquina","ciemny kontrastowy","Widoczne ślady wody i kwasów"],["Emperador Dark","ciemnobrązowy","Ściany akcentowe, półki"]]},"faq":[{"question":"Czy marmur boi się wody?","answer":"Nie. Woda nie niszczy marmuru; szkodzą kwasy i zabrudzenia wnikające w pory. Zaimpregnowany kamień w łazience zachowuje się jak każda inna powierzchnia."},{"question":"Jak często impregnować?","answer":"Raz w roku blat i podłogę, raz na dwa lata ściany. Orientacyjnie — test wodny: jeśli kropla wsiąka w kilka minut, czas odnowić ochronę."},{"question":"Co zrobić z plamą od kwasu?","answer":"Matowy ślad po kwasie to nie brud, lecz wytrawiona powierzchnia. Drobne ślady na matowym marmurze są mało widoczne; na polerowanym usuwa je fachowiec szlifowaniem i polerowaniem na miejscu."},{"question":"Czym zastąpić marmur?","answer":"Kwarcytem Taj Mahal, jeśli potrzebny jest jasny kamień naturalny bez wrażliwości na kwasy, albo kwarcem lub gresem z dekorem marmurowym, jeśli liczy się całkowity brak porów."}]}}'::jsonb) where slug = 'marmur-u-vanniy-kimnati';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Pflege der Granitarbeitsplatte: Regeln und Fehler","h1":"Pflege der Granitarbeitsplatte — Regeln Schritt für Schritt","description":"Pflege der Granitarbeitsplatte: tägliche Reinigung, sichere Mittel, Imprägnierung, Entfernen von Öl- und Weinflecken, typische Fehler.","dek":"Die tägliche Routine ohne Säuren, Scheuermittel und zufällige Chemie.","intro":"Eine Granitarbeitsplatte braucht keine besondere Pflege, aber die richtige. Die meisten Probleme, mit denen man zu uns kommt, sind die Folge von einem von drei Dingen: aggressive Chemie, vergessene Imprägnierung oder der Versuch, einen Fleck mit Scheuermittel wegzureiben. Hier die kurze Anleitung, die wir Kunden mit der Platte übergeben.","sections":[{"heading":"Wie reinigt man Granit täglich?","body":"Warmes Wasser, weiches Tuch oder Schwamm, ein paar Tropfen neutrales Reinigungsmittel. Abwischen, mit klarem Wasser nachspülen, trocken reiben, damit auf dunklem Stein keine Schlieren bleiben. Das ist die ganze tägliche Routine.\n\nVerschüttetes sofort aufnehmen, besonders Öl, Wein, Kaffee und Rote Bete. Imprägnierter Granit saugt sie nicht in einer Minute auf, aber über Nacht kann unter einer Öllache ein Schatten bleiben. Keine nassen Tüten und rostigen Dosen auf der Fläche lassen: Rost dringt in die Poren."},{"heading":"Welche Mittel sind erlaubt und welche verboten?","body":"Erlaubt: Mittel mit der Aufschrift „für Naturstein“ oder „pH-neutral“, gewöhnliches Spülmittel in kleiner Menge, Isopropylalkohol zum Entfetten vor der Imprägnierung.\n\nVerboten: Essig, Zitronensäure, Kalkentferner, Chlor und Backofenreiniger, Scheuerpulver, Melaminschwämme, Metallschaber. Säuren und Laugen zerstören die Imprägnierung und mattieren mit der Zeit die Politur, Scheuermittel hinterlassen Kratzer, die im Gegenlicht sichtbar sind."},{"heading":"Ist eine Imprägnierung nötig und wie oft?","body":"Ja. Die Imprägnierung füllt die Mikroporen und lässt Flüssigkeiten nicht eindringen. Wir tragen sie nach der Montage auf, danach erneuert der Besitzer sie selbst.\n\nDie Häufigkeit bestimmt der Wassertest, nicht der Kalender. Gießen Sie einen Esslöffel Wasser auf die Arbeitszone bei der Spüle und warten Sie 15 Minuten. Ist der Stein unter dem Wasser dunkler geworden, ist es Zeit, die Imprägnierung zu erneuern. Bei poliertem Granit ist das meist alle ein bis drei Jahre, bei mattem öfter.\n\nVorgehen: Oberfläche reinigen und trocknen, Imprägnierung mit dem Schwamm dünn auftragen, nach Anleitung einwirken lassen (meist 10–20 Minuten), Reste trocken abwischen. Überschuss, der auf der Oberfläche trocknet, gibt Flecken, deshalb gründlich abwischen."},{"heading":"Was tun bei einem Öl- oder Weinfleck?","body":"Frischer Fleck: mit Küchenpapier abtupfen, nicht reiben, und mit neutralem Mittel abwaschen. In den meisten Fällen reicht das.\n\nAlter Fettfleck: eine Paste aus Natron und Wasser in Sahnekonsistenz anrühren, 5 mm dick auf den Fleck auftragen, mit Folie abdecken und 12–24 Stunden lassen. Die Paste zieht das Öl aus den Poren. Abnehmen, abwaschen, bei Bedarf wiederholen.\n\nOrganischer Fleck (Wein, Kaffee, Saft): dieselbe Paste, aber mit 3 % Wasserstoffperoxid statt Wasser. Auf dunklem Granit zuerst an einer unauffälligen Stelle testen. Rost und unbekannte Flecken zeigen Sie besser uns: Ein Gesamtfoto und eine Nahaufnahme reichen für einen Rat."},{"heading":"Was darf man niemals tun?","body":"Nicht ohne Brett auf dem Stein schneiden: Dem Granit passiert nichts, aber die Messer sind in einer Woche stumpf. Nicht auf die Platte steigen und nicht auf den Überstand setzen: Die Platte ist für verteilte Last ausgelegt, nicht für punktuelle 80 kg an der Kante.\n\nKeine heiße Pfanne auf die Fuge zwischen den Platten oder auf den Ausschnitt am Kochfeld stellen: Lokale Überhitzung der Klebefuge kann sie schwächen. Der Granit selbst fürchtet keine Hitze. Keine Wachse und „Polituren“ aus dem Haushaltsregal verwenden: Sie hinterlassen einen klebrigen Film, der Schmutz sammelt und mit Steinpolitur nichts zu tun hat."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Tägliche Reinigung","Erlaubt","Weiches Tuch, neutrales Mittel, trocken wischen"],["Säuren und Scheuermittel","Verboten","Mattieren die Politur, zerstören die Imprägnierung"],["Heißes","Erlaubt","Nur Fugen und Ausschnittkanten meiden"],["Imprägnierung","Alle 1–3 Jahre","Häufigkeit bestimmt der Wassertest"],["Flecken","Natronpaste","Nicht mit Scheuermittel reiben"]]},"faq":[{"question":"Kann man auf Granit schneiden?","answer":"Der Stein leidet nicht unter dem Messer, aber das Messer wird schnell stumpf. Benutzen Sie ein Brett, das ist für beide angenehmer."},{"question":"Kann man Heißes abstellen?","answer":"Ja, Granit verträgt Geschirr vom Herd und aus dem Ofen. Der einzige Ort, an dem man besser einen Untersetzer nimmt, ist die Klebefuge zwischen den Platten."},{"question":"Wie entfernt man Fett?","answer":"Frisch — mit Spülmittel. Alt — mit einer Paste aus Natron und Wasser einen Tag unter Folie. Alkalische Küchenentfetter sollte man nicht verwenden."},{"question":"Wie bekommt man den Glanz zurück?","answer":"Ist die Oberfläche durch wachs- oder säurehaltige Mittel matt geworden, waschen Sie sie zuerst mit neutralem Mittel und Alkohol. Ist die Politur wirklich beschädigt, stellt sie ein Fachmann vor Ort mit Maschine und Diamantpasten wieder her."}]},"en":{"title":"How to care for a granite countertop: rules and mistakes","h1":"Caring for a granite countertop — step-by-step rules","description":"Caring for a granite countertop: daily cleaning, safe products, sealing, removing oil and wine stains, common mistakes.","dek":"A daily routine without acids, abrasives or random chemicals.","intro":"A granite countertop does not need special care, but it does need the right care. Most problems people bring to us result from one of three things: aggressive chemicals, forgotten sealing, or an attempt to scrub a stain with an abrasive. Here is the short set of rules we hand to clients together with the countertop.","sections":[{"heading":"How to clean granite daily?","body":"Warm water, a soft cloth or sponge, a few drops of neutral detergent. Wipe, rinse with clean water, dry off so no streaks remain on dark stone. That is the whole daily routine.\n\nWipe up spills immediately, especially oil, wine, coffee and beetroot. Sealed granite will not absorb them in a minute, but overnight under a puddle of oil a shadow may remain. Do not leave wet bags or rusty tins on the surface: rust penetrates the pores."},{"heading":"Which products are allowed and which are forbidden?","body":"Allowed: products labelled “for natural stone” or “pH-neutral”, ordinary washing-up liquid in a small amount, isopropyl alcohol for degreasing before sealing.\n\nForbidden: vinegar, citric acid, limescale removers, chlorine and oven cleaners, abrasive powders, melamine sponges, metal scrapers. Acids and alkalis destroy the sealant and dull the polish over time; abrasives leave scratches visible against the light."},{"heading":"Is sealing needed and how often?","body":"Yes. The sealant (impregnator) fills the micropores and stops liquids from penetrating. We apply it after installation; after that the owner renews it themselves.\n\nThe frequency is set by the water test, not the calendar. Pour a tablespoon of water on the work area by the sink and wait 15 minutes. If the stone under the water has darkened, it is time to renew the sealant. For polished granite that is usually every one to three years, for honed more often.\n\nProcedure: clean and dry the surface, apply the impregnator with a sponge in a thin layer, wait as instructed (usually 10–20 minutes), wipe off the excess dry. Excess that dries on the surface leaves marks, so wipe thoroughly."},{"heading":"What to do with an oil or wine stain?","body":"Fresh stain: blot with a paper towel without rubbing and wash with a neutral cleaner. In most cases that is enough.\n\nOld grease stain: make a paste of baking soda and water to the consistency of sour cream, apply a 5 mm layer over the stain, cover with film and leave for 12–24 hours. The paste draws the oil out of the pores. Remove, rinse, repeat if needed.\n\nOrganic stain (wine, coffee, juice): the same paste, but with 3 % hydrogen peroxide instead of water. On dark granite test first on an inconspicuous spot. Rust and unknown stains are best shown to us: an overall photo and a close-up are enough for advice."},{"heading":"What should you never do?","body":"Do not cut on the stone without a board: the granite will not suffer, but the knives will be blunt within a week. Do not stand on the counter or sit on the overhang: the slab is designed for distributed load, not a point load of 80 kg on the edge.\n\nDo not put a hot frying pan on the joint between slabs or at the cut-out by the hob: local overheating of the glued joint can weaken it. Granite itself is not afraid of heat. Do not use waxes or household “polishes”: they leave a sticky film that collects dirt and has nothing to do with stone polishing."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Daily cleaning","Allowed","Soft cloth, neutral cleaner, wipe dry"],["Acids and abrasives","Forbidden","Dull the polish, destroy the sealant"],["Heat","Allowed","Avoid only joints and cut-out edges"],["Sealing","Every 1–3 years","Frequency set by the water test"],["Stains","Baking soda paste","Do not rub with an abrasive"]]},"faq":[{"question":"Can I cut on granite?","answer":"The stone will not suffer from a knife, but the knife will quickly go blunt. Use a board, it is easier on both."},{"question":"Can I put hot things on it?","answer":"Yes, granite takes cookware from the hob and oven. The only place to put a trivet is the glued joint between slabs."},{"question":"How to remove grease?","answer":"Fresh — with washing-up liquid. Old — with a paste of baking soda and water for a day under film. Alkaline kitchen degreasers should not be used."},{"question":"How to bring back the shine?","answer":"If the surface has dulled from waxy or acidic products, first wash it with a neutral cleaner and alcohol. If the polish is really damaged, a craftsman restores it on site with a machine and diamond pastes."}]},"lt":{"title":"Kaip prižiūrėti granito stalviršį: taisyklės ir klaidos","h1":"Granito stalviršio priežiūra — taisyklės žingsnis po žingsnio","description":"Granito stalviršio priežiūra: kasdienis valymas, saugios priemonės, impregnavimas, aliejaus ir vyno dėmių šalinimas, tipinės klaidos.","dek":"Kasdienis algoritmas be rūgščių, abrazyvų ir atsitiktinės chemijos.","intro":"Granito stalviršiui nereikia specialios priežiūros, bet reikia teisingos. Dauguma problemų, su kuriomis į mus kreipiasi, — tai vienos iš trijų priežasčių pasekmės: agresyvios chemijos, pamiršto impregnavimo arba bandymo nutrinti dėmę abrazyvu. Štai trumpas reglamentas, kurį atiduodame klientams kartu su stalviršiu.","sections":[{"heading":"Kaip kasdien valyti granitą?","body":"Šiltas vanduo, minkšta šluostė ar kempinė, keli lašai neutralios plovimo priemonės. Nušluostėte, nuplovėte švariu vandeniu, nušluostėte sausai, kad ant tamsaus akmens neliktų dryžių. Tai visa kasdienė rutina.\n\nIšsipylusius skysčius nuvalykite iš karto, ypač aliejų, vyną, kavą ir burokėlius. Impregnuotas granitas jų per minutę neįgers, bet per naktį po aliejaus balute gali likti šešėlis. Nepalikite ant paviršiaus drėgnų maišelių ir surūdijusių skardinių: rūdys skverbiasi į poras."},{"heading":"Kokios priemonės galimos, o kokios draudžiamos?","body":"Galima: priemonės su užrašu „natūraliam akmeniui“ arba „pH neutrali“, paprasta indų plovimo priemonė nedideliu kiekiu, izopropilo alkoholis riebalų pašalinimui prieš impregnavimą.\n\nNegalima: actas, citrinos rūgštis, kalkių nuosėdų valikliai, chloras ir orkaičių valikliai, abrazyviniai milteliai, melamininės kempinės, metaliniai gremžtukai. Rūgštys ir šarmai ardo impregnavimą ir laikui bėgant matina poliravimą, abrazyvai palieka įbrėžimų, matomų prieš šviesą."},{"heading":"Ar reikia impregnuoti ir kaip dažnai?","body":"Taip. Impregnantas užpildo mikroporas ir neleidžia skysčiams prasiskverbti į vidų. Mes jį užtepame po montavimo, toliau savininkas atnaujina pats.\n\nPeriodiškumą nustato vandens testas, o ne kalendorius. Užpilkite šaukštą vandens darbo zonoje prie plautuvės ir palaukite 15 minučių. Jei akmuo po vandeniu patamsėjo, laikas atnaujinti impregnavimą. Poliruotam granitui tai paprastai kartą per vienerius–trejus metus, matiniam — dažniau.\n\nProcedūra: nuvalyti ir išdžiovinti paviršių, užtepti impregnantą kempine plonu sluoksniu, palaikyti pagal instrukciją (paprastai 10–20 minučių), nušluostyti likučius sausai. Perteklius, išdžiūvęs ant paviršiaus, palieka dėmes, todėl šluostyti reikia kruopščiai."},{"heading":"Ką daryti su aliejaus ar vyno dėme?","body":"Šviežia dėmė: nusausinti popieriniu rankšluosčiu netrinant ir nuplauti neutralia priemone. Dauguma atvejų to pakanka.\n\nSena riebalų dėmė: padaryti pastą iš sodos ir vandens grietinės konsistencijos, užtepti ant dėmės 5 mm sluoksniu, uždengti plėvele ir palikti 12–24 valandoms. Pasta ištraukia aliejų iš porų. Nuimti, nuplauti, esant reikalui pakartoti.\n\nOrganinė dėmė (vynas, kava, sultys): ta pati pasta, bet su 3 % vandenilio peroksidu vietoj vandens. Ant tamsaus granito pirmiausia patikrinkite nematomoje vietoje. Rūdis ir nežinomas dėmes geriau parodyti mums: bendro plano nuotraukos ir stambaus plano pakanka patarimui."},{"heading":"Ko niekada negalima daryti?","body":"Nepjaustyti ant akmens be lentelės: granitas nenukentės, o peiliai atšips per savaitę. Nestoti ant stalviršio ir nesėsti ant iškyšos: plokštė apskaičiuota paskirstytai apkrovai, o ne taškinei 80 kg ant krašto.\n\nNestatyti karštos keptuvės ant siūlės tarp plokščių ir išpjovos vietoje prie kaitlentės: vietinis klijų siūlės perkaitimas gali ją susilpninti. Pats granitas karščio nebijo. Nenaudoti vaškų ir buitinės chemijos „poliravimo priemonių“: jos sudaro lipnią plėvelę, kuri kaupia nešvarumus ir neturi nieko bendra su akmens poliravimu."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Kasdienis valymas","Galima","Minkšta šluostė, neutrali priemonė, nušluostyti sausai"],["Rūgštys ir abrazyvai","Negalima","Matina poliravimą, ardo impregnavimą"],["Karštis","Galima","Vengti tik siūlių ir išpjovų kraštų"],["Impregnavimas","Kartą per 1–3 metus","Periodiškumą nustato vandens testas"],["Dėmės","Sodos pasta","Netrinti abrazyvu"]]},"faq":[{"question":"Ar galima pjaustyti ant granito?","answer":"Akmuo nuo peilio nenukentės, bet peilis greitai atšips. Naudokite lentelę, taip patogiau abiem."},{"question":"Ar galima statyti karštus indus?","answer":"Taip, granitas atlaiko indus nuo viryklės ir iš orkaitės. Vienintelė vieta, kur geriau padėti padėklą, — klijų siūlė tarp plokščių."},{"question":"Kuo pašalinti riebalus?","answer":"Šviežius — indų plovikliu. Senus — sodos ir vandens pasta parai po plėvele. Šarminių virtuvės riebalų šalinimo priemonių naudoti neverta."},{"question":"Kaip sugrąžinti blizgesį?","answer":"Jei paviršius tapo blausus dėl priemonių su vašku ar rūgštimi, pirmiausia nuplaukite jį neutralia priemone ir alkoholiu. Jei poliravimas tikrai pažeistas, jį vietoje atkuria meistras mašinėle su deimantinėmis pastomis."}]},"pl":{"title":"Jak dbać o blat granitowy: zasady i błędy","h1":"Pielęgnacja blatu granitowego — zasady krok po kroku","description":"Pielęgnacja blatu granitowego: codzienne czyszczenie, bezpieczne środki, impregnacja, usuwanie plam z oleju i wina, typowe błędy.","dek":"Codzienny algorytm bez kwasów, środków ściernych i przypadkowej chemii.","intro":"Blat granitowy nie wymaga specjalnej pielęgnacji, ale wymaga właściwej. Większość problemów, z którymi do nas trafiają klienci, to skutek jednego z trzech: agresywnej chemii, zapomnianej impregnacji lub próby wytarcia plamy środkiem ściernym. Oto krótki regulamin, który przekazujemy klientom razem z blatem.","sections":[{"heading":"Jak codziennie czyścić granit?","body":"Ciepła woda, miękka ściereczka lub gąbka, kilka kropli neutralnego płynu. Przetrzeć, spłukać czystą wodą, wytrzeć do sucha, aby na ciemnym kamieniu nie zostawały smugi. To cała codzienna rutyna.\n\nRozlane płyny sprzątaj od razu, zwłaszcza olej, wino, kawę i buraki. Granit z impregnacją nie wciągnie ich w minutę, ale po nocy pod kałużą oleju może zostać cień. Nie zostawiaj na powierzchni mokrych torebek i zardzewiałych puszek: rdza wnika w pory."},{"heading":"Jakie środki można, a jakie są zabronione?","body":"Można: środki z napisem „do kamienia naturalnego” lub „pH-neutralny”, zwykły płyn do naczyń w małej ilości, alkohol izopropylowy do odtłuszczenia przed impregnacją.\n\nNie można: ocet, kwas cytrynowy, środki na osad wapienny, chlor i preparaty do piekarników, proszki ścierne, gąbki melaminowe, metalowe skrobaki. Kwasy i zasady niszczą impregnację i z czasem matowią połysk, środki ścierne zostawiają rysy widoczne pod światło."},{"heading":"Czy potrzebna jest impregnacja i jak często?","body":"Tak. Impregnat wypełnia mikropory i nie pozwala płynom wnikać do wnętrza. Nakładamy go po montażu, dalej właściciel odnawia go samodzielnie.\n\nCzęstotliwość wyznacza test wodny, a nie kalendarz. Wylej łyżkę wody na strefę roboczą przy zlewie i odczekaj 15 minut. Jeśli kamień pod wodą pociemniał, czas odnowić impregnację. Dla polerowanego granitu to zwykle raz na jeden–trzy lata, dla matowego częściej.\n\nProcedura: oczyścić i wysuszyć powierzchnię, nanieść impregnat gąbką cienką warstwą, odczekać według instrukcji (zwykle 10–20 minut), wytrzeć resztki do sucha. Nadmiar, który wyschnie na powierzchni, daje plamy, dlatego wycierać trzeba starannie."},{"heading":"Co zrobić z plamą z oleju lub wina?","body":"Świeża plama: osuszyć ręcznikiem papierowym bez rozcierania i umyć środkiem neutralnym. W większości przypadków to wystarczy.\n\nStara plama tłusta: zrobić pastę z sody oczyszczonej i wody o konsystencji śmietany, nałożyć na plamę warstwą 5 mm, przykryć folią i zostawić na 12–24 godziny. Pasta wyciąga olej z porów. Zdjąć, spłukać, w razie potrzeby powtórzyć.\n\nPlama organiczna (wino, kawa, sok): ta sama pasta, ale z 3 % nadtlenkiem wodoru zamiast wody. Na ciemnym granicie najpierw sprawdź w niewidocznym miejscu. Rdzę i nieznane plamy lepiej pokazać nam: zdjęcie ogólne i zbliżenie wystarczą do porady."},{"heading":"Czego nigdy nie robić?","body":"Nie kroić na kamieniu bez deski: granit nie ucierpi, ale noże stępią się w tydzień. Nie stawać na blacie i nie siadać na nawisie: płyta jest obliczona na obciążenie rozłożone, a nie punktowe 80 kg na krawędzi.\n\nNie stawiać gorącej patelni na spoinie między płytami ani w miejscu wycięcia przy płycie grzewczej: miejscowe przegrzanie spoiny klejowej może ją osłabić. Sam granit gorącego się nie boi. Nie używać wosków i „politur” z chemii gospodarczej: dają lepką powłokę, która zbiera brud i nie ma nic wspólnego z polerowaniem kamienia."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Codzienne czyszczenie","Można","Miękka ściereczka, środek neutralny, wytrzeć do sucha"],["Kwasy i środki ścierne","Nie można","Matowią połysk, niszczą impregnację"],["Gorące","Można","Unikać tylko spoin i krawędzi wycięć"],["Impregnacja","Raz na 1–3 lata","Częstotliwość wyznacza test wodny"],["Plamy","Pasta z sody","Nie trzeć środkiem ściernym"]]},"faq":[{"question":"Czy można kroić na granicie?","answer":"Kamień od noża nie ucierpi, ale nóż szybko się stępi. Używaj deski, to wygodniejsze dla obu."},{"question":"Czy można stawiać gorące?","answer":"Tak, granit wytrzymuje naczynia z kuchenki i piekarnika. Jedyne miejsce, gdzie lepiej podłożyć podkładkę, to spoina klejowa między płytami."},{"question":"Czym usunąć tłuszcz?","answer":"Świeży — płynem do naczyń. Stary — pastą z sody i wody na dobę pod folią. Odtłuszczaczy kuchennych z zasadą lepiej nie używać."},{"question":"Jak przywrócić połysk?","answer":"Jeśli powierzchnia zmatowiała od środków z woskiem lub kwasem, najpierw umyj ją środkiem neutralnym i alkoholem. Jeśli połysk jest naprawdę uszkodzony, odnawia go fachowiec na miejscu maszyną z pastami diamentowymi."}]}}'::jsonb) where slug = 'yak-doglyadaty-za-granitnoyu-stilnytseyu';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Marmorpflege: reinigen und Flecken entfernen","h1":"Wie man Marmor pflegt und Flecken entfernt","description":"Marmorpflege: sichere Mittel, was den Stein zerstört, wie man organische, Fett- und Rostflecken entfernt, wie oft imprägnieren.","dek":"Sichere Pflege einer Kalzitoberfläche ohne Säuren.","intro":"Marmor besteht aus Kalzit, und Kalzit löst sich in Säuren. Das ist das Einzige, was man sich merken muss, und daraus folgt die ganze Pflege: keine säurehaltigen Mittel, schnelles Abwischen, regelmäßige Imprägnierung. Der Rest ist nicht schwieriger als die Pflege jeder anderen Oberfläche.","sections":[{"heading":"Wie reinigt man Marmor sicher?","body":"Täglich: warmes Wasser und weiches Tuch. Einmal pro Woche: neutraler Steinreiniger nach Anleitung verdünnt, dann klares Wasser und ein trockenes Tuch. Auf poliertem Marmor ist trockenes Nachwischen wichtig, sonst bleiben nach dem Trocknen Tropfenspuren, besonders auf dunklen Sorten.\n\nHalten Sie fürs Bad eine eigene Flasche Steinreiniger bereit und verwenden Sie auf der Platte nicht, womit Sie WC oder Armatur putzen. Die meisten Sanitärreiniger enthalten Säure gegen Kalk."},{"heading":"Welche Mittel zerstören Marmor?","body":"Säuren: Essig, Zitrone, Entkalker und Kalkentferner, manche Glas- und Fliesenreiniger. Sie verschmutzen nicht, sie ätzen: In wenigen Minuten erscheint auf der polierten Fläche ein matter tropfenförmiger Fleck.\n\nLaugen und Chlor: Bleichmittel und Backofenreiniger zerfressen die Imprägnierung und entfärben farbigen Marmor. Scheuermittel: Pulver, Melaminschwämme, harte Bürsten zerkratzen den Kalzit, der weicher als Sand ist.\n\nKosmetik: Körperöle, Haarfarbe, manche alkoholhaltigen Parfüms mit Farbstoffen. Stellen Sie Flakons auf ein Tablett und wischen Sie Tropfen sofort ab."},{"heading":"Wie entfernt man organische, Fett- und Rostflecken?","body":"Bestimmen Sie zuerst den Typ. Ein matter Fleck ohne Farbe ist eine Säureätzung, die wird nicht gewaschen, sondern poliert. Ein farbiger Fleck in den Poren ist Schmutz, der mit einer Kompresse herausgezogen wird.\n\nOrganisch (Kaffee, Tee, Wein, Kosmetik): eine Paste aus weißem Küchenpapier oder Stärke, mit 3 % Wasserstoffperoxid befeuchtet, 12–24 Stunden unter Folie. Fett (Öl, Creme): Paste aus Natron und Wasser, gleiche Dauer. Rost: nur spezielle säurefreie Marmorpasten; Haushaltsrostentferner enthalten Säure und ruinieren den Stein.\n\nNach der Kompresse wird die Fläche abgewaschen, getrocknet und bei Bedarf wiederholt. Die Imprägnierung nach dem Entfernen des Flecks unbedingt erneuern."},{"heading":"Wie oft Marmor imprägnieren?","body":"Im Bad einmal im Jahr für Platte und Boden, alle zwei Jahre für Wände. Auf der Fensterbank oder dem Tisch in der Küche einmal im Jahr. Der Test ist derselbe wie bei Granit: ein Wassertropfen, 10 Minuten, ein dunkler Fleck bedeutet, es ist Zeit.\n\nWichtig zu verstehen: Die Imprägnierung schützt vor Flecken, aber nicht vor Säuren. Eine matte (honed) Oberfläche hilft zusätzlich gegen Ätzungen: Säurespuren sind darauf kaum sichtbar, und für ein viel genutztes Bad empfehlen wir genau sie."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Organischer Fleck","Kompresse mit Peroxid","Zuerst an unauffälliger Stelle testen"],["Fett","Natronpaste","Nicht reiben, der Kompresse Zeit geben"],["Rost","Säurefreie Marmorpaste","Haushaltsrostentferner verboten"],["Säureätzung","Politur durch den Fachmann","Lässt sich nicht abwaschen, ist eine Oberflächenveränderung"]]},"faq":[{"question":"Darf man Essig oder Zitrone verwenden?","answer":"Nein. Beide ätzen Kalzit in Minuten. Ablagerungen auf Marmor entfernt man mit neutralen Steinreinigern oder einer milden Natronpaste."},{"question":"Wie entfernt man Kaffee oder Wein?","answer":"Frisch — mit Wasser und Tuch. Was bereits eingezogen ist — mit einer Kompresse aus 3 % Wasserstoffperoxid für 12–24 Stunden unter Folie."},{"question":"Wie bekommt man den Glanz zurück?","answer":"Haushalts-„Polituren“ helfen nicht. Eine durch Säuren matt gewordene Fläche stellt ein Fachmann wieder her: Schleifen, Polieren und neue Imprägnierung vor Ort in wenigen Stunden."},{"question":"Ist eine jährliche Behandlung nötig?","answer":"Ja, Imprägnierung einmal im Jahr für Platten und Böden in Nassbereichen. Das sind 20 Minuten Arbeit mit dem Schwamm und der günstigste Weg, das Leben des Marmors zu verlängern."}]},"en":{"title":"Marble care: how to clean and remove stains","h1":"How to care for marble and remove stains","description":"Marble care: safe products, what destroys the stone, how to remove organic, grease and rust stains, how often to seal.","dek":"Safe care for a calcite surface without acids.","intro":"Marble consists of calcite, and calcite dissolves in acids. That is the only thing to remember, and all care follows from it: no acidic products, quick wiping, regular sealing. The rest is no harder than caring for any other surface.","sections":[{"heading":"How to clean marble safely?","body":"Daily: warm water and a soft cloth. Weekly: a neutral stone cleaner diluted as instructed, then clean water and a dry cloth. On polished marble it is important to wipe dry, otherwise drop marks remain after drying, especially on dark varieties.\n\nFor the bathroom keep a separate bottle of stone cleaner and do not use on the top what you wash the toilet or tap with. Most sanitary cleaners contain acid against limescale."},{"heading":"Which products destroy marble?","body":"Acids: vinegar, lemon, descalers and limescale removers, some glass and tile cleaners. They do not stain but etch: within minutes a matte drop-shaped spot appears on a polished surface.\n\nAlkalis and chlorine: bleaches and oven cleaners eat away the sealant and discolour coloured marble. Abrasives: powders, melamine sponges, stiff brushes scratch calcite, which is softer than sand.\n\nCosmetics: body oils, hair dye, some alcohol-based perfumes with dyes. Put bottles on a tray and wipe drops immediately."},{"heading":"How to remove organic, grease and rust stains?","body":"First identify the type. A matte colourless spot is acid etching; it is not washed but polished. A coloured stain in the pores is dirt that is drawn out with a poultice.\n\nOrganic (coffee, tea, wine, cosmetics): a paste of white paper towel or starch moistened with 3 % hydrogen peroxide, under film for 12–24 hours. Grease (oil, cream): a paste of baking soda and water, the same time. Rust: only special acid-free marble pastes; household rust removers contain acid and will ruin the stone.\n\nAfter the poultice the surface is rinsed, dried and the treatment repeated if needed. Always renew the sealant after removing a stain."},{"heading":"How often to seal marble?","body":"In the bathroom once a year for the top and floor, once every two years for walls. On a kitchen window sill or table — once a year. The test is the same as for granite: a drop of water, 10 minutes, a dark spot means it is time.\n\nIt is important to understand that sealing protects against stains but not against acids. A honed finish also helps against etching: acid marks are almost invisible on it, and for a busy bathroom we recommend exactly that."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Organic stain","Peroxide poultice","Test first on an inconspicuous spot"],["Grease","Baking soda paste","Do not rub, give the poultice time"],["Rust","Acid-free marble paste","Household rust removers are forbidden"],["Acid etching","Polishing by a craftsman","Cannot be washed off, it is a surface change"]]},"faq":[{"question":"Can I use vinegar or lemon?","answer":"No. Both etch calcite within minutes. Deposits on marble are removed with neutral stone cleaners or a mild baking soda paste."},{"question":"How to remove coffee or wine?","answer":"Fresh — with water and a cloth. What has soaked in — with a 3 % hydrogen peroxide poultice for 12–24 hours under film."},{"question":"How to bring back the shine?","answer":"Household “polishes” will not help. A surface dulled by acids is restored by a craftsman: grinding, polishing and new sealing on site within a few hours."},{"question":"Is an annual treatment needed?","answer":"Yes, sealing once a year for tops and floors in wet zones. It is 20 minutes of work with a sponge and the cheapest way to extend the life of marble."}]},"lt":{"title":"Marmuro priežiūra: kaip valyti ir šalinti dėmes","h1":"Kaip prižiūrėti marmurą ir šalinti dėmes","description":"Marmuro priežiūra: saugios priemonės, kas ardo akmenį, kaip pašalinti organines, riebalų ir rūdžių dėmes, kaip dažnai impregnuoti.","dek":"Saugi kalcitinio paviršiaus priežiūra be rūgščių.","intro":"Marmuras sudarytas iš kalcito, o kalcitas tirpsta rūgštyse. Tai vienintelis dalykas, kurį reikia atsiminti, ir iš to kyla visa priežiūra: jokių rūgštinių priemonių, greitas nušluostymas, reguliarus impregnavimas. Kita nesudėtingesnė nei bet kurio kito paviršiaus priežiūra.","sections":[{"heading":"Kaip saugiai valyti marmurą?","body":"Kasdien: šiltas vanduo ir minkšta šluostė. Kartą per savaitę: neutrali akmens priemonė, atskiesta pagal instrukciją, paskui švarus vanduo ir sausa šluostė. Ant poliruoto marmuro svarbu nušluostyti sausai, kitaip išdžiūvus lieka lašų pėdsakai, ypač ant tamsių rūšių.\n\nVoniai laikykite atskirą akmens priemonės buteliuką ir nenaudokite ant stalviršio to, kuo plaunate unitazą ar maišytuvą. Dauguma santechnikos priemonių turi rūgšties prieš kalkių nuosėdas."},{"heading":"Kokios priemonės ardo marmurą?","body":"Rūgštys: actas, citrina, nuovirų ir nuosėdų valikliai, kai kurios stiklo ir plytelių priemonės. Jos ne teršia, o ėsdina: per kelias minutes ant poliruoto paviršiaus atsiranda matinė lašo formos dėmė.\n\nŠarmai ir chloras: balikliai ir orkaičių valikliai ardo impregnavimą ir blukina spalvotą marmurą. Abrazyvai: milteliai, melamininės kempinės, kieti šepečiai braižo kalcitą, kuris minkštesnis už smėlį.\n\nKosmetika: kūno aliejai, plaukų dažai, kai kurie alkoholiniai kvepalai su dažikliais. Statykite buteliukus ant padėklo ir nušluostykite lašus iš karto."},{"heading":"Kaip pašalinti organines, riebalų ir rūdžių dėmes?","body":"Pirmiausia nustatykite tipą. Matinė dėmė be spalvos — tai ėsdinimas rūgštimi, jos neplaunama, o poliruojama. Spalvota dėmė porose — tai nešvarumas, kuris ištraukiamas kompresu.\n\nOrganinės (kava, arbata, vynas, kosmetika): pasta iš balto popierinio rankšluosčio ar krakmolo, sudrėkinta 3 % vandenilio peroksidu, po plėvele 12–24 valandoms. Riebalų (aliejus, kremas): sodos ir vandens pasta, tas pats laikas. Rūdys: tik specialios pastos marmurui be rūgšties; buitinės rūdžių šalinimo priemonės turi rūgšties ir sugadins akmenį.\n\nPo kompreso paviršius nuplaunamas, išdžiovinamas ir esant reikalui kartojama. Impregnavimą po dėmės pašalinimo atnaujinti būtina."},{"heading":"Kaip dažnai impregnuoti marmurą?","body":"Vonioje kartą per metus stalviršį ir grindis, kartą per dvejus metus sienas. Ant virtuvės palangės ar stalo — kartą per metus. Testas tas pats, kaip granitui: vandens lašas, 10 minučių, tamsi dėmė reiškia, kad laikas.\n\nSvarbu suprasti, kad impregnavimas saugo nuo dėmių, bet ne nuo rūgščių. Matinė (honed) apdaila padeda ir nuo ėsdinimo: ant jos rūgšties pėdsakai beveik nematomi, ir aktyviai vonioje rekomenduojame būtent ją."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Organinė dėmė","Kompresas su peroksidu","Pirmiausia testas nematomoje vietoje"],["Riebalų","Sodos pasta","Netrinti, duoti kompresui laiko"],["Rūdys","Pasta marmurui be rūgšties","Buitinės rūdžių priemonės draudžiamos"],["Rūgštinis ėsdinimas","Meistro poliravimas","Nenusiplauna, tai paviršiaus pokytis"]]},"faq":[{"question":"Ar galima actą arba citriną?","answer":"Ne. Abu išėsdina kalcitą per minutes. Nuosėdas nuo marmuro šalina neutraliomis akmens priemonėmis arba švelnia sodos pasta."},{"question":"Kuo pašalinti kavą ar vyną?","answer":"Šviežią — vandeniu ir šluoste. Tai, kas spėjo įsigerti, — kompresu su 3 % vandenilio peroksidu 12–24 valandoms po plėvele."},{"question":"Kaip sugrąžinti blizgesį?","answer":"Buitinės „poliravimo priemonės“ nepadės. Nuo rūgščių apblausiusį paviršių atkuria meistras: šlifavimas, poliravimas ir naujas impregnavimas vietoje per kelias valandas."},{"question":"Ar reikia kasmetinio apdorojimo?","answer":"Taip, impregnavimas kartą per metus stalviršiams ir grindims drėgnose zonose. Tai 20 minučių darbo kempine ir pigiausias būdas prailginti marmuro gyvenimą."}]},"pl":{"title":"Pielęgnacja marmuru: jak czyścić i usuwać plamy","h1":"Jak dbać o marmur i usuwać plamy","description":"Pielęgnacja marmuru: bezpieczne środki, co niszczy kamień, jak usunąć plamy organiczne, tłuste i rdzawe, jak często impregnować.","dek":"Bezpieczna pielęgnacja powierzchni kalcytowej bez kwasów.","intro":"Marmur składa się z kalcytu, a kalcyt rozpuszcza się w kwasach. To jedyne, co trzeba zapamiętać, i z tego wynika cała pielęgnacja: żadnych środków kwasowych, szybkie wycieranie, regularna impregnacja. Reszta nie jest trudniejsza niż pielęgnacja każdej innej powierzchni.","sections":[{"heading":"Jak bezpiecznie czyścić marmur?","body":"Codziennie: ciepła woda i miękka ściereczka. Raz w tygodniu: neutralny środek do kamienia rozcieńczony według instrukcji, potem czysta woda i sucha ściereczka. Na polerowanym marmurze ważne jest wycieranie do sucha, inaczej po wyschnięciu zostają ślady kropli, zwłaszcza na ciemnych odmianach.\n\nDo łazienki trzymaj osobną butelkę środka do kamienia i nie używaj na blacie tego, czym myjesz sedes czy baterię. Większość środków do sanitariatów zawiera kwas przeciw osadowi wapiennemu."},{"heading":"Jakie środki niszczą marmur?","body":"Kwasy: ocet, cytryna, środki na kamień i osad, część środków do szyb i płytek. One nie brudzą, lecz wytrawiają: w kilka minut na polerowanej powierzchni pojawia się matowa plama w kształcie kropli.\n\nZasady i chlor: wybielacze i preparaty do piekarników niszczą impregnację i odbarwiają kolorowy marmur. Środki ścierne: proszki, gąbki melaminowe, twarde szczotki rysują kalcyt, który jest miększy od piasku.\n\nKosmetyki: olejki do ciała, farba do włosów, niektóre perfumy na alkoholu z barwnikami. Stawiaj flakony na podstawce i wycieraj krople od razu."},{"heading":"Jak usunąć plamy organiczne, tłuste i rdzawe?","body":"Najpierw określ typ. Matowa plama bez koloru to wytrawienie kwasem, jej się nie myje, lecz poleruje. Kolorowa plama w porach to zabrudzenie, które wyciąga się kompresem.\n\nOrganiczne (kawa, herbata, wino, kosmetyki): pasta z białego ręcznika papierowego lub skrobi zwilżona 3 % nadtlenkiem wodoru, pod folią na 12–24 godziny. Tłuste (olej, krem): pasta z sody i wody, ten sam czas. Rdza: tylko specjalne pasty do marmuru bez kwasu; domowe odrdzewiacze zawierają kwas i zniszczą kamień.\n\nPo kompresie powierzchnię spłukuje się, suszy i w razie potrzeby powtarza zabieg. Impregnację po usunięciu plamy koniecznie odnów."},{"heading":"Jak często impregnować marmur?","body":"W łazience raz w roku blat i podłogę, raz na dwa lata ściany. Na parapecie lub stole w kuchni — raz w roku. Test ten sam jak dla granitu: kropla wody, 10 minut, ciemna plama oznacza, że już czas.\n\nWażne, by rozumieć, że impregnacja chroni przed plamami, ale nie przed kwasami. Wykończenie matowe (honed) pomaga też przeciw wytrawianiu: ślady kwasu są na nim prawie niewidoczne i do intensywnie używanej łazienki polecamy właśnie je."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Plama organiczna","Kompres z nadtlenkiem","Najpierw test w niewidocznym miejscu"],["Tłusta","Pasta z sody","Nie rozcierać, dać kompresowi czas"],["Rdza","Pasta do marmuru bez kwasu","Domowe odrdzewiacze zabronione"],["Wytrawienie kwasem","Polerowanie przez fachowca","Nie zmywa się, to zmiana powierzchni"]]},"faq":[{"question":"Czy można ocet lub cytrynę?","answer":"Nie. Oba wytrawiają kalcyt w kilka minut. Osad na marmurze usuwa się neutralnymi środkami do kamienia lub delikatną pastą z sody."},{"question":"Czym usunąć kawę lub wino?","answer":"Świeże — wodą i ściereczką. To, co zdążyło wsiąknąć, kompresem z 3 % nadtlenkiem wodoru na 12–24 godziny pod folią."},{"question":"Jak przywrócić połysk?","answer":"Domowe „politury” nie pomogą. Powierzchnię zmatowiałą od kwasów odnawia fachowiec: szlifowanie, polerowanie i nowa impregnacja na miejscu w kilka godzin."},{"question":"Czy potrzebna jest coroczna obróbka?","answer":"Tak, impregnacja raz w roku dla blatów i podłóg w strefach mokrych. To 20 minut pracy gąbką i najtańszy sposób przedłużenia życia marmuru."}]}}'::jsonb) where slug = 'dogljad-za-marmurom-vanna';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Fensterbank aus Stein: Marmor oder Granit?","h1":"Fensterbank aus Stein — Marmor oder Granit?","description":"Fensterbank aus Stein: Marmor oder Granit, Dicke, Überstand, Montage und Pflege. Was für die Südseite, Blumentöpfe und Feuchtigkeit wählen.","dek":"Die Wahl des Gesteins für Sonne, Feuchtigkeit, Pflanzen und den täglichen Gebrauch.","intro":"Eine Fensterbank ist der einfachste Weg, Naturstein ins Haus zu holen: eine Platte, ein Montagetag und Jahrzehnte ohne Austausch. Die Frage ist nur das Gestein. Granit verträgt Blumentöpfe, Wasser und Sonne, ohne an Pflege zu erinnern; Marmor wirkt weicher und wärmer, verlangt aber Aufmerksamkeit. Wir erklären, wie wir wählen.","sections":[{"heading":"Was für die Fensterbank wählen?","body":"Für Küche, Kinderzimmer und Fensterbänke mit Pflanzen wählen Sie Granit: Grey Ukraine, Kometa Black oder Quarz, wenn eine helle gleichmäßige Farbe gewünscht ist. Für Schlafzimmer, Wohnzimmer und Bad, wo die Fensterbank als Ablage und nicht als Arbeitsfläche dient, passt Marmor Crema Marfil oder Bianco Carrara.\n\nGehen die Fenster nach Süden und stehen dunkle Gegenstände auf der Bank, bedenken Sie die Erwärmung: Dunkler Granit wird in der Sonne heiß, heller Marmor und Quarz bleiben kühl. Quarz aber nicht den ganzen Tag in direkte Sonne stellen: Das Harz kann über die Jahre den Farbton verändern."},{"heading":"Warum ist Granit für die Fensterbank besser als Marmor?","body":"Granit fürchtet weder Wasser unter Blumentöpfen, Säure aus Dünger, Tassenränder noch Katzenkrallen. Die Imprägnierung wird alle paar Jahre erneuert, nicht jährlich. Er ist härter, deshalb platzt die Kante nicht ab, wenn der Fensterrahmen oder der Wischmopp beim Putzen anstößt.\n\nMarmor gewinnt anderswo: Er fühlt sich angenehmer an, gibt einen hellen warmen Ton, den Granit nicht hat, und wirkt in klassischen Interieurs stimmig. Stehen die Töpfe auf Untersetzern und wird die Fensterbank nicht überschwemmt, hält Marmor nicht weniger lang."},{"heading":"Welche Vorteile hat Stein gegenüber Kunststoff und Holz?","body":"Stein vergilbt nicht, verzieht sich nicht durch den Heizkörper unten und die Sonne oben, nimmt keine Gerüche auf und zerkratzt nicht so wie PVC. Er ist schwerer, und das ist sein Vorteil: Die Platte liegt auf Mörtel und „spielt“ nicht, und eine tiefe Fensterbank von 400–600 mm trägt einen Menschen, der sich mit einem Buch daraufsetzt.\n\nHolz ist schön, braucht aber Lack und fürchtet Wasser unter Blumentöpfen. Stein wird einmal gesetzt und meist für die ganze Lebensdauer des Fensters, und beim Fenstertausch wird die Platte umgesetzt."},{"heading":"Wie laufen Fertigung und Montage ab?","body":"Aufmaß nach Einbau des Fensters und Verputzen der Laibungen: Wir erfassen Länge, Tiefe, Überstand, Kantenform und ob die Platte in die Laibungen greift. Standardüberstand 30–50 mm von der Wand, Dicke 20 mm, für tiefe Fensterbänke über 500 mm oder Längen über 2 m nehmen wir 30 mm.\n\nMontage: Die Platte wird auf Zementmörtel oder Montageschaum auf ausgeglichenem Untergrund mit leichtem Gefälle zum Raum gesetzt, höchstens 1–2 mm, damit sich Wasser vom Fenster nicht am Rahmen sammelt. Zwischen Platte und Rahmen bleibt eine Fuge von 3–5 mm für Dichtmasse, unter der Platte kommen Unterlagen, um die Lüftung des Heizkörpers nicht zu stören. Die Arbeit dauert einen Tag, nutzbar ist die Bank am nächsten Tag."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Festigkeit","Granit 6–7 nach Mohs","Marmor 3–4, weicher"],["Feuchtigkeit und Dünger","Granit praktischer","Marmor braucht Imprägnierung und Untersetzer"],["Sonne","Dunkler Granit erwärmt sich","Quarz nicht in direkte Sonne"],["Optik","Kontrastreich oder neutral","Marmor warm und fließend"],["Dicke","20 mm Standard","30 mm bei Länge über 2 m"]]},"faq":[{"question":"Was ist langlebiger?","answer":"Granit: Er ist härter und reagiert nicht auf Säuren. Marmor hält genauso lang, wenn er imprägniert und nicht überschwemmt wird."},{"question":"Fürchtet er Sonne oder Feuchtigkeit?","answer":"Granit und Marmor fürchten die Sonne nicht. Quarz kann in direkter Sonne über den ganzen Tag im Lauf der Jahre den Farbton ändern. Feuchtigkeit fürchtet keiner der Steine, nur Schmutz in den Poren schadet."},{"question":"Welche Dicke?","answer":"Standard 20 mm. Für lange Fensterbänke über 2 m, tiefe über 500 mm oder mit großem Überstand nehmen wir 30 mm."},{"question":"Ist eine Sonderform möglich?","answer":"Ja: abgerundete Ecken, Ausschnitte für Laibungen, eine Erkerfensterbank aus mehreren Platten, eine Fensterbank-Arbeitsplatte, die in die Küchenarbeitszone übergeht."}]},"en":{"title":"Stone window sill: marble or granite?","h1":"A stone window sill — marble or granite?","description":"Stone window sill: marble or granite, thickness, overhang, installation and care. What to choose for a sunny side, plants and moisture.","dek":"Choosing the stone for sun, moisture, plants and daily use.","intro":"A window sill is the simplest way to bring natural stone into a home: one slab, one day of installation and decades without replacement. The only question is the stone. Granite takes plant pots, water and sun without reminders about care; marble looks softer and warmer but asks for attention. We explain how we choose.","sections":[{"heading":"What to choose for a window sill?","body":"For the kitchen, children''s room and sills with plants choose granite: Grey Ukraine, Kometa Black, or quartz if you need a light uniform colour. For the bedroom, living room and bathroom, where the sill works as a shelf rather than a work surface, Crema Marfil or Bianco Carrara marble is appropriate.\n\nIf the windows face south and dark objects will stand on the sill, consider heating: dark granite gets hot in the sun, light marble and quartz stay cool. Do not, however, place quartz in direct sun all day: the resin can change shade over the years."},{"heading":"Why is granite better than marble for a sill?","body":"Granite is not afraid of water from under pots, acid from fertilisers, cup marks or a cat''s claws. The sealant is renewed every few years, not every year. It is harder, so the edge does not chip from a knock by the window frame or a mop during cleaning.\n\nMarble wins elsewhere: it is more pleasant to touch, gives a light warm tone that granite cannot, and looks right in classic interiors. If the pots stand on saucers and the sill is not flooded, marble lasts just as long."},{"heading":"What are the advantages of stone over plastic and wood?","body":"Stone does not yellow, does not warp from the radiator below and the sun above, does not absorb smells and does not scratch the way PVC does. It is heavier, and that is its advantage: the slab lies on mortar and does not “play”, and a deep 400–600 mm sill holds a person who sits on it with a book.\n\nWood is beautiful but needs varnish and fears water under pots. Stone is installed once and usually for the whole life of the window, and when the window is replaced the slab is reset."},{"heading":"How are fabrication and installation done?","body":"Measurement after the window is installed and the reveals plastered: we record the length, depth, overhang, edge shape and whether the slab goes into the reveals. The standard overhang is 30–50 mm from the wall, thickness 20 mm; for deep sills over 500 mm or lengths over 2 m we take 30 mm.\n\nInstallation: the slab is laid on cement mortar or installation foam on a levelled base with a slight slope towards the room, no more than 1–2 mm, so water from the window does not collect by the frame. A 3–5 mm gap is left between the slab and the frame for sealant, and pads are placed under the slab so as not to disturb the radiator''s ventilation. The work takes a day; the sill can be used the next day."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Strength","Granite 6–7 on Mohs","Marble 3–4, softer"],["Moisture and fertilisers","Granite is more practical","Marble needs sealing and saucers"],["Sun","Dark granite heats up","Quartz not for direct sun"],["Look","Contrasting or neutral","Marble is warm and flowing"],["Thickness","20 mm standard","30 mm for lengths over 2 m"]]},"faq":[{"question":"Which lasts longer?","answer":"Granite: it is harder and does not react to acids. Marble lasts just as long if it is sealed and not flooded."},{"question":"Is it afraid of sun or moisture?","answer":"Granite and marble are not afraid of sun. Quartz in direct sun all day can change shade over the years. None of the stones fears moisture; only dirt in the pores does harm."},{"question":"What thickness?","answer":"Standard 20 mm. For long sills over 2 m, deep ones over 500 mm or with a large overhang we take 30 mm."},{"question":"Is a non-standard shape possible?","answer":"Yes: rounded corners, cut-outs for reveals, a bay window sill from several slabs, a sill-countertop that flows into the kitchen work area."}]},"lt":{"title":"Palangė iš akmens: marmuras ar granitas?","h1":"Akmens palangė — marmuras ar granitas?","description":"Palangė iš akmens: marmuras ar granitas, storis, iškyša, montavimas ir priežiūra. Ką rinktis saulėtai pusei, vazonams ir drėgmei.","dek":"Uolienos pasirinkimas saulei, drėgmei, augalams ir kasdieniam naudojimui.","intro":"Palangė — paprasčiausias būdas pridėti į namus natūralaus akmens: viena plokštė, viena montavimo diena ir dešimtmečiai be keitimo. Klausimas tik uolienoje. Granitas atlaiko vazonus, vandenį ir saulę be priminimų apie priežiūrą; marmuras atrodo švelnesnis ir šiltesnis, bet prašo dėmesio. Paaiškiname, kaip renkamės mes.","sections":[{"heading":"Ką rinktis palangei?","body":"Virtuvei, vaikų kambariui ir palangėms su augalais rinkitės granitą: Grey Ukraine, Kometa Black arba kvarcą, jei reikia šviesios vienodos spalvos. Miegamajam, svetainei ir voniai, kur palangė dirba kaip lentyna, o ne darbo paviršius, tinka marmuras Crema Marfil arba Bianco Carrara.\n\nJei langai į pietus ir ant palangės stovės tamsūs daiktai, atsižvelkite į įkaitimą: tamsus granitas saulėje tampa karštas, šviesus marmuras ir kvarcas lieka vėsūs. Kvarco tačiau nestatykite tiesioginėje saulėje visą dieną: derva per metus gali pakeisti atspalvį."},{"heading":"Kuo granitas geresnis už marmurą palangei?","body":"Granitas nebijo vandens iš po vazonų, rūgšties iš trąšų, puodelių pėdsakų ir katės nagų. Impregnavimas atnaujinamas kartą per kelis metus, o ne kasmet. Jis kietesnis, todėl kraštas nenuskyla nuo smūgio lango rėmu ar šluoste valant.\n\nMarmuras laimi kitur: jis malonesnis liesti, suteikia šviesų šiltą toną, kurio granitas neturi, ir atrodo tinkamas klasikiniuose interjeruose. Jei vazonai stovi ant padėklų, o palangė neužliejama, marmuras tarnauja ne mažiau."},{"heading":"Kokie akmens privalumai prieš plastiką ir medieną?","body":"Akmuo negelsta, nesideformuoja nuo radiatoriaus apačioje ir saulės viršuje, neįgeria kvapų ir nesibraižo taip, kaip PVC. Jis sunkesnis, ir tame jo privalumas: plokštė guli ant skiedinio ir „nežaidžia“, o gili 400–600 mm palangė atlaiko žmogų, atsisėdusį ant jos su knyga.\n\nMediena graži, bet reikia lako ir bijo vandens po vazonais. Akmuo statomas vieną kartą ir paprastai visam lango tarnavimo laikui, o keičiant langą plokštė perstatoma."},{"heading":"Kaip vyksta gamyba ir montavimas?","body":"Matavimas po lango įstatymo ir angokraščių tinkavimo: fiksuojame ilgį, gylį, iškyšą, kraštų formą ir tai, ar plokštė įeina į angokraščius. Standartinė iškyša 30–50 mm nuo sienos, storis 20 mm, gilioms palangėms virš 500 mm arba ilgesnėms nei 2 m imame 30 mm.\n\nMontavimas: plokštė dedama ant cementinio skiedinio arba montavimo putų ant išlyginto pagrindo su nedideliu nuolydžiu į kambarį, ne daugiau 1–2 mm, kad vanduo nuo lango nesikauptų prie rėmo. Tarp plokštės ir rėmo paliekamas 3–5 mm tarpas hermetikui, po plokšte dedamos pakladės, kad nepažeisti radiatoriaus ventiliacijos. Darbai užima dieną, naudotis galima kitą dieną."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Tvirtumas","Granitas 6–7 pagal Mosą","Marmuras 3–4, minkštesnis"],["Drėgmė ir trąšos","Granitas praktiškesnis","Marmurui reikia impregnavimo ir padėklų"],["Saulė","Tamsus granitas įkaista","Kvarcas ne tiesioginei saulei"],["Išvaizda","Kontrastinga arba neutrali","Marmuras šiltas ir plastiškas"],["Storis","20 mm standartas","30 mm ilgesnėms nei 2 m"]]},"faq":[{"question":"Kas ilgaamžiškesnis?","answer":"Granitas: jis kietesnis ir nereaguoja į rūgštis. Marmuras tarnauja taip pat ilgai, jei jį impregnuoja ir neužlieja."},{"question":"Ar bijo saulės ar drėgmės?","answer":"Granitas ir marmuras saulės nebijo. Kvarcas tiesioginiuose spinduliuose visą dieną per metus gali pakeisti atspalvį. Drėgmės nebijo nė vienas akmuo, kenkia tik nešvarumai porose."},{"question":"Koks storis?","answer":"Standartas 20 mm. Ilgoms palangėms virš 2 m, gilioms virš 500 mm arba su didele iškyša imame 30 mm."},{"question":"Ar galima nestandartinė forma?","answer":"Taip: suapvalinti kampai, išpjovos angokraščiams, erkerio palangė iš kelių plokščių, palangė-stalviršis, pereinanti į virtuvės darbo zoną."}]},"pl":{"title":"Parapet z kamienia: marmur czy granit?","h1":"Kamienny parapet — marmur czy granit?","description":"Parapet z kamienia: marmur czy granit, grubość, nawis, montaż i pielęgnacja. Co wybrać na stronę południową, do kwiatów i wilgoci.","dek":"Wybór skały pod słońce, wilgoć, rośliny i codzienne użytkowanie.","intro":"Parapet to najprostszy sposób, by dodać do domu kamień naturalny: jedna płyta, jeden dzień montażu i dekady bez wymiany. Pytanie tylko o skałę. Granit wytrzymuje kwiaty, wodę i słońce bez przypominania o pielęgnacji; marmur wygląda miękcej i cieplej, ale wymaga uwagi. Wyjaśniamy, jak wybieramy my.","sections":[{"heading":"Co wybrać na parapet?","body":"Do kuchni, pokoju dziecięcego i parapetów z roślinami wybieraj granit: Grey Ukraine, Kometa Black lub kwarc, jeśli potrzebny jest jasny jednolity kolor. Do sypialni, salonu i łazienki, gdzie parapet pracuje jak półka, a nie powierzchnia robocza, pasuje marmur Crema Marfil lub Bianco Carrara.\n\nJeśli okna wychodzą na południe i na parapecie będą stać ciemne przedmioty, uwzględnij nagrzewanie: ciemny granit w słońcu staje się gorący, jasny marmur i kwarc pozostają chłodne. Kwarcu przy tym nie stawiaj w pełnym słońcu przez cały dzień: żywica z latami może zmienić odcień."},{"heading":"Czym granit jest lepszy od marmuru na parapet?","body":"Granit nie boi się wody spod doniczek, kwasu z nawozów, śladów po kubkach i kocich pazurów. Impregnację odnawia się raz na kilka lat, a nie co roku. Jest twardszy, więc krawędź nie odpryskuje od uderzenia ramą okna lub mopem podczas sprzątania.\n\nMarmur wygrywa w czym innym: jest przyjemniejszy w dotyku, daje jasny ciepły ton, którego granit nie ma, i wygląda na miejscu w klasycznych wnętrzach. Jeśli doniczki stoją na podstawkach, a parapetu się nie zalewa, marmur służy nie krócej."},{"heading":"Jakie są zalety kamienia nad plastikiem i drewnem?","body":"Kamień nie żółknie, nie odkształca się od grzejnika pod spodem i słońca z góry, nie chłonie zapachów i nie rysuje się tak, jak PVC. Jest cięższy i to jego zaleta: płyta leży na zaprawie i nie „gra”, a głęboki parapet 400–600 mm wytrzymuje człowieka, który usiadł na nim z książką.\n\nDrewno jest piękne, ale wymaga lakieru i boi się wody pod doniczkami. Kamień montuje się raz i zwykle na cały okres życia okna, a przy wymianie okna płytę przekłada się."},{"heading":"Jak wygląda wykonanie i montaż?","body":"Pomiar po montażu okna i wykończeniu ościeży: ustalamy długość, głębokość, nawis, kształt krawędzi i to, czy płyta wchodzi w ościeża. Standardowy nawis 30–50 mm od ściany, grubość 20 mm, dla głębokich parapetów powyżej 500 mm lub długości powyżej 2 m bierzemy 30 mm.\n\nMontaż: płytę układa się na zaprawie cementowej lub piance montażowej na wyrównanym podłożu z niewielkim spadkiem do pokoju, nie więcej niż 1–2 mm, aby woda z okna nie zbierała się przy ramie. Między płytą i ramą zostawia się szczelinę 3–5 mm pod uszczelniacz, pod płytą stawia się podkładki, aby nie zaburzać wentylacji grzejnika. Prace zajmują dzień, korzystać można następnego dnia."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Wytrzymałość","Granit 6–7 w skali Mohsa","Marmur 3–4, miększy"],["Wilgoć i nawozy","Granit praktyczniejszy","Marmur wymaga impregnacji i podstawek"],["Słońce","Ciemny granit się nagrzewa","Kwarc nie do pełnego słońca"],["Wygląd","Kontrastowy lub neutralny","Marmur ciepły i plastyczny"],["Grubość","20 mm standard","30 mm dla długości powyżej 2 m"]]},"faq":[{"question":"Co jest trwalsze?","answer":"Granit: jest twardszy i nie reaguje na kwasy. Marmur służy równie długo, jeśli się go impregnuje i nie zalewa."},{"question":"Czy boi się słońca lub wilgoci?","answer":"Granit i marmur nie boją się słońca. Kwarc w pełnym słońcu przez cały dzień może z latami zmienić odcień. Wilgoci nie boi się żaden z kamieni, szkodzą tylko zabrudzenia w porach."},{"question":"Jaka grubość?","answer":"Standard 20 mm. Dla długich parapetów powyżej 2 m, głębokich powyżej 500 mm lub z dużym nawisem bierzemy 30 mm."},{"question":"Czy można niestandardowy kształt?","answer":"Tak: zaokrąglone narożniki, wycięcia pod ościeża, parapet wykuszowy z kilku płyt, parapet-blat przechodzący w strefę roboczą kuchni."}]}}'::jsonb) where slug = 'pidvikonnya-z-kamenyu-marmur-granit';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Treppen aus Granit: Fertigung, Bearbeitung, Kosten","h1":"Granittreppen — wie sie gewählt und gefertigt werden","description":"Granittreppen: Belag- und Massivstufen, Oberfläche für außen und innen, Rutschhemmung, Stufenmaße und woraus sich die Kosten zusammensetzen.","dek":"Konstruktion, Oberfläche und sicheres Detail für innen und außen.","intro":"Granittreppen sind der langlebigste Teil eines Hauses: Vorbauten aus ukrainischem Granit stehen 50 Jahre ohne Reparatur. Doch gerade auf Treppen kosten Fehler am meisten, weil eine rutschige Stufe oder nicht abgeleitetes Wasser täglich spürbar sind. Wir erklären, wie wir Treppen für Häuser, Hausflure und Geschäfte planen.","sections":[{"heading":"Welche Granittreppen gibt es?","body":"Nach Konstruktion: Belagstufen (Trittstufen und Setzstufen aus 20–30-mm-Platten auf Betonunterbau) und Massivstufen (massive Blöcke von 100–150 mm, die selbst die Stufen sind). Belagstufen werden in 90 % der Fälle verwendet, in Häusern wie im Freien.\n\nNach Ort: innen (polierte oder matte Oberfläche, Setzstufen aus Holz oder Stein, Sockelleiste entlang der Wand) und außen (geflammte Oberfläche, Gefälle für Wasser, Tropfkante unter der Trittstufe, frostbeständiger Kleber)."},{"heading":"Belag- oder Massivstufen — was ist der Unterschied?","body":"Belagstufen sind leichter, günstiger und erlauben jede Oberfläche. Eine Trittstufe von 30 mm mit Tropfkante und eine Setzstufe von 20 mm werden auf den Betonlauf mit Steinkleber gesetzt. Daraus entstehen gerade, gewendelte und Spindeltreppen.\n\nMassivblöcke passen zu Landschaft und massiven Eingängen: Stützstufen im Garten, ein Vorbau im Stil „Stein aus dem Steinbruch“. Sie brauchen keinen Betonunterbau im klassischen Sinn, aber schweres Gerät für die Montage und kosten wegen der Materialmenge deutlich mehr."},{"heading":"Welche Bearbeitung braucht es für außen?","body":"Für Außentreppen ist Politur gefährlich: Bei Regen und Frost wird sie zur Eisbahn. Wir verwenden Flammen (die Oberfläche wird abgebrannt, die Kristalle platzen und ergeben eine rauhe Textur) oder Stocken (mechanisches Aufrauen). Beide Oberflächen sind auch nass rutschhemmend.\n\nEin Kompromiss für innen, wo man Glanz möchte: eine polierte Trittstufe mit geflammten oder sandgestrahlten Streifen von 30–40 mm Breite an der Kante. Sie wirken wie ein Antirutschband, ohne die Optik zu stören. Für außen sind zudem ein Gefälle der Trittstufe von 1–2 % vom Haus weg und eine Tropfkante unten wichtig, damit Wasser nicht auf die Setzstufe läuft und in der Fuge gefriert."},{"heading":"Wovon hängen die Kosten ab?","body":"Material: Ukrainischer Granit Grey Ukraine ist günstiger als Gabbro und Labradorit, Import kostet noch mehr. Dicke: Trittstufe 30 mm gegenüber 20 mm, Massivblöcke gesondert.\n\nGeometrie: Gerade Stufen in Standardbreite 300–330 mm sind günstiger als gewendelte und gebogene, jeder Ausschnitt für ein Geländer oder ein Sonderwinkel bedeutet Mehrarbeit. Oberfläche: Politur ist Basis, Flammen und Stocken sind teurer. Dazu Lieferung und Montage, die bei Treppen länger dauert als bei einer Arbeitsplatte, weil jedes Teil vor Ort angepasst wird.\n\nEinen Richtwert für Ihren Treppenlauf gibt der Rechner, den genauen Kostenvoranschlag nach dem Aufmaß des Betonunterbaus."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Politur","Innen, Vertikalen, Details","Nass rutschig, Streifen ergänzen"],["Schleifen (matt)","Innen, ruhige Oberfläche","Weniger rutschig, leichter zu pflegen"],["Flammen","Außen, Vorbauten, Terrassen","Rutschhemmende rauhe Textur"],["Stocken","Außen, öffentliche Eingänge","Gröbste Textur, Rampen"]]},"faq":[{"question":"Sind Granittreppen rutschig?","answer":"Polierte — ja, besonders nass. Geflammte und gestockte — nein, sie sind auch bei Regen und Frost rutschhemmend. Für innen lässt sich Glanz mit rutschhemmenden Streifen kombinieren."},{"question":"Wie lang kann eine Stufe maximal sein?","answer":"Aus einer 30-mm-Platte fertigen wir durchgehende Trittstufen bis 3 m, die Grenze ist das Plattenmaß. Längere Stufen werden aus zwei Platten mit Fuge in der Mitte oder über einem Auflager zusammengesetzt."},{"question":"Was für den Vorbau wählen?","answer":"Geflammter Grey Ukraine oder Kometa Black in 30 mm Dicke mit Tropfkante. Das ist die verbreitetste und zuverlässigste Lösung für das ukrainische Klima."},{"question":"Was kostet es?","answer":"Das hängt von Gestein, Dicke, Anzahl und Form der Stufen, Oberfläche und Montage ab. Geben Sie die Maße in den Rechner ein für einen Richtwert, die genaue Summe nennen wir nach dem Aufmaß."}]},"en":{"title":"Granite stairs: fabrication, finishing, cost","h1":"Granite stairs — how they are chosen and made","description":"Granite stairs: overlay and solid, finish for exteriors and interiors, slip resistance, step dimensions and what makes up the cost.","dek":"Structure, finish and a safe detail for interiors and exteriors.","intro":"Granite stairs are the most durable part of a house: porches of Ukrainian granite stand for 50 years without repair. But it is on stairs that mistakes cost the most, because a slippery step or undrained water is felt every day. We explain how we design stairs for houses, entrance halls and shops.","sections":[{"heading":"What kinds of granite stairs are there?","body":"By structure: overlay (treads and risers from 20–30 mm slabs on a concrete base) and solid (massive 100–150 mm blocks that are the steps themselves). Overlay stairs are used in 90 % of cases, both in houses and outdoors.\n\nBy location: interior (polished or honed finish, wooden or stone risers, a skirting along the wall) and exterior (flamed finish, a slope for water, a drip edge under the tread, frost-resistant adhesive)."},{"heading":"Overlay or solid — what is the difference?","body":"Overlay stairs are lighter, cheaper and allow any finish. A 30 mm tread with a drip edge and a 20 mm riser are laid on a concrete flight with stone adhesive. They are used for straight, winding and spiral flights.\n\nSolid blocks suit landscaping and massive entrances: retaining steps in a garden, a porch in the “stone from the quarry” style. They do not need a concrete base in the classic sense, but they need heavy machinery for installation and cost significantly more because of the volume of material."},{"heading":"What finish is needed for outdoors?","body":"For exterior stairs polishing is dangerous: in rain and frost it turns into an ice rink. We use flaming (the surface is torched, the crystals flake and give a rough texture) or bush-hammering (mechanical pitting). Both finishes are slip-resistant even when wet.\n\nA compromise for interiors where you want shine: a polished tread with flamed or sandblasted strips 30–40 mm wide near the edge. They work like anti-slip tape without spoiling the look. Outdoors the tread also needs a 1–2 % slope away from the building and a drip edge underneath, so water does not run onto the riser and freeze in the joint."},{"heading":"What does the cost depend on?","body":"Material: Ukrainian Grey Ukraine granite is more affordable than gabbro and labradorite; imports cost even more. Thickness: a 30 mm tread versus 20 mm; solid blocks separately.\n\nGeometry: straight steps of standard 300–330 mm width are cheaper than winders and curved ones; every cut-out for a handrail or non-standard angle adds work. Finish: polishing is basic; flaming and bush-hammering cost more. Plus delivery and installation, which on stairs takes longer than on a countertop, because every part is fitted on site.\n\nA guide price for your flight is available in the calculator; the exact estimate follows measurement of the concrete base."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Polishing","Interior, verticals, details","Slippery when wet, add strips"],["Honing (matte)","Interior, calm surface","Less slippery, easier to care for"],["Flaming","Outdoors, porches, terraces","Slip-resistant rough texture"],["Bush-hammering","Outdoors, public entrances","The coarsest texture, ramps"]]},"faq":[{"question":"Are granite stairs slippery?","answer":"Polished — yes, especially wet. Flamed and bush-hammered — no, they are slip-resistant even in rain and frost. For interiors you can combine shine with anti-slip strips."},{"question":"What is the maximum step length?","answer":"From a 30 mm slab we make solid treads up to 3 m; the limit is the slab size. Longer steps are assembled from two slabs with a joint in the middle or over a support."},{"question":"What to choose for a porch?","answer":"Flamed Grey Ukraine or Kometa Black 30 mm thick with a drip edge. It is the most common and most reliable solution for the Ukrainian climate."},{"question":"How much does it cost?","answer":"It depends on the stone, thickness, number and shape of steps, finish and installation. Enter the dimensions in the calculator for a guide; we give the exact figure after measurement."}]},"lt":{"title":"Laiptai iš granito: gamyba, apdirbimas, kaina","h1":"Granito laiptai — kaip renkami ir gaminami","description":"Granito laiptai: uždedami ir vientisi, apdaila laukui ir interjerui, neslidumas, pakopų matmenys ir iš ko susideda kaina.","dek":"Konstrukcija, apdaila ir saugus mazgas interjerui ir laukui.","intro":"Granito laiptai — ilgaamžiškiausia namo dalis: prieangiai iš ukrainietiško granito stovi po 50 metų be remonto. Bet būtent laiptuose klaidos kainuoja brangiausiai, nes slidi pakopa ar nenuvestas vanduo jaučiami kasdien. Pasakojame, kaip projektuojame laiptus namams, laiptinėms ir parduotuvėms.","sections":[{"heading":"Kokie būna granito laiptai?","body":"Pagal konstrukciją: uždedami (pakopos ir pakopų sienelės iš 20–30 mm plokščių ant betoninio pagrindo) ir vientisi (masyvūs 100–150 mm blokai, kurie patys yra pakopos). Uždedami naudojami 90 % atvejų: ir namuose, ir lauke.\n\nPagal vietą: interjeriniai (poliruota arba matinė apdaila, medinės ar akmeninės pakopų sienelės, grindjuostė palei sieną) ir išoriniai (deginta apdaila, nuolydis vandeniui, lašų kraštas po pakopa, šalčiui atsparūs klijai)."},{"heading":"Uždedami ar vientisi — koks skirtumas?","body":"Uždedami laiptai lengvesni, pigesni ir leidžia bet kokią apdailą. 30 mm pakopa su lašų kraštu ir 20 mm pakopos sienelė dedamos ant betoninio maršo akmens klijais. Iš jų daromi ir tiesūs, ir sukti, ir spiraliniai maršai.\n\nVientisi blokai tinka kraštovaizdžiui ir masyviems įėjimams: atraminiai laiptai sode, prieangis „akmens iš karjero“ stiliumi. Jiems nereikia betoninio pagrindo klasikine prasme, bet reikia sunkios technikos montavimui ir jie kainuoja gerokai brangiau dėl medžiagos kiekio."},{"heading":"Kokio apdirbimo reikia laukui?","body":"Išoriniams laiptams poliravimas pavojingas: lyjant ir šąlant jis virsta čiuožykla. Naudojame terminį apdirbimą (paviršius apdeginamas, kristalai skeldėja ir suteikia šiurkščią faktūrą) arba kalstymą (mechaninį taškavimą). Abi apdailos neslidžios net drėgnos.\n\nKompromisinis variantas interjerui, kur norisi blizgesio: poliruota pakopa su degintomis ar smėliasraučiu apdirbtomis 30–40 mm pločio juostomis prie krašto. Jos veikia kaip neslidi juosta ir negadina išvaizdos. Laukui taip pat svarbus pakopos 1–2 % nuolydis nuo namo ir lašų kraštas apačioje, kad vanduo netekėtų ant pakopos sienelės ir neužšaltų siūlėje."},{"heading":"Nuo ko priklauso kaina?","body":"Medžiaga: ukrainietiškas granitas Grey Ukraine prieinamesnis už gabrą ir labradoritą, importas kainuoja dar brangiau. Storis: 30 mm pakopa prieš 20 mm, masyvūs blokai atskirai.\n\nGeometrija: tiesios standartinio 300–330 mm pločio pakopos pigesnės už suktas ir lenktas, kiekviena išpjova turėklui ar nestandartinis kampas prideda darbo. Apdaila: poliravimas bazinis, terminis apdirbimas ir kalstymas brangesni. Plius pristatymas ir montavimas, kuris laiptuose užima daugiau laiko nei stalviršyje, nes kiekviena detalė pritaikoma vietoje.\n\nOrientyrą jūsų maršui galite gauti skaičiuoklėje, tikslią sąmatą — po betoninio pagrindo išmatavimo."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Poliravimas","Interjeras, vertikalės, detalės","Slidus drėgnas, pridėkite juostų"],["Šlifavimas (matinis)","Interjeras, ramus paviršius","Mažiau slidus, lengviau prižiūrėti"],["Terminis apdirbimas","Laukas, prieangiai, terasos","Neslidi šiurkšti faktūra"],["Kalstymas","Laukas, visuomeniniai įėjimai","Šiurkščiausia faktūra, nuovažos"]]},"faq":[{"question":"Ar granito laiptai slidūs?","answer":"Poliruoti — taip, ypač drėgni. Deginti ir kalstyti — ne, jie neslidūs net lyjant ir šąlant. Interjerui galima derinti blizgesį su neslidžiomis juostomis."},{"question":"Koks maksimalus pakopos ilgis?","answer":"Iš 30 mm plokštės gaminame vientisas pakopas iki 3 m, ribojimas — plokštės dydis. Ilgesnės pakopos sudedamos iš dviejų plokščių su siūle centre arba virš atramos."},{"question":"Ką rinktis prieangiui?","answer":"Degintą Grey Ukraine arba Kometa Black 30 mm storio su lašų kraštu. Tai dažniausias ir patikimiausias sprendimas Ukrainos klimatui."},{"question":"Kiek kainuoja?","answer":"Priklauso nuo uolienos, storio, pakopų skaičiaus ir formos, apdailos ir montavimo. Įveskite matmenis į skaičiuoklę orientyrui, tikslią sumą pasakysime po išmatavimo."}]},"pl":{"title":"Schody z granitu: wykonanie, obróbka, koszt","h1":"Schody granitowe — jak się je dobiera i wykonuje","description":"Schody granitowe: nakładane i monolityczne, wykończenie na zewnątrz i do wnętrz, antypoślizg, wymiary stopni i z czego składa się koszt.","dek":"Konstrukcja, wykończenie i bezpieczny detal dla wnętrz i na zewnątrz.","intro":"Schody granitowe to najtrwalsza część domu: ganki z ukraińskiego granitu stoją po 50 lat bez remontu. Ale właśnie na schodach błędy kosztują najwięcej, bo śliski stopień lub nieodprowadzona woda odczuwa się codziennie. Opowiadamy, jak projektujemy schody do domów, klatek schodowych i sklepów.","sections":[{"heading":"Jakie bywają schody granitowe?","body":"Według konstrukcji: nakładane (stopnice i podstopnice z płyt 20–30 mm na podłożu betonowym) i monolityczne (masywne bloki 100–150 mm, które same są stopniami). Nakładane stosuje się w 90 % przypadków: i w domach, i na zewnątrz.\n\nWedług miejsca: wewnętrzne (wykończenie polerowane lub matowe, drewniane lub kamienne podstopnice, cokół wzdłuż ściany) i zewnętrzne (wykończenie płomieniowane, spadek do odprowadzenia wody, kapinos pod stopnicą, klej mrozoodporny)."},{"heading":"Nakładane czy monolityczne — jaka różnica?","body":"Schody nakładane są lżejsze, tańsze i pozwalają na każde wykończenie. Stopnica 30 mm z kapinosem i podstopnica 20 mm układane są na biegu betonowym na klej do kamienia. Robi się z nich biegi proste, zabiegowe i kręte.\n\nBloki monolityczne pasują do krajobrazu i masywnych wejść: schody oporowe w ogrodzie, ganek w stylu „kamień z kamieniołomu”. Nie potrzebują podłoża betonowego w klasycznym sensie, ale wymagają ciężkiego sprzętu do montażu i kosztują znacznie więcej przez ilość materiału."},{"heading":"Jaka obróbka jest potrzebna na zewnątrz?","body":"Dla schodów zewnętrznych polerowanie jest niebezpieczne: w deszczu i mrozie zamienia się w lodowisko. Stosujemy płomieniowanie (powierzchnię opala się, kryształy pękają i dają szorstką fakturę) lub groszkowanie (mechaniczne punktowanie). Oba wykończenia są antypoślizgowe nawet na mokro.\n\nKompromis dla wnętrz, gdzie chce się połysku: polerowana stopnica z płomieniowanymi lub piaskowanymi pasami o szerokości 30–40 mm przy krawędzi. Działają jak taśma antypoślizgowa i nie psują wyglądu. Na zewnątrz ważny jest też spadek stopnicy 1–2 % od budynku i kapinos od spodu, aby woda nie spływała na podstopnicę i nie zamarzała w spoinie."},{"heading":"Od czego zależy koszt?","body":"Materiał: ukraiński granit Grey Ukraine jest tańszy od gabro i labradorytu, import kosztuje jeszcze więcej. Grubość: stopnica 30 mm wobec 20 mm, masywne bloki osobno.\n\nGeometria: proste stopnie standardowej szerokości 300–330 mm są tańsze od zabiegowych i łukowych, każde wycięcie pod poręcz lub niestandardowy kąt dodaje pracy. Wykończenie: polerowanie jest bazowe, płomieniowanie i groszkowanie droższe. Plus dostawa i montaż, który na schodach zajmuje więcej czasu niż na blacie, bo każdy detal dopasowuje się na miejscu.\n\nOrientacyjną cenę Twojego biegu można uzyskać w kalkulatorze, dokładny kosztorys po pomiarze podłoża betonowego."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Polerowanie","Wnętrza, pionowe, detale","Śliskie na mokro, dodaj pasy"],["Szlifowanie (matowe)","Wnętrza, spokojna powierzchnia","Mniej śliskie, łatwsze w pielęgnacji"],["Płomieniowanie","Zewnątrz, ganki, tarasy","Antypoślizgowa szorstka faktura"],["Groszkowanie","Zewnątrz, wejścia publiczne","Najgrubsza faktura, rampy"]]},"faq":[{"question":"Czy schody granitowe są śliskie?","answer":"Polerowane — tak, zwłaszcza mokre. Płomieniowane i groszkowane — nie, są antypoślizgowe nawet w deszczu i mrozie. Do wnętrz można połączyć połysk z pasami antypoślizgowymi."},{"question":"Jaka jest maksymalna długość stopnia?","answer":"Z płyty 30 mm robimy jednolite stopnice do 3 m, ograniczeniem jest wymiar sląba. Dłuższe stopnie składa się z dwóch płyt ze spoiną na środku lub nad podporą."},{"question":"Co wybrać na ganek?","answer":"Płomieniowany Grey Ukraine lub Kometa Black o grubości 30 mm z kapinosem. To najpowszechniejsze i najbardziej niezawodne rozwiązanie dla ukraińskiego klimatu."},{"question":"Ile to kosztuje?","answer":"Zależy od skały, grubości, liczby i kształtu stopni, wykończenia i montażu. Wprowadź wymiary do kalkulatora dla orientacji, dokładną kwotę podamy po pomiarze."}]}}'::jsonb) where slug = 'shody-z-granitu-cina-vygotovlennya';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Fassade aus Stein: welcher Stein für die Verkleidung","h1":"Fassadenverkleidung mit Stein — welchen Stein wählen","description":"Fassade aus Stein: Granit, Travertin, Quarzit oder Feinsteinzeug. Plattendicke, hinterlüftete Fassade und mechanische Befestigung, Fugen, Pflege.","dek":"Material, Unterkonstruktion, Fugen und Wasser in einer langlebigen Fassade.","intro":"Eine Steinfassade ist nicht „an die Wand geklebte Fliese“, sondern ein Ingenieursystem: Unterkonstruktion, Anker, Platten, Fugen und Wasserableitung. Das Material ist darin wichtig, aber nicht das Einzige. Wir erklären, welchen Stein wir für den ukrainischen Winter empfehlen, wie er befestigt wird und warum Granit fast immer gewinnt.","sections":[{"heading":"Welcher Stein ist der beste für die Fassade?","body":"Für ein Privathaus und ein Geschäftsgebäude in unserem Klima ist es Granit: Er ist frostbeständig (hält über 300 Frostzyklen aus), nimmt kein Wasser auf und verblasst nicht. Travertin und Sandstein sind schön, aber porös und brauchen Schutz und regelmäßige Pflege. Marmor an der Fassade verliert durch sauren Stadtregen schnell die Politur.\n\nDie Alternative zu Stein ist großformatiges Feinsteinzeug von Laminam oder Neolith: dünn, leicht, UV-stabil, in Stein- oder Betondekoren. Es funktioniert gut an hinterlüfteten Fassaden, wo das Gewicht zählt."},{"heading":"Warum ist Granit die praktische Wahl?","body":"Granit braucht an der Fassade keine Imprägnierung: Wasser läuft ab, und Schmutz wird vom Regen abgewaschen. Eine geflammte Oberfläche verbirgt kleine Chargenunterschiede und blendet nicht. Ukrainischer Granit ist in großen Chargen aus einem Block verfügbar, sodass die Farbe an der ganzen Fassade gleichmäßig ist.\n\nEin weiterer Vorteil ist die Reparierbarkeit: Eine beschädigte Platte an mechanischer Befestigung wird in einer Stunde getauscht, ohne die Nachbarplatten abzunehmen. Für den Sockel ist Granit überhaupt ohne Alternative: Salz, Spritzwasser, die Schaufel des Hausmeisters und Stöße hinterlassen keine Spur."},{"heading":"Wie werden Fassadenplatten befestigt?","body":"Die Nassmethode (Kleber an der Wand) ist zulässig für Sockel und kleine Flächen bis 3 m Höhe mit 20-mm-Platten. Darüber wird die Fassade hinterlüftet ausgeführt: An der Wand werden Konsolen und Profile befestigt, darin Klammern oder Stifte, die 30-mm-Platten in Schlitzen an den Kanten halten.\n\nZwischen den Platten bleibt eine Fuge von 4–6 mm für Temperaturbewegungen, hinter den Platten ein Lüftungsspalt von 30–50 mm und Dämmung. So wird die Wand nicht nass, Kondensat wird abgeführt, und der Stein reißt nicht durch Frost. Die Berechnung der Unterkonstruktion macht der Statiker, wir fertigen die Platten mit Schlitzen für die konkrete Befestigung."},{"heading":"Braucht eine Steinfassade Pflege?","body":"Granit: Reinigung mit dem Hochdruckreiniger alle paar Jahre, Kontrolle der Fugen und Befestigungen. Imprägnierung nicht nötig. Travertin und Kalkstein: Hydrophobierung alle 3–5 Jahre, sonst sammeln die Poren Schmutz und Moos auf der Nordseite.\n\nEinen Sockel aus jedem Stein sollte man nach dem Winter einmal im Jahr von Salz abwaschen. Feinsteinzeug braucht nichts außer Waschen. Ist die Fassade richtig ausgeführt, beschränkt sich die Pflege auf Abspülen, und die Konstruktion selbst hält länger als das Gebäude."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Granit","Frostbeständig, nimmt kein Wasser auf","Mechanische Befestigung ab 3 m"],["Travertin","Warme poröse Textur","Hydrophobierung, Schutz vor Schmutz"],["Quarzit","Ausdrucksstarke Zeichnung","Charge prüfen, höherer Preis"],["Feinsteinzeug","Leicht, UV-stabil","Hinterlüftete Fassade, dünne Platten 6–12 mm"]]},"faq":[{"question":"Welcher Stein für ein rauhes Klima?","answer":"Granit mit geflammter Oberfläche an einer hinterlüfteten Fassade. Er fürchtet weder Frost, Wasser noch Salz und braucht keine Imprägnierung."},{"question":"Welche Plattendicke?","answer":"20 mm für die Klebebefestigung am Sockel, 30 mm für die hinterlüftete Fassade mit Klammern. Feinsteinzeug 6–12 mm auf eigener Unterkonstruktion."},{"question":"Verblasst Granit?","answer":"Nein. Die Mineralien des Granits sind UV-stabil, die Farbe ist nach 30 Jahren dieselbe. Ändern kann sich nur die Politur, deshalb nimmt man für die Fassade eine matte oder geflammte Oberfläche."},{"question":"Wie pflegen?","answer":"Reinigung mit dem Hochdruckreiniger alle paar Jahre und Kontrolle der Fugen. Bei porösen Steinen zusätzlich Hydrophobierung alle 3–5 Jahre."}]},"en":{"title":"Stone facade: which stone to choose for cladding","h1":"Cladding a facade in stone — which stone to choose","description":"Stone facade: granite, travertine, quartzite or porcelain. Slab thickness, ventilated facade and mechanical fixing, joints, care.","dek":"Material, subsystem, joints and water in a durable facade.","intro":"A stone facade is not “tiles glued to a wall” but an engineered system: subframe, anchors, slabs, joints and drainage. The material matters, but it is not the only thing. We explain which stone we recommend for the Ukrainian winter, how it is fixed and why granite almost always wins.","sections":[{"heading":"Which stone is best for a facade?","body":"For a private house and a commercial building in our climate it is granite: it is frost-resistant (withstands over 300 freeze cycles), does not absorb water and does not fade. Travertine and sandstone are beautiful but porous and need protection and regular care. Marble on a facade quickly loses its polish from acidic city rain.\n\nThe alternative to stone is large-format Laminam or Neolith porcelain: thin, light, UV-stable, in stone or concrete decors. It works well on ventilated facades where weight matters."},{"heading":"Why is granite the practical choice?","body":"Granite needs no sealing on a facade: water runs off it and dirt is washed away by rain. A flamed surface hides small batch differences and gives no glare. Ukrainian granite is available in large batches from one block, so the colour across the whole facade is uniform.\n\nAnother advantage is repairability: a damaged slab on mechanical fixing is replaced in an hour without dismantling its neighbours. For a plinth granite has no alternative at all: salt, splashes, the caretaker''s shovel and knocks leave no trace on it."},{"heading":"How are facade slabs fixed?","body":"The wet method (adhesive to the wall) is acceptable for plinths and small areas up to 3 m high with 20 mm slabs. Above that the facade is made ventilated: brackets and rails are fixed to the wall, and in them clamps or pins hold 30 mm slabs in kerfs on the edges.\n\nA 4–6 mm joint is left between slabs for thermal movement, and behind the slabs a 30–50 mm ventilation gap and insulation. This way the wall does not get wet, condensation is carried away and the stone does not crack from frost. The subsystem is calculated by a structural engineer; we make the slabs with kerfs for the specific fixing."},{"heading":"Does a stone facade need care?","body":"Granite: pressure washing every few years, checking the joints and fixings. No sealing is needed. Travertine and limestone: a water repellent every 3–5 years, otherwise the pores collect dirt and moss on the north side.\n\nA plinth of any stone should be washed of salt once a year after winter. Porcelain needs nothing but washing. If the facade is done correctly, care comes down to rinsing, and the structure itself outlives the building."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Granite","Frost-resistant, does not absorb water","Mechanical fixing from 3 m"],["Travertine","Warm porous texture","Water repellent, protection from dirt"],["Quartzite","Expressive pattern","Check the batch, higher price"],["Porcelain","Light, UV-stable","Ventilated facade, thin 6–12 mm slabs"]]},"faq":[{"question":"Which stone for a harsh climate?","answer":"Granite with a flamed finish on a ventilated facade. It is not afraid of frost, water or salt and needs no sealing."},{"question":"What slab thickness?","answer":"20 mm for adhesive fixing on a plinth, 30 mm for a ventilated facade on clamps. Porcelain 6–12 mm on its own subsystem."},{"question":"Does granite fade?","answer":"No. Granite''s minerals are stable to ultraviolet; the colour after 30 years is the same. Only the polish can change, which is why a honed or flamed finish is used on facades."},{"question":"How to care for it?","answer":"Pressure washing every few years and an inspection of the joints. For porous stones additionally a water repellent every 3–5 years."}]},"lt":{"title":"Fasadas iš akmens: kokį akmenį rinktis apdailai","h1":"Fasado apdaila akmeniu — kokį akmenį rinktis","description":"Fasadas iš akmens: granitas, travertinas, kvarcitas ar keraminis granitas. Plokščių storis, vėdinamas fasadas ir mechaninis tvirtinimas, siūlės, priežiūra.","dek":"Medžiaga, posistemė, siūlės ir vanduo ilgaamžiame fasade.","intro":"Akmens fasadas — tai ne „plytelės, priklijuotos prie sienos“, o inžinerinė sistema: pokonstrukcija, inkarai, plokštės, siūlės ir vandens nuvedimas. Medžiaga jame svarbi, bet ne vienintelė. Paaiškiname, kokį akmenį rekomenduojame Ukrainos žiemai, kaip jis tvirtinamas ir kodėl granitas beveik visada laimi.","sections":[{"heading":"Koks akmuo geriausias fasadui?","body":"Privačiam namui ir komerciniam pastatui mūsų klimate tai granitas: jis atsparus šalčiui (atlaiko daugiau nei 300 užšalimo ciklų), neįgeria vandens ir neblunka. Travertinas ir smiltainis gražūs, bet porėti ir reikalauja apsaugos bei reguliarios priežiūros. Marmuras fasade greitai praranda poliravimą nuo rūgštaus miesto lietaus.\n\nAlternatyva akmeniui — didelio formato keraminis granitas Laminam arba Neolith: plonas, lengvas, UV stabilus, akmens ar betono dekoruose. Jis gerai dirba vėdinamuose fasaduose, kur svarbus svoris."},{"heading":"Kodėl granitas — praktiškas pasirinkimas?","body":"Granitui fasade nereikia impregnavimo: vanduo nuo jo nuteka, o nešvarumus nuplauna lietus. Degintas paviršius paslepia smulkius partijų skirtumus ir neblizga. Ukrainietiškas granitas prieinamas didelėmis partijomis iš vieno bloko, tad spalva visame fasade vienoda.\n\nDar vienas privalumas — remontuojamumas: pažeistą plokštę su mechaniniu tvirtinimu pakeičia per valandą nedemontuojant kaimyninių. Cokoliui granitas išvis be alternatyvų: druska, purslai, kiemsargio kastuvas ir smūgiai nepalieka ant jo pėdsakų."},{"heading":"Kaip tvirtinamos fasado plokštės?","body":"Šlapias būdas (klijais prie sienos) leistinas cokoliams ir nedideliems plotams iki 3 m aukščio su 20 mm plokštėmis. Aukščiau fasadas daromas vėdinamas: prie sienos tvirtinamos konsolės ir kreipiančiosios, jose — klemeriai arba kaiščiai, laikantys 30 mm plokštes įpjovose kraštuose.\n\nTarp plokščių paliekama 4–6 mm siūlė temperatūriniams judesiams, už plokščių — 30–50 mm vėdinimo tarpas ir šiltinimas. Taip siena nesudrėksta, kondensatas išvedamas, o akmuo neskyla nuo šalčio. Posistemę apskaičiuoja konstruktorius, mes gaminame plokštes su įpjovomis konkrečiam tvirtinimui."},{"heading":"Ar akmens fasadui reikia priežiūros?","body":"Granitas: plovimas vandeniu su slėgiu kartą per kelis metus, siūlių ir tvirtinimų patikra. Impregnavimo nereikia. Travertinas ir klintis: hidrofobizatorius kartą per 3–5 metus, kitaip poros kaupia nešvarumus ir samanas šiaurinėje pusėje.\n\nCokolį iš bet kokio akmens verta kartą per metus nuplauti nuo druskos po žiemos. Keraminiam granitui nereikia nieko, išskyrus plovimą. Jei fasadas padarytas teisingai, priežiūra susiveda į nuskalavimą, o pati konstrukcija tarnauja ilgiau nei pastatas."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Granitas","Atsparus šalčiui, neįgeria vandens","Mechaninis tvirtinimas nuo 3 m"],["Travertinas","Šilta porėta faktūra","Hidrofobizatorius, apsauga nuo nešvarumų"],["Kvarcitas","Išraiškingas raštas","Tikrinti partiją, kaina aukštesnė"],["Keraminis granitas","Lengvas, UV stabilus","Vėdinamas fasadas, plonos plokštės 6–12 mm"]]},"faq":[{"question":"Koks akmuo atšiauriam klimatui?","answer":"Granitas su deginta apdaila vėdinamame fasade. Jis nebijo šalčio, vandens ir druskos ir nereikalauja impregnavimo."},{"question":"Koks plokščių storis?","answer":"20 mm klijavimui ant cokolio, 30 mm vėdinamam fasadui ant klemerių. Keraminis granitas 6–12 mm ant savos posistemės."},{"question":"Ar granitas blunka?","answer":"Ne. Granito mineralai stabilūs ultravioletui, spalva po 30 metų ta pati. Pasikeisti gali tik poliravimas, todėl fasadui imama matinė arba deginta apdaila."},{"question":"Kaip prižiūrėti?","answer":"Plovimas vandeniu su slėgiu kartą per kelis metus ir siūlių apžiūra. Porėtiems akmenims papildomai hidrofobizatorius kartą per 3–5 metus."}]},"pl":{"title":"Elewacja z kamienia: który kamień wybrać na okładzinę","h1":"Okładzina elewacji kamieniem — który kamień wybrać","description":"Elewacja z kamienia: granit, trawertyn, kwarcyt czy gres. Grubość płyt, elewacja wentylowana i mocowanie mechaniczne, spoiny, pielęgnacja.","dek":"Materiał, podkonstrukcja, spoiny i woda w trwałej elewacji.","intro":"Kamienna elewacja to nie „płytki przyklejone do ściany”, lecz system inżynieryjny: podkonstrukcja, kotwy, płyty, spoiny i odprowadzenie wody. Materiał jest w niej ważny, ale nie jedyny. Wyjaśniamy, który kamień polecamy na ukraińską zimę, jak się mocuje i dlaczego granit prawie zawsze wygrywa.","sections":[{"heading":"Który kamień jest najlepszy na elewację?","body":"Dla domu prywatnego i budynku komercyjnego w naszym klimacie to granit: jest mrozoodporny (wytrzymuje ponad 300 cykli zamrażania), nie chłonie wody i nie blaknie. Trawertyn i piaskowiec są piękne, ale porowate i wymagają ochrony i regularnej pielęgnacji. Marmur na elewacji szybko traci połysk od miejskich kwaśnych deszczy.\n\nAlternatywą dla kamienia jest wielkoformatowy gres Laminam lub Neolith: cienki, lekki, stabilny na UV, w dekorach pod kamień lub beton. Dobrze pracuje na elewacjach wentylowanych, gdzie liczy się waga."},{"heading":"Dlaczego granit to praktyczny wybór?","body":"Granit nie wymaga impregnacji na elewacji: woda z niego spływa, a brud zmywa deszcz. Powierzchnia płomieniowana ukrywa drobne różnice partii i nie daje odblasków. Ukraiński granit jest dostępny w dużych partiach z jednego bloku, więc kolor na całej elewacji jest jednolity.\n\nKolejna zaleta to naprawialność: uszkodzoną płytę na mocowaniu mechanicznym wymienia się w godzinę bez demontażu sąsiednich. Na cokół granit jest w ogóle bez alternatywy: sól, bryzgi, łopata dozorcy i uderzenia nie zostawiają na nim śladu."},{"heading":"Jak mocuje się płyty elewacyjne?","body":"Sposób mokry (na klej do ściany) dopuszczalny jest dla cokołów i niewielkich fragmentów o wysokości do 3 m z płytami 20 mm. Wyżej elewację robi się wentylowaną: do ściany mocuje się wsporniki i prowadnice, w nich — klamry lub trzpienie, które trzymają płyty 30 mm w nacięciach na krawędziach.\n\nMiędzy płytami zostawia się spoinę 4–6 mm na ruchy termiczne, za płytami — szczelinę wentylacyjną 30–50 mm i izolację. Tak ściana nie zawilgaca się, kondensat jest odprowadzany, a kamień nie pęka od mrozu. Obliczenia podkonstrukcji wykonuje konstruktor, my wykonujemy płyty z nacięciami pod konkretne mocowanie."},{"heading":"Czy kamienna elewacja wymaga pielęgnacji?","body":"Granit: mycie wodą pod ciśnieniem raz na kilka lat, kontrola spoin i mocowań. Impregnacja nie jest potrzebna. Trawertyn i wapień: hydrofobizacja raz na 3–5 lat, inaczej pory zbierają brud i mech od północnej strony.\n\nCokół z każdego kamienia warto raz w roku umyć z soli po zimie. Gres nie wymaga niczego poza myciem. Jeśli elewacja jest wykonana prawidłowo, pielęgnacja sprowadza się do spłukiwania, a sama konstrukcja służy dłużej niż budynek."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Granit","Mrozoodporny, nie chłonie wody","Mocowanie mechaniczne od 3 m"],["Trawertyn","Ciepła porowata faktura","Hydrofobizacja, ochrona przed brudem"],["Kwarcyt","Wyrazisty rysunek","Sprawdzać partię, wyższa cena"],["Gres","Lekki, stabilny na UV","Elewacja wentylowana, cienkie płyty 6–12 mm"]]},"faq":[{"question":"Który kamień do surowego klimatu?","answer":"Granit z wykończeniem płomieniowanym na elewacji wentylowanej. Nie boi się mrozu, wody i soli i nie wymaga impregnacji."},{"question":"Jaka grubość płyt?","answer":"20 mm do mocowania na klej na cokole, 30 mm do elewacji wentylowanej na klamrach. Gres 6–12 mm na własnej podkonstrukcji."},{"question":"Czy granit blaknie?","answer":"Nie. Minerały granitu są stabilne wobec ultrafioletu, kolor po 30 latach jest ten sam. Zmienić się może tylko połysk, dlatego na elewację bierze się wykończenie matowe lub płomieniowane."},{"question":"Jak pielęgnować?","answer":"Mycie wodą pod ciśnieniem raz na kilka lat i przegląd spoin. Dla kamieni porowatych dodatkowo hydrofobizacja raz na 3–5 lat."}]}}'::jsonb) where slug = 'fasad-z-kamenyu-yakyy-kamin';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Granit- oder Betonpflaster: Was ist besser","h1":"Granit- oder Betonpflaster — was wählen","description":"Granit- oder vibrationsgepresstes Betonpflaster: Festigkeit, Haltbarkeit, Optik, Reparatur und Lebenszykluskosten. Was für Hof, Wege und Einfahrt wählen.","dek":"Das Belagsmaterial für Hof, Wege und die Autoeinfahrt.","intro":"Vibrationsgepresstes Betonpflaster ist am Anfang günstiger, Granitpflaster nach 20 Jahren. Das ist die Hauptthese, und der Rest des Artikels erklärt, warum das so ist und in welchen Fällen Beton trotzdem gerechtfertigt ist. Wir fertigen Granitpflaster aus ukrainischem Stein und sehen beide Materialien täglich auf den Baustellen.","sections":[{"heading":"Was für den Hof wählen?","body":"Für Einfahrt, Zufahrt und Stellplatz wählen Sie Granit: gespaltenes oder gesägt-gespaltenes Pflaster 100 × 100 × 50–100 mm hält das Gewicht eines Autos und einen Winter mit Salz unverändert aus. Für Gartenwege, auf denen nur Menschen gehen, eignen sich beide Materialien, hier entscheiden Budget und Optik.\n\nIst der Hof groß, ist ein verbreiteter Kompromiss: Granit an Einfahrt, Eingang und entlang der Fassade, Beton im Wirtschaftsbereich. So erhalten die sichtbarsten Flächen ein Material für die ganze Lebensdauer des Hauses."},{"heading":"Warum ist Granitpflaster fester?","body":"Granit ist ein monolithischer Naturstein mit einer Druckfestigkeit von 180–220 MPa. Betonpflaster hat eine Festigkeit von 40–60 MPa und besteht aus Zementstein mit Zuschlag. Unter Rädern und im Frost bröselt Beton mit der Zeit an den Kanten und verliert die pigmentierte Deckschicht, Granit verändert sich nicht.\n\nDie Wasseraufnahme von Granit liegt unter 0,2 %, deshalb dringt Wasser nicht in den Stein ein und sprengt ihn beim Gefrieren nicht. Bei Beton beträgt sie 4–6 %. Nach 10–15 Wintern ist der Unterschied mit bloßem Auge sichtbar: Granitpflaster sieht aus wie frisch verlegt, Betonpflaster muss ersetzt werden."},{"heading":"Wann ist Betonpflaster gerechtfertigt?","body":"Wenn das Budget begrenzt und das Grundstück groß ist und kein Schwerverkehr fährt. Wenn eine exakte, wiederholbare Geometrie und Farbe für ein geometrisches Muster gebraucht werden. Wenn der Belag vorübergehend ist oder der Hof in einigen Jahren umgestaltet werden soll.\n\nGuter Beton eines großen Herstellers mit 60–80 mm Dicke und richtigem Unterbau hält 10–15 Jahre und sieht ordentlich aus. Die Probleme beginnen bei billigem Pflaster zweifelhafter Werke: Es verliert in zwei Saisons die Farbe und blättert ab."},{"heading":"Was ist mit den Kosten pro Quadratmeter?","body":"Material: Granitpflaster ist mehrfach teurer als Beton. Verlegung: etwa gleich für beide, denn Unterbau und Arbeit sind dieselben. Lebenszyklus: Granit wird einmal verlegt, Beton alle 10–15 Jahre neu, samt Arbeit und Abtransport des alten.\n\nEs gibt auch eine indirekte Ersparnis: Granitpflaster wird nach dem Aufnehmen (etwa bei Leitungsreparaturen) wieder verlegt, Betonpflaster meist entsorgt. Einen Richtwert für Ihre Fläche liefert der Pflasterrechner."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Festigkeit","Granit 180–220 MPa","Beton 40–60 MPa"],["Wasseraufnahme","Granit bis 0,2 %","Beton 4–6 %, blättert im Frost"],["Optik nach 15 Jahren","Granit unverändert","Beton verblasst, bröselt"],["Reparatur","Granit wird neu verlegt","Beton wird durch neuen ersetzt"],["Startpreis","Granit teurer","Beton günstiger"]]},"faq":[{"question":"Was ist langlebiger?","answer":"Granit: Die Lebensdauer misst sich in Jahrzehnten ohne Veränderung der Optik. Betonpflaster ist in unserem Klima auf 10–15 Jahre ausgelegt."},{"question":"Was ist günstiger?","answer":"Am Anfang — Beton. Über den Lebenszyklus mit Neuverlegung — Granit, weil er einmal verlegt wird."},{"question":"Was für die Autoeinfahrt?","answer":"Granitpflaster 80–100 mm auf Schotterunterbau. Beton hält Pkw aus, aber die Kanten bröseln schnell durch Manöver."},{"question":"Was für Fußwege?","answer":"Beide Materialien. Granit 50–60 mm oder Beton 60 mm auf Sand-Schotter-Unterbau; die Wahl nach Optik und Budget."}]},"en":{"title":"Granite or vibro-pressed paving: which is better","h1":"Granite or vibro-pressed paving — what to choose","description":"Granite or vibro-pressed paving: strength, durability, look, repair and life-cycle cost. What to choose for a yard, paths and a driveway.","dek":"Paving material for a yard, paths and a car driveway.","intro":"Vibro-pressed concrete paving is cheaper at the start; granite paving is cheaper after 20 years. That is the main thesis, and the rest of the article explains why and in which cases concrete is still justified. We make granite paving from Ukrainian stone and see both materials on sites every day.","sections":[{"heading":"What to choose for a yard?","body":"For a driveway, access road and parking space choose granite: split or sawn-split setts 100 × 100 × 50–100 mm withstand the weight of a car and a salty winter without change. For garden paths where only people walk, both materials suit, and here budget and look decide.\n\nIf the yard is large, a common compromise is granite on the driveway, entrance and along the facade, concrete in the utility zone. That way the most visible areas get a material for the whole life of the house."},{"heading":"Why is granite paving stronger?","body":"Granite is a monolithic natural stone with a compressive strength of 180–220 MPa. Concrete paving has a strength of 40–60 MPa and consists of cement stone with aggregate. Under wheels and in frost concrete crumbles at the edges over time and loses its pigmented top layer; granite does not change.\n\nGranite''s water absorption is below 0.2 %, so water does not penetrate the stone and does not break it when freezing. In concrete it is 4–6 %. After 10–15 winters the difference is visible to the naked eye: granite paving looks freshly laid, concrete needs replacing."},{"heading":"When is vibro-pressed paving justified?","body":"When the budget is limited and the plot is large without heavy traffic. When exact repeatable geometry and colour are needed for a geometric pattern. When the surface is temporary or the yard is to be re-planned in a few years.\n\nQuality concrete from a large manufacturer, 60–80 mm thick and on a correct base, lasts 10–15 years and looks neat. The problems start with cheap paving from dubious plants: it loses colour in two seasons and flakes."},{"heading":"What about the cost per square metre?","body":"Material: granite paving is several times more expensive than concrete. Laying: roughly the same for both, because the base and the work are the same. Life cycle: granite is laid once, concrete is relaid every 10–15 years together with the work and removal of the old.\n\nThere is also an indirect saving: granite paving lifted for, say, utility repairs is laid back, while concrete is usually thrown away. A guide for your area can be calculated in the paving calculator."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Strength","Granite 180–220 MPa","Concrete 40–60 MPa"],["Water absorption","Granite up to 0.2 %","Concrete 4–6 %, flakes in frost"],["Look after 15 years","Granite unchanged","Concrete fades and crumbles"],["Repair","Granite is relaid again","Concrete is replaced with new"],["Starting price","Granite more expensive","Concrete cheaper"]]},"faq":[{"question":"Which lasts longer?","answer":"Granite: its service life is measured in decades without a change in appearance. Concrete paving is designed for 10–15 years in our climate."},{"question":"Which is cheaper?","answer":"At the start — concrete. Over the life cycle with relaying — granite, because it is laid once."},{"question":"What for a car driveway?","answer":"Granite paving 80–100 mm on a crushed-stone base. Concrete takes passenger cars, but the edges quickly crumble from manoeuvring."},{"question":"What for footpaths?","answer":"Both materials. Granite 50–60 mm or concrete 60 mm on a sand-and-gravel base; the choice is by look and budget."}]},"lt":{"title":"Granito ar vibropresuotas grindinys: kas geriau","h1":"Granito ar vibropresuotas grindinys — ką rinktis","description":"Granito ar vibropresuotas grindinys: tvirtumas, ilgaamžiškumas, išvaizda, remontas ir kaina per gyvavimo ciklą. Ką rinktis kiemui, takams ir įvažiavimui.","dek":"Dangos medžiaga kiemui, takams ir automobilio įvažiavimui.","intro":"Betoninis vibropresuotas grindinys pigesnis pradžioje, granito — pigesnis po 20 metų. Tai pagrindinė tezė, o likusi straipsnio dalis paaiškina, kodėl taip yra ir kokiais atvejais betonas vis tiek pateisinamas. Gaminame granito grindinį iš ukrainietiško akmens ir abi medžiagas objektuose matome kasdien.","sections":[{"heading":"Ką rinktis kiemui?","body":"Įvažiavimui, privažiavimo takui ir stovėjimo vietai rinkitės granitą: skaldytas arba pjautas-skaldytas 100 × 100 × 50–100 mm grindinys atlaiko automobilio svorį ir žiemą su druska be pokyčių. Sodo takams, kur vaikšto tik žmonės, tinka abi medžiagos, ir čia sprendžia biudžetas ir išvaizda.\n\nJei kiemas didelis, paplitęs kompromisas: granitas įvažiavime, įėjime ir palei fasadą, betonas ūkinėje zonoje. Taip labiausiai matomos vietos gauna medžiagą visam namo gyvavimo laikui."},{"heading":"Kuo granito grindinys tvirtesnis?","body":"Granitas — monolitinis natūralus akmuo, kurio gniuždymo stipris 180–220 MPa. Betoninis grindinys turi 40–60 MPa stiprį ir sudarytas iš cemento akmens su užpildu. Po ratais ir šaltyje betonas laikui bėgant trupa kraštuose ir praranda viršutinį sluoksnį su pigmentu, granitas nesikeičia.\n\nGranito vandens įgertis mažesnė nei 0,2 %, todėl vanduo neprasiskverbia į akmenį ir neplėšo jo užšaldamas. Betono — 4–6 %. Po 10–15 žiemų skirtumas matomas plika akimi: granito grindinys atrodo kaip tik paklotas, betoninį reikia keisti."},{"heading":"Kada vibropresuotas grindinys pateisinamas?","body":"Kai biudžetas ribotas, o sklypas didelis ir be sunkiojo transporto. Kai reikia tikslios kartojamos geometrijos ir spalvos geometriniam raštui. Kai danga laikina arba po kelių metų planuojamas kiemo perplanavimas.\n\nKokybiškas didelio gamintojo betonas 60–80 mm storio su teisingu pagrindu tarnauja 10–15 metų ir atrodo tvarkingai. Problemos prasideda nuo pigaus abejotinų gamyklų grindinio: jis praranda spalvą per du sezonus ir lupasi."},{"heading":"Kas dėl kainos už kvadratinį metrą?","body":"Medžiaga: granito grindinys kelis kartus brangesnis už betoninį. Klojimas: maždaug vienodas abiem, nes pagrindas ir darbas tie patys. Gyvavimo ciklas: granitas klojamas vieną kartą, betonas perklojamas kartą per 10–15 metų kartu su darbu ir seno išvežimu.\n\nYra ir netiesioginė ekonomija: granito grindinį po demontavimo (pavyzdžiui, remontuojant komunikacijas) kloja atgal, betoninį paprastai išmeta. Orientyrą jūsų plotui galima paskaičiuoti grindinio skaičiuoklėje."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Tvirtumas","Granitas 180–220 MPa","Betonas 40–60 MPa"],["Vandens įgertis","Granitas iki 0,2 %","Betonas 4–6 %, lupasi šaltyje"],["Išvaizda po 15 metų","Granitas be pokyčių","Betonas blunka, trupa"],["Remontas","Granitas perklojamas pakartotinai","Betonas keičiamas nauju"],["Pradinė kaina","Granitas brangesnis","Betonas pigesnis"]]},"faq":[{"question":"Kas ilgaamžiškesnis?","answer":"Granitas: tarnavimo laikas matuojamas dešimtmečiais be išvaizdos pokyčių. Betoninis grindinys mūsų klimate skirtas 10–15 metų."},{"question":"Kas pigiau?","answer":"Pradžioje — betonas. Per gyvavimo ciklą su perklojimu — granitas, nes jį kloja vieną kartą."},{"question":"Kas automobilio įvažiavimui?","answer":"Granito grindinys 80–100 mm ant skaldos pagrindo. Betonas atlaiko lengvuosius automobilius, bet kraštai greitai trupa nuo manevrų."},{"question":"Kas pėsčiųjų takams?","answer":"Abi medžiagos. Granitas 50–60 mm arba betonas 60 mm ant smėlio ir skaldos pagrindo; pasirinkimas pagal išvaizdą ir biudžetą."}]},"pl":{"title":"Kostka granitowa czy wibroprasowana: co lepsze","h1":"Kostka granitowa czy wibroprasowana — co wybrać","description":"Kostka granitowa czy wibroprasowana: wytrzymałość, trwałość, wygląd, naprawa i koszt w cyklu życia. Co wybrać na podwórze, ścieżki i podjazd.","dek":"Materiał nawierzchni na podwórze, ścieżki i podjazd samochodowy.","intro":"Betonowa kostka wibroprasowana jest tańsza na starcie, granitowa tańsza po 20 latach. To główna teza, a reszta artykułu wyjaśnia, dlaczego tak jest i w jakich przypadkach beton jest jednak uzasadniony. Produkujemy kostkę granitową z ukraińskiego kamienia i oba materiały widzimy na obiektach codziennie.","sections":[{"heading":"Co wybrać na podwórze?","body":"Na podjazd, drogę dojazdową i miejsce parkingowe wybieraj granit: kostka łupana lub cięto-łupana 100 × 100 × 50–100 mm wytrzymuje ciężar auta i zimę z solą bez zmian. Na ścieżki ogrodowe, gdzie chodzą tylko ludzie, nadają się oba materiały i tu decyduje budżet i wygląd.\n\nJeśli podwórze jest duże, częstym kompromisem jest: granit na podjeździe, wejściu i wzdłuż elewacji, beton w strefie gospodarczej. Tak najbardziej widoczne fragmenty dostają materiał na cały okres życia domu."},{"heading":"Czym kostka granitowa jest mocniejsza?","body":"Granit to monolityczny kamień naturalny o wytrzymałości na ściskanie 180–220 MPa. Kostka betonowa ma wytrzymałość 40–60 MPa i składa się ze spoiwa cementowego z wypełniaczem. Pod kołami i w mrozie beton z czasem kruszy się na krawędziach i traci wierzchnią warstwę z pigmentem, granit się nie zmienia.\n\nNasiąkliwość granitu jest poniżej 0,2 %, dlatego woda nie wnika w kamień i nie rozrywa go przy zamarzaniu. W betonie wynosi 4–6 %. Po 10–15 zimach różnica jest widoczna gołym okiem: kostka granitowa wygląda jak dopiero ułożona, betonowa wymaga wymiany."},{"heading":"Kiedy kostka wibroprasowana jest uzasadniona?","body":"Gdy budżet jest ograniczony, a działka duża i bez ciężkiego transportu. Gdy potrzebna jest dokładna, powtarzalna geometria i kolor do geometrycznego wzoru. Gdy nawierzchnia jest tymczasowa lub za kilka lat planowana jest przebudowa podwórza.\n\nDobry beton od dużego producenta o grubości 60–80 mm i na właściwym podłożu służy 10–15 lat i wygląda schludnie. Problemy zaczynają się od taniej kostki z wątpliwych zakładów: traci kolor w dwa sezony i się łuszczy."},{"heading":"Co z kosztem za metr kwadratowy?","body":"Materiał: kostka granitowa jest kilkakrotnie droższa od betonowej. Układanie: mniej więcej takie samo dla obu, bo podłoże i praca są te same. Cykl życia: granit układa się raz, beton przekłada się raz na 10–15 lat razem z pracą i wywozem starego.\n\nJest też oszczędność pośrednia: kostkę granitową po demontażu (np. przy remoncie instalacji) układa się z powrotem, betonową zwykle się wyrzuca. Orientację dla Twojej powierzchni można policzyć w kalkulatorze kostki."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Wytrzymałość","Granit 180–220 MPa","Beton 40–60 MPa"],["Nasiąkliwość","Granit do 0,2 %","Beton 4–6 %, łuszczy się w mrozie"],["Wygląd po 15 latach","Granit bez zmian","Beton blaknie, kruszy się"],["Naprawa","Granit przekłada się ponownie","Beton wymienia się na nowy"],["Cena startowa","Granit droższy","Beton tańszy"]]},"faq":[{"question":"Co jest trwalsze?","answer":"Granit: okres służby liczy się w dekadach bez zmiany wyglądu. Kostka betonowa jest obliczona na 10–15 lat w naszym klimacie."},{"question":"Co jest tańsze?","answer":"Na starcie — beton. W cyklu życia z przekładaniem — granit, bo układa się go raz."},{"question":"Co na podjazd auta?","answer":"Kostka granitowa 80–100 mm na podłożu z tłucznia. Beton wytrzymuje auta osobowe, ale krawędzie szybko kruszą się od manewrów."},{"question":"Co na ścieżki piesze?","answer":"Oba materiały. Granit 50–60 mm lub beton 60 mm na podłożu piaskowo-tłuczniowym; wybór według wyglądu i budżetu."}]}}'::jsonb) where slug = 'granitna-chy-vibropresovana-brukivka';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Verlegen von Granitpflaster: Technik und Unterbau","h1":"Wie Granitpflaster verlegt wird — Schritte und Unterbau","description":"Verlegen von Granitpflaster: Unterbauschichten für Weg und Einfahrt, Gefälle, Randsteine, Verlegemuster, Fugenfüllung und Pflege nach dem Verlegen.","dek":"Unterbau, Gefälle, Fugen und Arbeitsablauf für einen stabilen Belag.","intro":"Granitpflaster hält ewig, der Unterbau darunter aber nicht, wenn er falsch gemacht ist. Eingesunkene Spurrinnen in der Einfahrt und „Wellen“ im Weg sind immer ein Fehler in Schichten, Verdichtung oder Wasser, nie im Stein. Wir beschreiben die Technik, nach der wir arbeiten, und erklären, wie sich der Unterbau für Fußgänger von dem für Autos unterscheidet.","sections":[{"heading":"Wie verlegt man Pflaster richtig?","body":"Die Reihenfolge ist für alle Flächen gleich: Markierung und Planung der Gefälle, Aushub bis zur Tiefe aller Schichten, Geotextil, Schotter mit lagenweiser Verdichtung, Randsteine auf Beton, Ausgleichsschicht, Verlegen des Steins, Abrütteln, Verfugen.\n\nDas Gefälle des Belags vom Haus weg beträgt mindestens 1,5–2 %, also 2 cm pro Meter. Das Wasser muss zum Rasen, zur Entwässerungsrinne oder zum Einlauf laufen, nicht zur Wand. Diese Regel ist wichtiger als die Dicke des Steins."},{"heading":"Welchen Unterbau vorbereiten?","body":"Fußweg: Aushub 25–30 cm, Geotextil, Schotter 20–40 mm in 15 cm Schicht mit der Rüttelplatte verdichtet, Ausgleichsschicht aus Granitsplitt oder Sand-Zement-Gemisch 3–5 cm, Pflaster 50–60 mm.\n\nEinfahrt und Stellplatz: Aushub 40–45 cm, Geotextil, Schotter 40–70 mm in 15 cm Schicht, Schotter 20–40 mm in 10 cm Schicht, jede Schicht einzeln verdichtet, Ausgleichsschicht 3–4 cm, Pflaster 80–100 mm. Auf schwachen Böden kommt eine 10-cm-Sandschicht unter den Schotter oder eine bewehrte Betonplatte.\n\nRandsteine werden vor dem Verlegen des Steins auf ein Betonbett gesetzt: Sie halten den Belag vor dem Auseinanderdriften. Ohne Randsteine oder mit Randsteinen „auf Sand“ sinken die Ränder in der ersten Saison ab."},{"heading":"Welche Verlegearten und Muster gibt es?","body":"In Reihen: die einfachste und schnellste, geeignet für Wege. Um einen halben Stein versetzt: fester, weil die Fugen nicht durchlaufen, Standard für Einfahrten. In Bögen und Fächern: die Klassik europäischer Plätze aus gespaltenem 100 × 100-mm-Pflaster, braucht Erfahrung und mehr Stein, trägt Lasten aber hervorragend.\n\nFür kontrastreiche Muster kombiniert man den grauen Grey Ukraine mit dem roten Maple Red oder schwarzem Gabbro: Einfassung, Streifen, Schachbrettmodul. Gesägt-gespaltenes Pflaster mit ebener Oberseite ist bequemer für Absätze und Fahrrad, vollständig gespaltenes ist strukturierter und funktioniert an Gefällen besser."},{"heading":"Wie pflegt man nach dem Verlegen?","body":"In den ersten zwei Wochen werden die Fugen nachgefüllt: Splitt oder Sand setzen sich nach Regen und müssen auf Steinniveau gebracht werden. Danach einmal im Jahr fegen, bei Bedarf Fugen nachfüllen und mit Wasser abspülen. Polymerfugensand hält besser als gewöhnlicher und lässt kein Gras wachsen, ist aber teurer.\n\nIm Winter Schnee mit Kunststoff- oder Gummischaufel räumen, Salz schadet Granit nicht. Moos auf der schattigen Nordseite wird alle paar Jahre mit dem Hochdruckreiniger abgewaschen. Ist ein Stein abgesackt oder beschädigt, wird er herausgenommen, der Unterbau aufgefüllt und der Stein wieder gesetzt: Das ist der Hauptvorteil von Pflaster gegenüber Asphalt und Beton."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Sand","Ausgleichsschicht 3–5 cm","Nur auf verdichtetem Schotter"],["Schotter","Tragschicht 15–25 cm","Lagenweise Verdichtung mit der Rüttelplatte"],["Beton","Randsteine, schwache Böden, Rinnen","Entwässerung und Dehnungsfugen"],["Geotextil","Zwischen Boden und Schotter","Verhindert das Vermischen der Schichten"]]},"faq":[{"question":"Welche Pflasterdicke für Autos?","answer":"80–100 mm für Pkw und 100 mm für Lkw und Sattelzüge. Fußwege — 50–60 mm."},{"question":"Braucht es Beton?","answer":"Unter dem Pflaster selbst meist nicht: Verdichteter Schotter und Splitt funktionieren besser, weil sie Wasser durchlassen. Beton braucht es unter Randsteinen, Rinnen und auf schwachen oder aufgeschütteten Böden."},{"question":"Wie füllt man die Fugen?","answer":"Mit Granitsplitt oder feinem Sand, der in die Fugen gekehrt und in mehreren Durchgängen eingeschlämmt wird. Polymersand hält länger und wächst nicht zu."},{"question":"Wie lange hält es?","answer":"Der Stein — unbegrenzt. Der Unterbau bei richtiger Technik — 30 Jahre und mehr ohne Neuverlegung."}]},"en":{"title":"Laying granite paving: technique and base","h1":"How granite paving is laid — stages and base","description":"Laying granite paving: base layers for a path and a driveway, slopes, kerbs, paving patterns, joint filling and care after laying.","dek":"Base, slopes, joints and the order of work for a stable pavement.","intro":"Granite paving lasts forever, but the base under it does not if it is done wrong. Sunken ruts on a driveway and “waves” on a path are always a mistake in the layers, compaction or water, never in the stone. We describe the technique we work by and explain how the base for pedestrians differs from the one for a car.","sections":[{"heading":"How to lay paving correctly?","body":"The sequence is the same for every area: marking out and planning the slopes, excavating soil to the depth of all layers, geotextile, crushed stone compacted in layers, kerbs on concrete, a levelling layer, laying the stone, tamping, filling the joints.\n\nThe surface slope away from the building is at least 1.5–2 %, that is 2 cm per metre. Water must go to the lawn, a drainage channel or a gully, not to the wall. This rule is more important than the thickness of the stone."},{"heading":"What base to prepare?","body":"Footpath: excavation 25–30 cm, geotextile, 20–40 mm crushed stone in a 15 cm layer compacted with a plate compactor, a levelling layer of granite screenings or a sand-cement mix 3–5 cm, paving 50–60 mm.\n\nDriveway and parking space: excavation 40–45 cm, geotextile, 40–70 mm crushed stone in a 15 cm layer, 20–40 mm crushed stone in a 10 cm layer, each layer compacted separately, a levelling layer 3–4 cm, paving 80–100 mm. On weak soils a 10 cm layer of sand is added under the crushed stone, or a reinforced concrete slab.\n\nKerbs are set on a concrete bed before the stone is laid: they hold the pavement from spreading. Without kerbs, or with kerbs “on sand”, the edges sink in the first season."},{"heading":"What paving patterns are there?","body":"In rows: the simplest and fastest, suits paths. Offset by half a sett: stronger, because the joints do not line up, the standard for driveways. In arcs and fans: the classic of European squares in split 100 × 100 mm setts; it needs experience and more stone, but carries loads excellently.\n\nFor contrasting patterns grey Grey Ukraine is combined with red Maple Red or black gabbro: borders, bands, a checkerboard module. Sawn-split setts with a flat top are more comfortable for walking in heels and cycling; fully split ones are more textured and work better on slopes."},{"heading":"How to care for it after laying?","body":"For the first two weeks the joints are topped up: screenings or sand settle after rain and must be brought up to the level of the stone. After that, sweep once a year, top up the joints if needed and rinse with water. Polymer jointing sand holds better than ordinary sand and does not grow grass, but costs more.\n\nIn winter clear snow with a plastic or rubber shovel; salt does not harm granite. Moss on the shady north side is washed off with a pressure washer every few years. If one stone has sunk or is damaged, it is lifted, the base topped up and it is laid back: that is the main advantage of paving over asphalt and concrete."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Sand","Levelling layer 3–5 cm","Only on top of compacted crushed stone"],["Crushed stone","Bearing layer 15–25 cm","Layer-by-layer compaction with a plate compactor"],["Concrete","Kerbs, weak soils, channels","Drainage and movement joints"],["Geotextile","Between soil and crushed stone","Stops the layers mixing"]]},"faq":[{"question":"What paving thickness for a car?","answer":"80–100 mm for passenger cars and 100 mm for lorries. Footpaths — 50–60 mm."},{"question":"Is concrete needed?","answer":"Under the paving itself usually not: compacted crushed stone and screenings work better because they let water through. Concrete is needed under kerbs and channels and on weak or fill soils."},{"question":"How to fill the joints?","answer":"With granite screenings or fine sand, swept into the joints and watered in several passes. Polymer sand holds longer and does not grow weeds."},{"question":"How long does it last?","answer":"The stone — indefinitely. The base with correct technique — 30 years and more without relaying."}]},"lt":{"title":"Granito grindinio klojimas: technologija ir pagrindas","h1":"Kaip klojamas granito grindinys — etapai ir pagrindas","description":"Granito grindinio klojimas: pagrindo sluoksniai takui ir įvažiavimui, nuolydžiai, bortai, klojimo būdai, siūlių užpildymas ir priežiūra po klojimo.","dek":"Pagrindas, nuolydžiai, siūlės ir darbų tvarka stabiliai dangai.","intro":"Granito grindinys tarnauja amžinai, o pagrindas po juo — ne, jei jis padarytas neteisingai. Įdubusios vėžės įvažiavime ir „bangos“ take — visada klaida sluoksniuose, sutankinime ar vandenyje, o ne akmenyje. Aprašome technologiją, pagal kurią dirbame, ir paaiškiname, kuo skiriasi pagrindas pėstiesiems ir automobiliui.","sections":[{"heading":"Kaip teisingai kloti grindinį?","body":"Seka viena visiems plotams: žymėjimas ir nuolydžių planavimas, grunto iškasimas visų sluoksnių gyliui, geotekstilė, skalda su sluoksniniu sutankinimu, bortai ant betono, išlyginamasis sluoksnis, akmens klojimas, tankinimas, siūlių užpildymas.\n\nDangos nuolydis nuo namo ne mažiau 1,5–2 %, tai yra 2 cm metrui. Vanduo turi tekėti į veją, drenažo lovelį ar lietaus surinktuvą, o ne į sieną. Ši taisyklė svarbesnė už akmens storį."},{"heading":"Kokį pagrindą parengti?","body":"Pėsčiųjų takas: iškasa 25–30 cm, geotekstilė, 20–40 frakcijos skalda 15 cm sluoksniu, sutankinta vibroplokšte, išlyginamasis sluoksnis iš granito atsijų arba smėlio ir cemento mišinio 3–5 cm, grindinys 50–60 mm.\n\nĮvažiavimas ir stovėjimo vieta: iškasa 40–45 cm, geotekstilė, 40–70 skalda 15 cm sluoksniu, 20–40 skalda 10 cm sluoksniu, kiekvienas sluoksnis tankinamas atskirai, išlyginamasis sluoksnis 3–4 cm, grindinys 80–100 mm. Silpnuose gruntuose pridedamas 10 cm smėlio sluoksnis po skalda arba armuota betono plokštė.\n\nBortai statomi ant betono pagalvės prieš klojant akmenį: jie laiko dangą nuo išsiplėtimo. Be bortų arba su bortais „ant smėlio“ kraštai nusėda per pirmą sezoną."},{"heading":"Kokie yra klojimo būdai ir raštai?","body":"Eilėmis: paprasčiausias ir greičiausias, tinka takams. Su puse akmens poslinkiu: tvirtesnis, nes siūlės nesutampa, standartas įvažiavimams. Lankais ir vėduokle: Europos aikščių klasika iš skaldyto 100 × 100 mm grindinio, reikalauja patirties ir daugiau akmens, bet puikiai laiko apkrovas.\n\nKontrastingiems raštams derinamas pilkas Grey Ukraine su raudonu Maple Red arba juodu gabru: apvadas, juostos, šachmatinis modulis. Pjautas-skaldytas grindinys su lygiu viršumi patogesnis vaikščioti su kulniukais ir važiuoti dviračiu, visiškai skaldytas faktūriškesnis ir geriau dirba nuolydžiuose."},{"heading":"Kaip prižiūrėti po klojimo?","body":"Pirmas dvi savaites siūlės papildomos: atsijos ar smėlis nusėda po lietų, ir juos reikia užpildyti iki akmens lygio. Toliau kartą per metus šluojama, esant reikalui papildomos siūlės ir nuplaunama vandeniu. Polimerinis smėlis siūlėms laikosi geriau nei paprastas ir neapželia žole, bet brangesnis.\n\nŽiemą valykite sniegą plastikiniu ar guminiu kastuvu, druska granitui nekenkia. Samanos šiaurinėje šešėlinėje pusėje nuplaunamos vandeniu su slėgiu kartą per kelis metus. Jei vienas akmuo nusėdo ar pažeistas, jį išima, papildo pagrindą ir deda atgal: tai pagrindinis grindinio privalumas prieš asfaltą ir betoną."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Smėlis","Išlyginamasis sluoksnis 3–5 cm","Tik ant sutankintos skaldos"],["Skalda","Laikantysis sluoksnis 15–25 cm","Sluoksninis tankinimas vibroplokšte"],["Betonas","Bortai, silpni gruntai, loveliai","Drenažas ir deformacinės siūlės"],["Geotekstilė","Tarp grunto ir skaldos","Neleidžia sluoksniams maišytis"]]},"faq":[{"question":"Koks grindinio storis automobiliui?","answer":"80–100 mm lengviesiems automobiliams ir 100 mm sunkvežimiams ir vilkikams. Pėsčiųjų takai — 50–60 mm."},{"question":"Ar reikia betono?","answer":"Po pačiu grindiniu paprastai ne: sutankinta skalda ir atsijos dirba geriau, nes praleidžia vandenį. Betono reikia po bortais, loveliais ir silpnuose ar supiltuose gruntuose."},{"question":"Kaip užpildyti siūles?","answer":"Granito atsijomis arba smulkiu smėliu, kuris sušluojamas į siūles ir perpilamas vandeniu keliais kartais. Polimerinis smėlis laikosi ilgiau ir neapželia."},{"question":"Kiek tarnauja?","answer":"Akmuo — neribotai. Pagrindas pagal teisingą technologiją — 30 ir daugiau metų be perklojimo."}]},"pl":{"title":"Układanie kostki granitowej: technologia i podłoże","h1":"Jak układa się kostkę granitową — etapy i podłoże","description":"Układanie kostki granitowej: warstwy podłoża pod ścieżkę i podjazd, spadki, krawężniki, sposoby brukowania, wypełnienie spoin i pielęgnacja po ułożeniu.","dek":"Podłoże, spadki, spoiny i kolejność prac dla stabilnej nawierzchni.","intro":"Kostka granitowa służy wiecznie, ale podłoże pod nią nie, jeśli zrobić je źle. Zapadnięte koleiny na podjeździe i „fale” na ścieżce to zawsze błąd w warstwach, zagęszczeniu lub wodzie, a nie w kamieniu. Opisujemy technologię, według której pracujemy, i wyjaśniamy, czym różni się podłoże dla pieszych i dla samochodu.","sections":[{"heading":"Jak prawidłowo ułożyć kostkę?","body":"Kolejność jest jedna dla wszystkich powierzchni: wytyczenie i zaplanowanie spadków, wykop na głębokość wszystkich warstw, geowłóknina, tłuczeń z warstwowym zagęszczeniem, krawężniki na betonie, warstwa wyrównująca, układanie kamienia, ubijanie, wypełnienie spoin.\n\nSpadek nawierzchni od budynku nie mniej niż 1,5–2 %, czyli 2 cm na metr. Woda ma iść do trawnika, korytka odwadniającego lub wpustu, a nie do ściany. Ta zasada jest ważniejsza od grubości kamienia."},{"heading":"Jakie podłoże przygotować?","body":"Ścieżka piesza: wykop 25–30 cm, geowłóknina, tłuczeń frakcji 20–40 warstwą 15 cm zagęszczony płytą wibracyjną, warstwa wyrównująca z grysu granitowego lub mieszanki piasku z cementem 3–5 cm, kostka 50–60 mm.\n\nPodjazd i miejsce parkingowe: wykop 40–45 cm, geowłóknina, tłuczeń 40–70 warstwą 15 cm, tłuczeń 20–40 warstwą 10 cm, każdą warstwę zagęszcza się osobno, warstwa wyrównująca 3–4 cm, kostka 80–100 mm. Na słabych gruntach dodaje się warstwę piasku 10 cm pod tłuczeń lub zbrojoną płytę betonową.\n\nKrawężniki stawia się na ławie betonowej przed ułożeniem kamienia: trzymają nawierzchnię przed rozjechaniem. Bez krawężników lub z krawężnikami „na piasek” brzegi osiadają w pierwszym sezonie."},{"heading":"Jakie są sposoby brukowania i wzory?","body":"Rzędami: najprostszy i najszybszy, pasuje na ścieżki. Z przesunięciem o pół kostki: mocniejszy, bo spoiny się nie pokrywają, standard na podjazdy. Łukami i wachlarzem: klasyka europejskich placów z kostki łupanej 100 × 100 mm, wymaga doświadczenia i większej ilości kamienia, ale świetnie przenosi obciążenia.\n\nDla kontrastowych wzorów łączy się szary Grey Ukraine z czerwonym Maple Red lub czarnym gabro: obramowanie, pasy, moduł szachownicy. Kostka cięto-łupana z równą górą jest wygodniejsza do chodzenia w szpilkach i na rowerze, w pełni łupana jest bardziej fakturowa i lepiej pracuje na spadkach."},{"heading":"Jak pielęgnować po ułożeniu?","body":"Przez pierwsze dwa tygodnie spoiny dosypuje się: grys lub piasek osiadają po deszczach i trzeba je doprowadzić do poziomu kamienia. Dalej raz w roku zamiata się, w razie potrzeby dosypuje spoiny i spłukuje wodą. Piasek polimerowy do spoin trzyma się lepiej od zwykłego i nie porasta trawą, ale jest droższy.\n\nZimą odgarniaj śnieg łopatą plastikową lub gumową, sól granitowi nie szkodzi. Mech po północnej, zacienionej stronie zmywa się wodą pod ciśnieniem raz na kilka lat. Jeśli jeden kamień się zapadł lub uszkodził, wyjmuje się go, dosypuje podłoże i układa z powrotem: to główna zaleta brukowania nad asfaltem i betonem."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Piasek","Warstwa wyrównująca 3–5 cm","Tylko na zagęszczonym tłuczniu"],["Tłuczeń","Warstwa nośna 15–25 cm","Warstwowe zagęszczanie płytą wibracyjną"],["Beton","Krawężniki, słabe grunty, korytka","Odwodnienie i szczeliny dylatacyjne"],["Geowłóknina","Między gruntem i tłuczniem","Nie pozwala warstwom się mieszać"]]},"faq":[{"question":"Jaka grubość kostki pod auto?","answer":"80–100 mm dla aut osobowych i 100 mm dla ciężarówek. Ścieżki piesze — 50–60 mm."},{"question":"Czy potrzebny jest beton?","answer":"Pod samą kostkę zwykle nie: zagęszczony tłuczeń i grys pracują lepiej, bo przepuszczają wodę. Beton potrzebny jest pod krawężniki, korytka oraz na słabych lub nasypowych gruntach."},{"question":"Jak wypełnić spoiny?","answer":"Grysem granitowym lub drobnym piaskiem, który zamiata się w spoiny i przelewa wodą w kilku podejściach. Piasek polimerowy trzyma się dłużej i nie porasta."},{"question":"Jak długo służy?","answer":"Kamień — bez ograniczeń. Podłoże przy prawidłowej technologii — 30 i więcej lat bez przekładania."}]}}'::jsonb) where slug = 'ukladannya-granitnoyi-brukivky';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Stein für den Kamin: Granit, Marmor oder Travertin","h1":"Welchen Stein für die Kaminverkleidung wählen","description":"Stein für den Kamin: Granit, Marmor, Travertin oder Labradorit. Hitzebeständigkeit, technische Abstände zum Feuerraum, Kleber, Pflege und Optik des Portals.","dek":"Gestein und Verkleidungsdetail für verschiedene Kamintypen.","intro":"Das Kaminportal ist das auffälligste Steinstück im Wohnzimmer und arbeitet unter den härtesten Bedingungen: Erwärmung, Ruß, schroffe Temperaturwechsel. Naturstein ist dafür geschaffen, aber Gestein, Detail und Kleber müssen zum Kamintyp passen. Wir erklären den Unterschied zwischen Holz-, Gas- und Elektrokamin und was wir für jeden empfehlen.","sections":[{"heading":"Welcher Stein eignet sich für den Kamin?","body":"Für einen Holzkamin mit offenem oder geschlossenem Feuerraum: Granit oder Gabbro für das Portal und besonders für das Podest vor dem Feuerraum, wo Funken und Glut fallen. Für Gas: jeder Stein, auch Marmor, denn die Erwärmung ist moderat. Für Elektro: keine Einschränkungen, das ist ein Möbel.\n\nLabradorit Volga Blue ist eine der effektvollsten Varianten für das Portal: Das blaue Aufblitzen der Kristalle lebt im Feuerschein auf. Travertin wählt man für warme mediterrane Interieurs, seine Poren brauchen aber Schutz vor Ruß."},{"heading":"Warum ist Granit für intensive Nutzung besser?","body":"Granit verändert bei Erwärmung auf 200–250 °C die Farbe nicht, nimmt nach der Imprägnierung keinen Ruß auf, hält den Stoß von Holzscheiten aus und lässt sich leicht waschen. Auf dem Podest vor dem Feuerraum kann man ihn mit einer harten Bürste von Glut reinigen. Die polierte Oberfläche spiegelt das Feuer und bringt Licht in den Raum.\n\nDie Wärmedehnung von Granit ist gering, aber das Portal wird nicht bündig an den Feuerraum geklebt: Zwischen Metall und Stein bleibt ein Spalt von 5–10 mm mit hitzebeständiger Dichtmasse oder Mineralwolle, und die Platten werden auf hitzebeständigen Steinkleber gesetzt."},{"heading":"Wann Marmor wählen?","body":"Marmor ist die Klassik der Kaminportale von Versailles bis zu den Lemberger Stadthäusern. Wählen Sie ihn für Gas- und Elektrokamine oder für Holzkamine mit geschlossenem Feuerraum, wo das Portal keinen Kontakt zur Flamme hat und einen technischen Abstand einhält.\n\nAuf Marmor sind Ruß und Fingerabdrücke sichtbar, und saure Reiniger für die Kaminscheibe ätzen die Oberfläche. Deshalb wird ein Marmorportal nur mit neutralen Mitteln gepflegt und einmal im Jahr imprägniert. Bianco Carrara und Nero Marquina sind die häufigste Wahl; Crema Marfil ergibt ein warmes, ruhiges Portal für ein helles Wohnzimmer."},{"heading":"Wie steht es um Hitzebeständigkeit und Pflege?","body":"Naturstein hält die Erwärmung aus, die ein Portal erreicht, aber keine plötzliche lokale Erhitzung: Ein heißer Gusseisentopf auf dem Marmorpodest kann eine Spur oder einen Riss hinterlassen. Deshalb fertigen wir das Podest vor einem Holzfeuerraum aus Granit oder Gabbro.\n\nPflege: Ruß wird mit Wasser und neutralem Mittel abgewaschen, starke Verschmutzung mit einer Natronkompresse. Granit wird alle zwei bis drei Jahre imprägniert, Marmor und Travertin jährlich. Einmal pro Saison den Spalt zwischen Feuerraum und Stein prüfen: Die Dichtmasse muss elastisch und rissfrei sein."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Granit / Gabbro","Holzkamine, Podest","Hitzebeständig, mit Bürste waschbar"],["Labradorit","Akzentportal","Kristallglanz im Feuerschein"],["Marmor","Gas- und geschlossene Feuerräume, Klassik","Empfindlich gegen Säuren und Ruß"],["Travertin","Warme Interieurs","Poren jährlich imprägnieren"]]},"faq":[{"question":"Hält Marmor die Hitze aus?","answer":"Moderate Erwärmung des Portals — ja. Direkter Kontakt mit Flamme, Funken oder heißem Metall — nein, für diese Zonen nehmen wir Granit."},{"question":"Was für den Holzkamin?","answer":"Granit oder Gabbro für Portal und Podest, hitzebeständiger Kleber, 5–10 mm Abstand zum Feuerraum mit elastischer Dichtmasse."},{"question":"Was für die Klassik?","answer":"Marmor Bianco Carrara oder Nero Marquina mit profilierter Kante, manchmal mit geschnitzten Elementen. Für einen Gas- oder geschlossenen Feuerraum ist das eine sichere Wahl."},{"question":"Wie reinigt man das Portal?","answer":"Mit neutralem Steinreiniger und weichem Tuch. Ruß mit einer Natronkompresse. Keine Säuren, besonders auf Marmor, und keine Kaminscheibenreiniger auf dem Stein."}]},"en":{"title":"Stone for a fireplace: granite, marble or travertine","h1":"Which stone to choose for fireplace cladding","description":"Stone for a fireplace: granite, marble, travertine or labradorite. Heat resistance, technical gaps from the firebox, adhesive, care and the look of the surround.","dek":"The stone and cladding detail for different types of fireplace.","intro":"A fireplace surround is the most visible stone piece in a living room, and it works in the harshest conditions: heat, soot, sharp temperature changes. Natural stone was made for this, but the rock, the detail and the adhesive must match the type of fireplace. We explain the difference between wood-burning, gas and electric and what we advise for each.","sections":[{"heading":"Which stone suits a fireplace?","body":"For a wood-burning fireplace with an open or closed firebox: granite or gabbro for the surround and especially for the hearth in front of the firebox, where sparks and embers fall. For gas: any stone, including marble, because the heating is moderate. For electric: no restrictions, it is furniture.\n\nVolga Blue labradorite is one of the most striking options for a surround: the blue flash of the crystals comes alive in firelight. Travertine is chosen for warm Mediterranean interiors, but its pores need protection from soot."},{"heading":"Why is granite better for active use?","body":"Granite does not change colour when heated to 200–250 °C, does not absorb soot once sealed, withstands knocks from logs and washes easily. On the hearth in front of the firebox it can be cleaned of embers with a stiff brush. A polished surface reflects the fire and adds light to the room.\n\nGranite''s thermal expansion is small, but the surround is not glued tight to the firebox: a 5–10 mm gap with heat-resistant sealant or mineral wool is left between metal and stone, and the slabs are laid on heat-resistant stone adhesive."},{"heading":"When to choose marble?","body":"Marble is the classic of fireplace surrounds from Versailles to Lviv townhouses. Choose it for gas and electric fireplaces or for wood-burning ones with a closed firebox, where the surround does not touch the flame and has a technical gap.\n\nSoot and fingerprints show on marble, and acidic cleaners for the firebox glass etch the surface. So a marble surround is cared for only with neutral products and sealed once a year. Bianco Carrara and Nero Marquina are the most common choice; Crema Marfil gives a warm calm surround for a light living room."},{"heading":"What about heat resistance and care?","body":"Natural stone withstands the heat a surround reaches, but not sudden local heating: a hot cast-iron pot on a marble hearth can leave a mark or a crack. That is why we make the hearth in front of a wood-burning firebox from granite or gabbro.\n\nCare: soot is washed off with water and a neutral cleaner, heavy dirt with a baking soda poultice. Granite is sealed every two to three years, marble and travertine every year. Once a season inspect the gap between the firebox and the stone: the sealant must be elastic and free of cracks."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Granite / gabbro","Wood-burning fireplaces, hearth","Heat-resistant, brush-washable"],["Labradorite","Accent surround","Crystal sparkle in firelight"],["Marble","Gas and closed fireboxes, classic","Sensitive to acids and soot"],["Travertine","Warm interiors","Seal the pores every year"]]},"faq":[{"question":"Does marble take the heat?","answer":"Moderate heating of the surround — yes. Direct contact with flame, sparks or hot metal — no; for those zones we use granite."},{"question":"What for a wood-burning fireplace?","answer":"Granite or gabbro for the surround and hearth, heat-resistant adhesive, a 5–10 mm gap from the firebox with elastic sealant."},{"question":"What for a classic look?","answer":"Bianco Carrara or Nero Marquina marble with a profiled edge, sometimes with carved elements. For a gas or closed firebox it is a safe choice."},{"question":"How to clean the surround?","answer":"With a neutral stone cleaner and a soft cloth. Soot with a baking soda poultice. No acids, especially on marble, and no firebox glass cleaners on the stone."}]},"lt":{"title":"Akmuo židiniui: granitas, marmuras ar travertinas","h1":"Kokį akmenį rinktis židinio apdailai","description":"Akmuo židiniui: granitas, marmuras, travertinas arba labradoritas. Atsparumas karščiui, techniniai tarpai nuo pakuros, klijai, priežiūra ir portalo išvaizda.","dek":"Uoliena ir apdailos mazgas skirtingiems židinių tipams.","intro":"Židinio portalas — labiausiai matomas akmens gaminys svetainėje, ir jis dirba sunkiausiomis sąlygomis: įkaitimas, suodžiai, staigūs temperatūros svyravimai. Natūralus akmuo tam sukurtas, bet uoliena, mazgas ir klijai turi atitikti židinio tipą. Paaiškiname skirtumą tarp malkinio, dujinio ir elektrinio ir ką patariame kiekvienam.","sections":[{"heading":"Koks akmuo tinka židiniui?","body":"Malkiniam židiniui su atvira ar uždara pakura: granitas arba gabras portalui ir ypač podiumui prieš pakurą, kur krinta kibirkštys ir žarijos. Dujiniam: bet koks akmuo, įskaitant marmurą, nes įkaitimas vidutinis. Elektriniam: apribojimų nėra, tai baldas.\n\nLabradoritas Volga Blue — vienas efektingiausių variantų portalui: mėlynas kristalų blyksnis atgyja ugnies šviesoje. Travertiną renkasi šiltiems Viduržemio jūros interjerams, bet jo poros reikalauja apsaugos nuo suodžių."},{"heading":"Kuo granitas geresnis aktyviam naudojimui?","body":"Granitas nekeičia spalvos įkaitęs iki 200–250 °C, po impregnavimo neįgeria suodžių, atlaiko malkų smūgius ir lengvai plaunamas. Podiume prieš pakurą jį galima valyti nuo žarijų kietu šepečiu. Poliruotas paviršius atspindi ugnį ir prideda kambariui šviesos.\n\nGranito šiluminis plėtimasis nedidelis, bet portalas neklijuojamas prie pakuros glaudžiai: tarp metalo ir akmens paliekamas 5–10 mm tarpas su karščiui atspariu sandarikliu ar mineraline vata, o plokštės dedamos ant karščiui atsparių akmens klijų."},{"heading":"Kada rinktis marmurą?","body":"Marmuras — židinių portalų klasika nuo Versalio iki Lvivo namų. Rinkitės jį dujiniams ir elektriniams židiniams arba malkiniams su uždara pakura, kur portalas neliečia liepsnos ir turi techninį tarpą.\n\nAnt marmuro matomi suodžiai ir rankų pėdsakai, o rūgštinės pakuros stiklo valymo priemonės ėsdina paviršių. Todėl marmuro portalas prižiūrimas tik neutraliomis priemonėmis ir impregnuojamas kartą per metus. Bianco Carrara ir Nero Marquina — dažniausias pasirinkimas; Crema Marfil suteikia šiltą ramų portalą šviesiai svetainei."},{"heading":"Kas dėl atsparumo karščiui ir priežiūros?","body":"Natūralus akmuo atlaiko įkaitimą, kurį pasiekia portalas, bet neatlaiko staigaus vietinio įkaitimo: karštas ketaus indas ant marmuro podiumo gali palikti pėdsaką ar įtrūkimą. Todėl podiumą prieš malkinę pakurą darome iš granito arba gabro.\n\nPriežiūra: suodžiai nuplaunami vandeniu su neutralia priemone, sunkūs nešvarumai — sodos kompresu. Granitas impregnuojamas kartą per dvejus–trejus metus, marmuras ir travertinas — kasmet. Kartą per sezoną apžiūrėkite tarpą tarp pakuros ir akmens: sandariklis turi būti elastingas ir be įtrūkimų."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Granitas / gabras","Malkiniai židiniai, podiumas","Atsparus karščiui, plaunamas šepečiu"],["Labradoritas","Akcentinis portalas","Kristalų blizgesys ugnies šviesoje"],["Marmuras","Dujinės ir uždaros pakuros, klasika","Jautrus rūgštims ir suodžiams"],["Travertinas","Šilti interjerai","Poras impregnuoti kasmet"]]},"faq":[{"question":"Ar marmuras atlaiko karštį?","answer":"Vidutinį portalo įkaitimą — taip. Tiesioginį kontaktą su liepsna, kibirkštimis ar karštu metalu — ne, šioms zonoms imame granitą."},{"question":"Kas malkiniam židiniui?","answer":"Granitas arba gabras portalui ir podiumui, karščiui atsparūs klijai, 5–10 mm tarpas nuo pakuros su elastingu sandarikliu."},{"question":"Kas klasikai?","answer":"Marmuras Bianco Carrara arba Nero Marquina su profiliuotu kraštu, kartais su raižytais elementais. Dujinei ar uždarai pakurai tai saugus pasirinkimas."},{"question":"Kaip valyti portalą?","answer":"Neutralia akmens priemone ir minkšta šluoste. Suodžius — sodos kompresu. Be rūgščių, ypač ant marmuro, ir be pakuros stiklo valiklių ant akmens."}]},"pl":{"title":"Kamień na kominek: granit, marmur czy trawertyn","h1":"Jaki kamień wybrać na okładzinę kominka","description":"Kamień na kominek: granit, marmur, trawertyn lub labradoryt. Odporność termiczna, szczeliny techniczne od wkładu, klej, pielęgnacja i wygląd portalu.","dek":"Skała i detal okładziny dla różnych typów kominków.","intro":"Portal kominkowy to najbardziej widoczny kamienny wyrób w salonie i pracuje w najtrudniejszych warunkach: nagrzewanie, sadza, gwałtowne zmiany temperatury. Kamień naturalny jest do tego stworzony, ale skała, detal i klej muszą odpowiadać typowi kominka. Wyjaśniamy różnicę między kominkiem na drewno, gazowym i elektrycznym oraz co radzimy do każdego.","sections":[{"heading":"Który kamień nadaje się na kominek?","body":"Do kominka na drewno z otwartą lub zamkniętą komorą: granit lub gabro na portal, a szczególnie na podest przed wkładem, gdzie spadają iskry i węgle. Do gazowego: każdy kamień, także marmur, bo nagrzewanie jest umiarkowane. Do elektrycznego: ograniczeń nie ma, to mebel.\n\nLabradoryt Volga Blue to jeden z najefektowniejszych wariantów na portal: niebieski błysk kryształów ożywa w świetle ognia. Trawertyn wybiera się do ciepłych śródziemnomorskich wnętrz, ale jego pory wymagają ochrony przed sadzą."},{"heading":"Czym granit jest lepszy przy intensywnym użytkowaniu?","body":"Granit nie zmienia koloru od nagrzania do 200–250 °C, po impregnacji nie chłonie sadzy, wytrzymuje uderzenie polan i łatwo się myje. Na podeście przed wkładem można go czyścić z węgla twardą szczotką. Polerowana powierzchnia odbija ogień i dodaje pokojowi światła.\n\nRozszerzalność cieplna granitu jest niewielka, ale portalu nie przykleja się do wkładu na styk: między metalem i kamieniem zostawia się szczelinę 5–10 mm z uszczelniaczem żaroodpornym lub wełną mineralną, a płyty układa się na żaroodpornym kleju do kamienia."},{"heading":"Kiedy wybrać marmur?","body":"Marmur to klasyka portali kominkowych od Wersalu do lwowskich kamienic. Wybieraj go do kominków gazowych i elektrycznych albo do kominków na drewno z zamkniętą komorą, gdzie portal nie ma kontaktu z płomieniem i ma szczelinę techniczną.\n\nNa marmurze widoczna jest sadza i ślady po rękach, a kwasowe środki do czyszczenia szyby wkładu wytrawiają powierzchnię. Dlatego portal marmurowy pielęgnuje się tylko środkami neutralnymi i impregnuje raz w roku. Bianco Carrara i Nero Marquina to najpowszechniejszy wybór; Crema Marfil daje ciepły, spokojny portal do jasnego salonu."},{"heading":"Co z odpornością termiczną i pielęgnacją?","body":"Kamień naturalny wytrzymuje nagrzanie, jakie osiąga portal, ale nie wytrzymuje gwałtownego miejscowego nagrzania: gorące żeliwne naczynie na marmurowym podeście może zostawić ślad lub pęknięcie. Dlatego podest przed wkładem na drewno robimy z granitu lub gabro.\n\nPielęgnacja: sadzę zmywa się wodą ze środkiem neutralnym, ciężkie zabrudzenia kompresem z sody. Granit impregnuje się raz na dwa–trzy lata, marmur i trawertyn co roku. Raz w sezonie sprawdzaj szczelinę między wkładem i kamieniem: uszczelniacz ma być elastyczny i bez pęknięć."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Granit / gabro","Kominki na drewno, podest","Żaroodporny, myje się szczotką"],["Labradoryt","Portal akcentowy","Błysk kryształów w świetle ognia"],["Marmur","Wkłady gazowe i zamknięte, klasyka","Wrażliwy na kwasy i sadzę"],["Trawertyn","Ciepłe wnętrza","Pory impregnować co roku"]]},"faq":[{"question":"Czy marmur wytrzymuje żar?","answer":"Umiarkowane nagrzanie portalu — tak. Bezpośredni kontakt z płomieniem, iskrami lub gorącym metalem — nie, do tych stref bierzemy granit."},{"question":"Co do kominka na drewno?","answer":"Granit lub gabro na portal i podest, klej żaroodporny, szczelina 5–10 mm od wkładu z elastycznym uszczelniaczem."},{"question":"Co do klasyki?","answer":"Marmur Bianco Carrara lub Nero Marquina z profilowaną krawędzią, czasem z elementami rzeźbionymi. Do wkładu gazowego lub zamkniętego to bezpieczny wybór."},{"question":"Jak czyścić portal?","answer":"Neutralnym środkiem do kamienia i miękką ściereczką. Sadzę kompresem z sody. Bez kwasów, zwłaszcza na marmurze, i bez środków do czyszczenia szyby wkładu na kamieniu."}]}}'::jsonb) where slug = 'kamin-dlya-kaminu-granit-marmur';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Landschaftsstein für den Hof: Arten und Anwendung","h1":"Landschaftsstein — wie man ihn für Hof und Garten wählt","description":"Landschaftsstein für den Hof: Platten für Wege, Stützmauern, Randsteine, Beete. Frostbeständigkeit, rutschhemmende Oberfläche, Kombination mit Pflaster und Fassade.","dek":"Stein für Wege, Beete, Stützmauern und Dekorzonen.","intro":"Im Garten arbeitet Stein anders als im Haus: Hier gibt es kein heißes Geschirr, dafür Frost, Wasser, Wurzeln und den Rasenmäher. Landschaftsstein wählt man nicht nach der Schönheit auf der Platte, sondern nach der Funktion: worauf man geht, was er hält, was er betont. Wir erklären, welche Granitprodukte wir für Höfe fertigen und wie sie sich mit Pflaster und Fassade verbinden.","sections":[{"heading":"Welchen Landschaftsstein wählen?","body":"Granit deckt alle Aufgaben des Hofs ab: Platten für Wege und Terrassen, Randsteine, Stufen, Stützmauern, Verkleidung von Beeten und Teichen. Er ist frostbeständig, fürchtet weder Wasser noch Salz, und eine geflammte Oberfläche ist nicht rutschig. Sandstein und Kalkstein sind weicher und poröser, in unserem Klima blättern sie nach einigen Wintern ab.\n\nFür Dekorzonen eignet sich gespaltener Stein aus Produktionsresten: Bruchstein für Trockenmauern, Rollstein für Beete. Das ist ein günstiger Weg zu natürlicher Textur, und wir bieten ihn zusammen mit den Hauptprodukten an."},{"heading":"Welche Arten werden im Hof verwendet?","body":"Platten für Wege und Terrassen: 30–40 mm zum Verlegen auf Schotter und Sand, 20 mm auf Betonunterbau, Formate von 300 × 300 bis 600 × 900 mm, geflammt oder gesägt. Stufen und Gartentreppen: Massivblöcke oder Belagstufen 30–40 mm auf Beton.\n\nStützmauern: Granitblöcke 200–400 mm oder Verkleidungsplatten auf Betonkern. Randsteine: gesägt oder gespalten, 80–150 mm hoch, halten Wege und Rasen. Verkleidungen: Beete, Schalen, Teiche, Außenküchen, Bänke und Grillplatten aus geflammtem Granit."},{"heading":"Wie kombiniert man Stein mit Pflaster und Fassade?","body":"Eine Regel: nicht mehr als zwei Gesteine im Hof. Zum Beispiel Grey Ukraine in Pflaster und Terrassenplatten plus Kometa Black in Randsteinen, Stufen und Akzentstreifen. Sind Fassade oder Sockel aus Stein, setzt die Landschaft deren Gestein fort.\n\nOberflächen nach Funktion abstimmen: poliert nur an Vertikalen und Akzenten, geflammt überall, wo man geht. Modulmaße sollte man als Vielfaches des Pflasters (100 mm) abstimmen, damit Plattenweg und Pflastereinfahrt ohne Zuschnitt aneinanderstoßen."},{"heading":"Wie pflegt man Landschaftsstein?","body":"Zweimal im Jahr mit dem Hochdruckreiniger abspülen, besonders schattige Bereiche, wo Moos wächst. Eine Imprägnierung braucht Granit im Freien nicht, Sandstein und Kalkstein eine Hydrophobierung alle paar Jahre.\n\nIm Winter Kunststoffschaufel und beliebiges Streumittel, Granit verträgt sie. Einmal im Jahr die Fugen zwischen Platten und Randsteinen prüfen und bei Bedarf nachfüllen. Pflanzen mit aggressiven Wurzeln (Weide, Pappel, Bambus) nicht näher als 2–3 m an Wegen setzen: Wurzeln heben Platten unabhängig vom Gestein an."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Platten","Wege, Terrassen, Grillzone","Geflammte rutschhemmende Oberfläche"],["Gespaltener Stein","Beete, Trockenmauern, Akzente","Stabiler Unterbau, Drainage"],["Blöcke","Stützmauern, Gartentreppen","Statische Berechnung ab 1 m"],["Randsteine","Grenzen von Wegen und Rasen","Auf Betonbett"]]},"faq":[{"question":"Welcher Stein ist frostbeständig?","answer":"Granit, Gabbro und Labradorit: Wasseraufnahme unter 0,2 %, über 300 Frostzyklen ohne Veränderung. Sandstein und Kalkstein blättern in unserem Klima ab."},{"question":"Ist er nach Regen rutschig?","answer":"Poliert — ja, deshalb verlegen wir ihn nicht im Freien. Geflammter, gestockter und gesägter Granit sind nass rutschhemmend."},{"question":"Wie verlegen?","answer":"Platten 30–40 mm auf verdichteten Schotter und Splitt wie Pflaster, 20 mm auf Beton und Kleber. Randsteine und Stufen auf ein Betonbett."},{"question":"Wie reinigen?","answer":"Mit dem Hochdruckreiniger zweimal im Jahr. Moos wird abgewaschen, Salz schadet Granit nicht, Imprägnierung ist nicht nötig."}]},"en":{"title":"Landscape stone for a yard: types and uses","h1":"Landscape stone — how to choose it for a yard and garden","description":"Landscape stone for a yard: slabs for paths, retaining walls, kerbs, flower beds. Frost resistance, slip-resistant finish, combining with paving and the facade.","dek":"Stone for paths, flower beds, retaining walls and decorative zones.","intro":"In a garden stone works differently than in a house: there are no hot pans here, but there is frost, water, roots and a lawnmower. Landscape stone is chosen not for its beauty on the slab but for its function: what to walk on, what to hold, what to highlight. We explain which granite products we make for yards and how they combine with paving and the facade.","sections":[{"heading":"Which landscape stone to choose?","body":"Granite covers every task in a yard: slabs for paths and terraces, kerbs, steps, retaining walls, cladding for flower beds and ponds. It is frost-resistant, unafraid of water and salt, and a flamed surface is not slippery. Sandstone and limestone are softer and more porous; in our climate they flake after a few winters.\n\nFor decorative zones split stone from production offcuts suits well: rubble for dry walls, cobbles for flower beds. It is an affordable way to get a natural texture, and we offer it together with the main products."},{"heading":"Which types are used in a yard?","body":"Slabs for paths and terraces: 30–40 mm for laying on crushed stone and sand, 20 mm on a concrete base, formats from 300 × 300 to 600 × 900 mm, flamed or sawn finish. Steps and garden stairs: solid blocks or 30–40 mm overlay treads on concrete.\n\nRetaining walls: granite blocks 200–400 mm or cladding slabs on a concrete core. Kerbs: sawn or split, 80–150 mm high, holding paths and the lawn. Cladding: flower beds, bowls, ponds, outdoor kitchens, benches and barbecue tops of flamed granite."},{"heading":"How to combine stone with paving and the facade?","body":"One rule: no more than two stones in a yard. For example, Grey Ukraine in the paving and terrace slabs plus Kometa Black in kerbs, steps and accent bands. If the facade or plinth is stone, the landscaping continues its stone.\n\nMatch finishes to function: polished only on verticals and accents, flamed everywhere people walk. Module sizes should be matched in multiples to the paving (100 mm) so a slab path and a paved driveway meet without trimming."},{"heading":"How to care for landscape stone?","body":"Twice a year rinse with a pressure washer, especially shaded areas where moss grows. Sealing is not needed for granite outdoors; for sandstone and limestone a water repellent every few years.\n\nIn winter a plastic shovel and any de-icer; granite tolerates them. Once a year check the joints between slabs and kerbs and top up if needed. Plant trees with aggressive roots (willow, poplar, bamboo) no closer than 2–3 m from paths: roots lift slabs regardless of the type of stone."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Slabs","Paths, terraces, barbecue area","Flamed slip-resistant finish"],["Split stone","Flower beds, dry walls, accents","Stable base, drainage"],["Blocks","Retaining walls, garden steps","Engineering calculation from 1 m"],["Kerbs","Edges of paths and lawn","On a concrete bed"]]},"faq":[{"question":"Which stone is frost-resistant?","answer":"Granite, gabbro and labradorite: water absorption below 0.2 %, over 300 freeze cycles without change. Sandstone and limestone flake in our climate."},{"question":"Is it slippery after rain?","answer":"Polished — yes, which is why we do not lay it outdoors. Flamed, bush-hammered and sawn granite are slip-resistant when wet."},{"question":"How to lay it?","answer":"30–40 mm slabs on compacted crushed stone and screenings like paving, 20 mm on concrete and adhesive. Kerbs and steps on a concrete bed."},{"question":"How to clean it?","answer":"With a pressure washer twice a year. Moss washes off, salt does not harm granite, sealing is not needed."}]},"lt":{"title":"Kraštovaizdžio akmuo kiemui: rūšys ir pritaikymas","h1":"Kraštovaizdžio akmuo — kaip rinktis kiemui ir sodui","description":"Kraštovaizdžio akmuo kiemui: plokštės takams, atraminės sienos, bortai, gėlynai. Atsparumas šalčiui, neslidi apdaila, derinimas su grindiniu ir fasadu.","dek":"Akmuo takams, gėlynams, atraminėms sienoms ir dekoratyvinėms zonoms.","intro":"Sode akmuo dirba kitaip nei namuose: čia nėra karštų indų, bet yra šaltis, vanduo, šaknys ir vejapjovė. Kraštovaizdžio akmuo renkamas ne pagal grožį ant plokštės, o pagal funkciją: kuo vaikščioti, ką laikyti, ką pabrėžti. Pasakojame, kokius granito gaminius darome kiemams ir kaip jie derinasi su grindiniu ir fasadu.","sections":[{"heading":"Kokį akmenį kraštovaizdžiui rinktis?","body":"Granitas išsprendžia visas kiemo užduotis: plokštės takams ir terasoms, bortai, laiptai, atraminės sienos, gėlynų ir tvenkinių apdaila. Jis atsparus šalčiui, nebijo vandens ir druskos, o degintas paviršius neslidus. Smiltainis ir klintis minkštesni ir porėtesni, mūsų klimate lupasi po kelių žiemų.\n\nDekoratyvinėms zonoms tinka skaldytas akmuo iš gamybos atliekų: skalda sausoms sienelėms, apvalūs akmenys gėlynams. Tai prieinamas būdas gauti natūralią faktūrą, ir siūlome jį kartu su pagrindiniais gaminiais."},{"heading":"Kokios rūšys naudojamos kieme?","body":"Plokštės takams ir terasoms: 30–40 mm klojimui ant skaldos ir smėlio, 20 mm ant betoninio pagrindo, formatas nuo 300 × 300 iki 600 × 900 mm, deginta arba pjauta apdaila. Pakopos ir sodo laiptai: masyvūs blokai arba uždedamos 30–40 mm pakopos ant betono.\n\nAtraminės sienos: granito blokai 200–400 mm arba apdailos plokštės ant betoninio branduolio. Bortai: pjauti arba skaldyti 80–150 mm aukščio, laiko takus ir veją. Apdaila: gėlynai, dubenys, tvenkiniai, lauko virtuvės, suolai ir stalviršiai kepsninei iš deginto granito."},{"heading":"Kaip derinti akmenį su grindiniu ir fasadu?","body":"Viena taisyklė: ne daugiau dviejų uolienų kieme. Pavyzdžiui, Grey Ukraine grindinyje ir terasų plokštėse plius Kometa Black bortuose, laiptuose ir akcentinėse juostose. Jei fasadas ar cokolis iš akmens, kraštovaizdis tęsia jo uolieną.\n\nApdailas derinkite pagal funkciją: poliruota tik vertikalėse ir akcentuose, deginta visur, kur vaikštoma. Modulių matmenis verta derinti kartotinius grindiniui (100 mm), kad plokščių takas ir grindinio įvažiavimas jungtųsi be papjovimo."},{"heading":"Kaip prižiūrėti kraštovaizdžio akmenį?","body":"Du kartus per metus nuplauti vandeniu su slėgiu, ypač šešėlines vietas, kur auga samanos. Impregnavimo granitui lauke nereikia, smiltainiui ir klinčiai — hidrofobizatorius kartą per kelis metus.\n\nŽiemą plastikinis kastuvas ir bet kokia priemonė nuo apledėjimo, granitas jas atlaiko. Kartą per metus patikrinkite siūles tarp plokščių ir bortų ir esant reikalui papildykite. Augalus su agresyviomis šaknimis (gluosnis, tuopa, bambukas) sodinkite ne arčiau kaip 2–3 m nuo takų: šaknys kelia plokštes nepriklausomai nuo akmens rūšies."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Plokštės","Takai, terasos, kepsninės zona","Deginta neslidi apdaila"],["Skaldytas akmuo","Gėlynai, sausos sienelės, akcentai","Stabilus pagrindas, drenažas"],["Blokai","Atraminės sienos, laiptai sode","Inžinerinis skaičiavimas nuo 1 m"],["Bortai","Takų ir vejos ribos","Ant betono pagalvės"]]},"faq":[{"question":"Koks akmuo atsparus šalčiui?","answer":"Granitas, gabras ir labradoritas: vandens įgertis mažesnė nei 0,2 %, daugiau nei 300 užšalimo ciklų be pokyčių. Smiltainis ir klintis mūsų klimate lupasi."},{"question":"Ar jis slidus po lietaus?","answer":"Poliruotas — taip, todėl lauke jo neklojame. Degintas, kalstytas ir pjautas granitas neslidūs drėgni."},{"question":"Kaip kloti?","answer":"Plokštes 30–40 mm ant sutankintos skaldos ir atsijų kaip grindinį, 20 mm ant betono ir klijų. Bortus ir laiptus ant betono pagalvės."},{"question":"Kaip valyti?","answer":"Vandeniu su slėgiu du kartus per metus. Samanos nusiplauna, druska granitui nekenkia, impregnavimo nereikia."}]},"pl":{"title":"Kamień ogrodowy na podwórze: rodzaje i zastosowanie","h1":"Kamień ogrodowy — jak wybrać na podwórze i do ogrodu","description":"Kamień ogrodowy na podwórze: płyty na ścieżki, mury oporowe, krawężniki, rabaty. Mrozoodporność, wykończenie antypoślizgowe, łączenie z kostką i elewacją.","dek":"Kamień na ścieżki, rabaty, mury oporowe i strefy dekoracyjne.","intro":"W ogrodzie kamień pracuje inaczej niż w domu: nie ma tu gorących naczyń, ale jest mróz, woda, korzenie i kosiarka. Kamień ogrodowy wybiera się nie za urodę na sląbie, lecz za funkcję: po czym chodzić, co trzymać, co podkreślić. Opowiadamy, jakie wyroby z granitu robimy na podwórza i jak łączą się z kostką i elewacją.","sections":[{"heading":"Który kamień do ogrodu wybrać?","body":"Granit zamyka wszystkie zadania podwórza: płyty na ścieżki i tarasy, krawężniki, schody, mury oporowe, okładziny rabat i oczek wodnych. Jest mrozoodporny, nie boi się wody i soli, a powierzchnia płomieniowana nie jest śliska. Piaskowiec i wapień są miększe i bardziej porowate, w naszym klimacie łuszczą się po kilku zimach.\n\nDo stref dekoracyjnych nadaje się kamień łupany z odpadów produkcyjnych: łamany na suche murki, otoczaki na rabaty. To przystępny sposób na naturalną fakturę i proponujemy go razem z głównymi wyrobami."},{"heading":"Jakie rodzaje stosuje się na podwórzu?","body":"Płyty na ścieżki i tarasy: 30–40 mm do układania na tłuczniu i piasku, 20 mm na podłożu betonowym, format od 300 × 300 do 600 × 900 mm, wykończenie płomieniowane lub cięte. Stopnie i schody ogrodowe: masywne bloki lub stopnice nakładane 30–40 mm na betonie.\n\nMury oporowe: bloki granitowe 200–400 mm lub płyty okładzinowe na rdzeniu betonowym. Krawężniki: cięte lub łupane o wysokości 80–150 mm, trzymają ścieżki i trawnik. Okładziny: rabaty, misy, oczka wodne, kuchnie zewnętrzne, ławy i blaty do grilla z granitu płomieniowanego."},{"heading":"Jak połączyć kamień z kostką i elewacją?","body":"Jedna zasada: nie więcej niż dwie skały na podwórzu. Na przykład Grey Ukraine w kostce i płytach tarasów plus Kometa Black w krawężnikach, schodach i pasach akcentowych. Jeśli elewacja lub cokół są z kamienia, ogród kontynuuje jego skałę.\n\nWykończenia dobieraj według funkcji: polerowane tylko na pionach i akcentach, płomieniowane wszędzie, gdzie się chodzi. Wymiary modułów warto dopasować do kostki (100 mm), aby ścieżka z płyt i podjazd z kostki łączyły się bez docinania."},{"heading":"Jak pielęgnować kamień ogrodowy?","body":"Dwa razy w roku spłukać wodą pod ciśnieniem, zwłaszcza miejsca zacienione, gdzie rośnie mech. Impregnacja granitu na zewnątrz nie jest potrzebna, dla piaskowca i wapienia — hydrofobizacja raz na kilka lat.\n\nZimą plastikowa łopata i dowolny środek przeciwoblodzeniowy, granit je wytrzymuje. Raz w roku sprawdź spoiny między płytami i krawężnikami i w razie potrzeby dosyp. Rośliny z agresywnymi korzeniami (wierzba, topola, bambus) sadź nie bliżej niż 2–3 m od ścieżek: korzenie podnoszą płyty niezależnie od rodzaju kamienia."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Płyty","Ścieżki, tarasy, strefa grilla","Płomieniowane wykończenie antypoślizgowe"],["Kamień łupany","Rabaty, suche murki, akcenty","Stabilne podłoże, drenaż"],["Bloki","Mury oporowe, schody w ogrodzie","Obliczenia inżynierskie od 1 m"],["Krawężniki","Granice ścieżek i trawnika","Na ławie betonowej"]]},"faq":[{"question":"Który kamień jest mrozoodporny?","answer":"Granit, gabro i labradoryt: nasiąkliwość poniżej 0,2 %, ponad 300 cykli zamrażania bez zmian. Piaskowiec i wapień w naszym klimacie łuszczą się."},{"question":"Czy jest śliski po deszczu?","answer":"Polerowany — tak, dlatego na zewnątrz go nie układamy. Płomieniowany, groszkowany i cięty granit są antypoślizgowe na mokro."},{"question":"Jak układać?","answer":"Płyty 30–40 mm na zagęszczony tłuczeń i grys jak kostkę, 20 mm na beton i klej. Krawężniki i schody na ławie betonowej."},{"question":"Jak czyścić?","answer":"Wodą pod ciśnieniem dwa razy w roku. Mech się zmywa, sól granitowi nie szkodzi, impregnacja nie jest potrzebna."}]}}'::jsonb) where slug = 'landshaftnyy-kamin-dvir';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Was kostet eine Steinarbeitsplatte: Wovon der Preis abhängt","h1":"Wovon die Kosten einer Steinarbeitsplatte abhängen","description":"Kosten einer Steinarbeitsplatte: Material, Fläche und Zuschnitt, Dicke, Kante, Ausschnitte, Verstärkung, Lieferung und Montage. Wie man eine genaue Kalkulation erhält.","dek":"Die Faktoren des Kostenvoranschlags ohne irreführende Einheitspreise.","intro":"„Was kostet eine Steinarbeitsplatte pro Meter?“ ist die häufigste Frage, und es gibt darauf keine ehrliche kurze Antwort. Zwei Platten gleicher Länge aus demselben Stein können sich durch Zuschnitt, Ausschnitte und Kante im Preis um das Doppelte unterscheiden. Wir erklären, woraus sich der Kostenvoranschlag zusammensetzt, in welcher Reihenfolge die Faktoren die Summe beeinflussen und wie man innerhalb eines Tages eine genaue Zahl bekommt.","sections":[{"heading":"Was kostet eine Steinarbeitsplatte?","body":"Der Kostenvoranschlag besteht aus vier Teilen: Material (Platte oder Teil davon), Bearbeitung (Zuschnitt, Kante, Ausschnitte, Polieren der Kanten), Zusatzelemente (Spritzschutz, Verstärkung, verleimte Kante) und Logistik mit Montage.\n\nDas Material macht meist 40 bis 60 % der Summe aus, die Bearbeitung 25–40 %, der Rest entfällt auf Lieferung und Montage. Deshalb führt die Frage „pro Meter“ in die Irre: Ein Preis pro laufenden Meter Stein lässt die Hälfte der Arbeiten außer Acht. Einen Richtwert für konkrete Maße gibt der Rechner auf der Website, er rechnet genau nach dieser Logik."},{"heading":"Welche Faktoren beeinflussen den Preis?","body":"Material: Gestein, Marke, Seltenheit der Farbe. Fläche und Zuschnitt: Wir bezahlen die ganze Platte, deshalb ist wichtig, wie viele Platten nötig sind und wie die Teile darauf liegen; eine Arbeitsplatte von 3,1 m kann zwei Platten statt einer erfordern.\n\nDicke: 30 mm sind teurer als 20 mm, im Material wie in der Bearbeitung. Kante: Gerade Kante ist Basis, Fase und Rundung etwas teurer, Ogee, Wasserfall und verleimte Kante 40–60 mm deutlich teurer. Ausschnitte: Jeder Ausschnitt für Spüle, Kochfeld, Armatur oder Steckdose bedeutet Mehrarbeit, und eine Unterbauspüle erfordert das Polieren des Innenumfangs.\n\nMontage: Stockwerk, Aufzug, Länge der Teile, Stöße vor Ort, Verstärkung von Überständen. Eine Arbeitsplatte in den fünften Stock ohne Aufzug kostet mehr als dieselbe im Erdgeschoss."},{"heading":"Wie beeinflusst das Material die Kosten?","body":"Grob teilen sich die Katalogmaterialien in drei Stufen. Basis: ukrainische Granite Grey Ukraine, Maple Red, Rosso Santiago und Feinsteinzeug in Standarddekoren. Mittel: Gabbro, Labradorit, Markenquarz Vicostone und Caesarstone aus den Basiskollektionen. Premium: Marmor, Quarzit Taj Mahal, Quarz in Calacatta-Optik, Dekton und Neolith.\n\nInnerhalb einer Stufe ist der Preisunterschied gering, zwischen den Stufen spürbar. Noch eine Nuance: Helle gleichmäßige Materialien sind in der Regel teurer als dunkle mit Zeichnung, weil sie schwerer fehlerfrei herzustellen sind. Die „ab“-Preise jeder Kollektion stehen auf ihrer Katalogseite."},{"heading":"Wie bekommt man schnell eine genaue Kalkulation?","body":"Schritt eins: Der Rechner auf der Website mit Maßen, Produkttyp und Material gibt in einer Minute einen Richtwert. Schritt zwei: Senden Sie uns den Küchenplan oder ein Foto mit Maßen, und wir berechnen Zuschnitt und vollständigen Kostenvoranschlag innerhalb eines Tages. Schritt drei: Das Aufmaß vor Ort nach Aufstellung der Möbel legt die Endsumme fest, die sich dann nicht mehr ändert.\n\nUm nicht zu viel zu zahlen, überlegen Sie vor dem Aufmaß drei Dinge: ob eine verleimte Kante nötig ist, ob die Fuge an eine unauffällige Stelle verlegt werden kann und ob ein Steinspritzschutz über die ganze Länge oder nur hinter dem Kochfeld gebraucht wird."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Material","40–60 % des Kostenvoranschlags","Gesteinsstufe und Anzahl der Platten"],["Zuschnitt und Dicke","Hoher Einfluss","Länge über 3 m = zweite Platte"],["Kante und Ausschnitte","Mittel oder hoch","Verleimte Kante und Unterbauspüle teurer"],["Lieferung und Montage","10–20 %","Stockwerk, Aufzug, Stöße vor Ort"]]},"faq":[{"question":"Was ist teurer — Granit oder Quarz?","answer":"Ukrainische Granite sind meist günstiger als Markenquarz. Importierter Granit in seltenen Farben und Quarz aus Premiumkollektionen kosten etwa gleich viel."},{"question":"Ist die Montage enthalten?","answer":"Im Kostenvoranschlag ist die Montage eine eigene Position, ebenso die Lieferung. So sehen Sie, wofür Sie zahlen, und können auf Wunsch nur die Fertigung bestellen."},{"question":"Wie rechne ich selbst?","answer":"Der Rechner auf der Website rechnet nach Maßen, Produkttyp, Material, Kante und Anzahl der Ausschnitte. Das ist ein Richtwert mit etwa ±15 % Genauigkeit, den Rest präzisiert der Zuschnitt."},{"question":"Was beeinflusst am meisten?","answer":"Material und Anzahl der Platten. Dann Kante und Ausschnitte. 30 mm Dicke statt 20 mm bringen 20–40 % dazu."}]},"en":{"title":"How much does a stone countertop cost: what the price depends on","h1":"What the cost of a stone countertop depends on","description":"The cost of a stone countertop: material, area and cutting, thickness, edge, cut-outs, reinforcement, delivery and installation. How to get an exact estimate.","dek":"The factors of the estimate without misleading universal prices.","intro":"“How much does a stone countertop cost per metre?” is the most common question, and there is no honest short answer. Two countertops of the same length in the same stone can differ in price twofold because of cutting, cut-outs and the edge. We explain what the estimate consists of, in what order the factors affect the sum and how to get an exact figure within a day.","sections":[{"heading":"How much does a stone countertop cost?","body":"The estimate consists of four parts: material (a slab or part of it), fabrication (cutting, edge, cut-outs, polishing of edges), extra elements (splashback, reinforcement, laminated edge) and logistics with installation.\n\nMaterial usually makes up 40 to 60 % of the sum, fabrication 25–40 %, the rest is delivery and installation. That is why the question “per metre” misleads: a price per linear metre of stone ignores half the work. A guide for specific dimensions is given by the calculator on the site; it works by exactly this logic."},{"heading":"Which factors affect the price?","body":"Material: stone, brand, rarity of colour. Area and cutting: we pay for the whole slab, so it matters how many slabs are needed and how the parts fit on them; a 3.1 m countertop may need two slabs instead of one.\n\nThickness: 30 mm is more expensive than 20 mm in both material and fabrication. Edge: a straight edge is basic, bevel and rounding slightly more, ogee, waterfall and a 40–60 mm laminated edge considerably more. Cut-outs: every cut-out for a sink, hob, tap or socket adds work, and an undermount sink needs the inner perimeter polished.\n\nInstallation: floor, lift, length of parts, joints on site, reinforcement of overhangs. A countertop for the fifth floor without a lift costs more than the same one on the ground floor."},{"heading":"How does the material affect the cost?","body":"Roughly, the catalogue materials fall into three tiers. Base: Ukrainian granites Grey Ukraine, Maple Red, Rosso Santiago and porcelain in standard decors. Mid: gabbro, labradorite, branded Vicostone and Caesarstone quartz from the base collections. Premium: marble, Taj Mahal quartzite, Calacatta-look quartz collections, Dekton and Neolith.\n\nWithin one tier the price difference is small, between tiers it is noticeable. One more nuance: light uniform materials are usually more expensive than dark patterned ones, because they are harder to produce without flaws. The “from” prices for each collection are shown on its catalogue page."},{"heading":"How to get an exact estimate quickly?","body":"Step one: the calculator on the site with dimensions, product type and material gives a guide within a minute. Step two: send us the kitchen plan or a photo with dimensions, and we calculate the cutting and the full estimate within a day. Step three: measurement on site after the furniture is installed fixes the final sum, which no longer changes.\n\nTo avoid overpaying, think about three things before the measurement: whether a laminated edge is needed, whether the joint can be moved to where it is not visible, and whether a stone splashback is needed along the whole length or only behind the hob."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Material","40–60 % of the estimate","Stone tier and number of slabs"],["Cutting and thickness","High impact","Length over 3 m = a second slab"],["Edge and cut-outs","Medium or high","Laminated edge and undermount sink cost more"],["Delivery and installation","10–20 %","Floor, lift, joints on site"]]},"faq":[{"question":"Which is more expensive — granite or quartz?","answer":"Ukrainian granites are usually more affordable than branded quartz. Imported granite in rare colours and premium quartz collections cost about the same."},{"question":"Is installation included?","answer":"In the estimate installation is a separate line, as is delivery. This lets you see what you pay for and, if you wish, order fabrication only."},{"question":"How to calculate it myself?","answer":"The calculator on the site works from dimensions, product type, material, edge and number of cut-outs. It is a guide with an accuracy of about ±15 %; the cutting layout refines the rest."},{"question":"What affects it most?","answer":"Material and the number of slabs. Then edge and cut-outs. 30 mm thickness instead of 20 mm adds 20–40 %."}]},"lt":{"title":"Kiek kainuoja akmens stalviršis: nuo ko priklauso kaina","h1":"Nuo ko priklauso akmens stalviršio kaina","description":"Akmens stalviršio kaina: medžiaga, plotas ir pjaustymas, storis, kraštas, išpjovos, sustiprinimas, pristatymas ir montavimas. Kaip gauti tikslų skaičiavimą.","dek":"Sąmatos faktoriai be klaidinančių universalių kainų.","intro":"„Kiek kainuoja akmens stalviršis už metrą?“ — dažniausias klausimas, ir sąžiningo trumpo atsakymo į jį nėra. Du vienodo ilgio stalviršiai iš to paties akmens gali skirtis kaina dvigubai dėl pjaustymo, išpjovų ir krašto. Paaiškiname, iš ko susideda sąmata, kokia tvarka faktoriai veikia sumą ir kaip gauti tikslų skaičių per vieną dieną.","sections":[{"heading":"Kiek kainuoja akmens stalviršis?","body":"Sąmata susideda iš keturių dalių: medžiaga (plokštė arba jos dalis), apdirbimas (pjaustymas, kraštas, išpjovos, kraštų poliravimas), papildomi elementai (sienelė, sustiprinimas, suklijuotas kraštas) ir logistika su montavimu.\n\nMedžiaga paprastai sudaro 40–60 % sumos, apdirbimas 25–40 %, likusi dalis — pristatymas ir montavimas. Todėl klausimas „už metrą“ klaidina: akmens metro kaina neapima pusės darbų. Orientyrą konkretiems matmenims duoda skaičiuoklė svetainėje, ji skaičiuoja būtent pagal šią logiką."},{"heading":"Kokie faktoriai veikia kainą?","body":"Medžiaga: uoliena, prekės ženklas, spalvos retumas. Plotas ir pjaustymas: mokame už visą plokštę, todėl svarbu, kiek plokščių reikia ir kaip detalės ant jų išsidėsto; 3,1 m stalviršiui gali reikėti dviejų plokščių vietoj vienos.\n\nStoris: 30 mm brangiau nei 20 mm ir medžiagoje, ir apdirbime. Kraštas: tiesus kraštas bazinis, nuožulna ir suapvalinimas kiek brangesni, ogee, krioklys ir suklijuotas 40–60 mm kraštas gerokai brangesni. Išpjovos: kiekviena išpjova plautuvei, kaitlentei, maišytuvui ar kištukiniam lizdui prideda darbo, o apatinio montavimo plautuvei reikia poliruoti vidinį perimetrą.\n\nMontavimas: aukštas, liftas, detalių ilgis, sujungimai vietoje, iškyšų sustiprinimas. Stalviršis į penktą aukštą be lifto kainuoja brangiau nei tas pats pirmame."},{"heading":"Kaip medžiaga veikia kainą?","body":"Sąlyginai katalogo medžiagos skirstomos į tris lygius. Bazinis: ukrainietiški granitai Grey Ukraine, Maple Red, Rosso Santiago ir standartinių dekorų keraminis granitas. Vidutinis: gabras, labradoritas, firminis kvarcas Vicostone ir Caesarstone bazinių kolekcijų. Premium: marmuras, kvarcitas Taj Mahal, „Calacatta“ tipo kvarco kolekcijos, Dekton ir Neolith.\n\nViename lygyje kainų skirtumas nedidelis, tarp lygių — juntamas. Dar vienas niuansas: šviesios vienalytės medžiagos, kaip taisyklė, brangesnės už tamsias su raštu, nes jas sunkiau pagaminti be defektų. Kainos „nuo“ kiekvienai kolekcijai nurodytos jos puslapyje kataloge."},{"heading":"Kaip greitai gauti tikslų skaičiavimą?","body":"Pirmas žingsnis: skaičiuoklė svetainėje su matmenimis, gaminio tipu ir medžiaga duoda orientyrą per minutę. Antras žingsnis: atsiųskite mums virtuvės planą ar nuotrauką su matmenimis, ir apskaičiuosime pjaustymą ir pilną sąmatą per dieną. Trečias žingsnis: išmatavimas objekte po baldų sustatymo fiksuoja galutinę sumą, kuri jau nesikeičia.\n\nKad nepermokėtumėte, prieš matavimą apgalvokite tris dalykus: ar reikia suklijuoto krašto, ar galima perkelti siūlę į nematomą vietą, ir ar reikia akmens sienelės per visą ilgį, ar tik už kaitlentės."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Medžiaga","40–60 % sąmatos","Uolienos lygis ir plokščių skaičius"],["Pjaustymas ir storis","Didelė įtaka","Ilgis virš 3 m = antra plokštė"],["Kraštas ir išpjovos","Vidutinė arba didelė","Suklijuotas kraštas ir apatinė plautuvė brangesni"],["Pristatymas ir montavimas","10–20 %","Aukštas, liftas, sujungimai vietoje"]]},"faq":[{"question":"Kas brangiau — granitas ar kvarcas?","answer":"Ukrainietiški granitai paprastai prieinamesni už firminį kvarcą. Importuotas retų spalvų granitas ir premium kolekcijų kvarcas kainuoja maždaug vienodai."},{"question":"Ar montavimas įskaičiuotas?","answer":"Sąmatoje montavimas — atskira eilutė, kaip ir pristatymas. Tai leidžia matyti, už ką mokate, ir norint užsakyti tik gamybą."},{"question":"Kaip apskaičiuoti pačiam?","answer":"Skaičiuoklė svetainėje skaičiuoja pagal matmenis, gaminio tipą, medžiagą, kraštą ir išpjovų skaičių. Tai orientyras su maždaug ±15 % tikslumu, likusią dalį patikslina pjaustymo planas."},{"question":"Kas veikia labiausiai?","answer":"Medžiaga ir plokščių skaičius. Toliau kraštas ir išpjovos. 30 mm storis vietoj 20 mm prideda 20–40 %."}]},"pl":{"title":"Ile kosztuje blat z kamienia: od czego zależy cena","h1":"Od czego zależy koszt blatu z kamienia","description":"Koszt blatu z kamienia: materiał, powierzchnia i rozkrój, grubość, krawędź, wycięcia, wzmocnienia, dostawa i montaż. Jak uzyskać dokładną kalkulację.","dek":"Czynniki kosztorysu bez mylących uniwersalnych cen.","intro":"„Ile kosztuje blat z kamienia za metr?” — to najczęstsze pytanie i nie ma na nie uczciwej krótkiej odpowiedzi. Dwa blaty tej samej długości z tego samego kamienia mogą różnić się ceną dwukrotnie przez rozkrój, wycięcia i krawędź. Wyjaśniamy, z czego składa się kosztorys, w jakiej kolejności czynniki wpływają na kwotę i jak uzyskać dokładną liczbę w jeden dzień.","sections":[{"heading":"Ile kosztuje blat z kamienia?","body":"Kosztorys składa się z czterech części: materiał (sląb lub jego część), obróbka (rozkrój, krawędź, wycięcia, polerowanie krawędzi), elementy dodatkowe (fartuch, wzmocnienie, klejona krawędź) oraz logistyka z montażem.\n\nMateriał stanowi zwykle od 40 do 60 % kwoty, obróbka 25–40 %, reszta to dostawa i montaż. Dlatego pytanie „za metr” wprowadza w błąd: cennik za metr bieżący kamienia nie uwzględnia połowy prac. Orientację dla konkretnych wymiarów daje kalkulator na stronie, liczy właśnie według tej logiki."},{"heading":"Jakie czynniki wpływają na cenę?","body":"Materiał: skała, marka, rzadkość koloru. Powierzchnia i rozkrój: płacimy za cały sląb, dlatego ważne jest, ile płyt jest potrzebnych i jak detale na nie wchodzą; blat 3,1 m może wymagać dwóch sląbów zamiast jednego.\n\nGrubość: 30 mm jest droższe od 20 mm i w materiale, i w obróbce. Krawędź: prosta jest bazowa, faza i zaokrąglenie nieco droższe, ogee, wodospad i klejona krawędź 40–60 mm znacznie droższe. Wycięcia: każde wycięcie pod zlew, płytę grzewczą, baterię lub gniazdko dodaje pracy, a zlew podwieszany wymaga polerowania wewnętrznego obwodu.\n\nMontaż: piętro, winda, długość detali, łączenia na miejscu, wzmocnienie nawisów. Blat na piąte piętro bez windy kosztuje więcej niż ten sam na parterze."},{"heading":"Jak materiał wpływa na koszt?","body":"Umownie materiały katalogu dzielą się na trzy poziomy. Podstawowy: ukraińskie granity Grey Ukraine, Maple Red, Rosso Santiago i gres w standardowych dekorach. Średni: gabro, labradoryt, markowy kwarc Vicostone i Caesarstone z kolekcji podstawowych. Premium: marmur, kwarcyt Taj Mahal, kwarc z kolekcji „pod Calacattę”, Dekton i Neolith.\n\nW obrębie jednego poziomu różnica w cenie jest niewielka, między poziomami odczuwalna. Jeszcze jeden niuans: jasne jednolite materiały są z reguły droższe od ciemnych z rysunkiem, bo trudniej wyprodukować je bez wad. Ceny „od” dla każdej kolekcji są podane na jej stronie w katalogu."},{"heading":"Jak szybko uzyskać dokładną kalkulację?","body":"Krok pierwszy: kalkulator na stronie z wymiarami, typem wyrobu i materiałem daje orientację w minutę. Krok drugi: prześlij nam plan kuchni lub zdjęcie z wymiarami, a policzymy rozkrój i pełny kosztorys w jeden dzień. Krok trzeci: pomiar na obiekcie po ustawieniu mebli ustala ostateczną kwotę, która już się nie zmienia.\n\nAby nie przepłacać, przemyśl przed pomiarem trzy rzeczy: czy potrzebna jest klejona krawędź, czy można przenieść spoinę w miejsce, gdzie jest niewidoczna, i czy potrzebny jest kamienny fartuch na całej długości, czy tylko za płytą."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Materiał","40–60 % kosztorysu","Poziom skały i liczba sląbów"],["Rozkrój i grubość","Wysoki wpływ","Długość powyżej 3 m = drugi sląb"],["Krawędź i wycięcia","Średni lub wysoki","Klejona krawędź i zlew podwieszany droższe"],["Dostawa i montaż","10–20 %","Piętro, winda, łączenia na miejscu"]]},"faq":[{"question":"Co droższe — granit czy kwarc?","answer":"Ukraińskie granity są zwykle tańsze od markowego kwarcu. Importowany granit w rzadkich kolorach i kwarc z kolekcji premium kosztują mniej więcej tyle samo."},{"question":"Czy montaż jest wliczony?","answer":"W kosztorysie montaż jest osobną pozycją, jak i dostawa. Pozwala to widzieć, za co płacisz, i na życzenie zamówić samo wykonanie."},{"question":"Jak policzyć samodzielnie?","answer":"Kalkulator na stronie liczy według wymiarów, typu wyrobu, materiału, krawędzi i liczby wycięć. To orientacja z dokładnością około ±15 %, resztę precyzuje rozkrój."},{"question":"Co wpływa najbardziej?","answer":"Materiał i liczba sląbów. Dalej krawędź i wycięcia. Grubość 30 mm zamiast 20 mm dodaje 20–40 %."}]}}'::jsonb) where slug = 'skilky-koshtue-stilnytsia-z-kamenyu';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Was eine Rohplatte ist und wo sie verwendet wird","h1":"Rohplatte — was das ist, Maße und Anwendung","description":"Eine Rohplatte (Slab) ist eine große Platte aus Natur- oder Kunststein. Plattenmaße von Granit, Marmor, Quarz und Feinsteinzeug, Dicke, Auswahl und was ein Reststück ist.","dek":"Wie man die ganze Platte, Charge, Ton und Nutzfläche liest.","intro":"Eine Rohplatte (englisch slab) ist eine große Steinplatte, die aus dem Block gesägt und einseitig poliert wurde. Aus Rohplatten werden Arbeitsplatten, Fensterbänke, Treppen und Verkleidungen geschnitten, und genau die Platte, nicht ein Muster von 10 × 10 cm, sollte man vor der Bestellung ansehen. Wir erklären, welche Platten es gibt, welche Maße sie haben und wie daraus Ihre Arbeitsplatte entsteht.","sections":[{"heading":"Was ist eine Rohplatte?","body":"Im Steinbruch wird der Stein in Blöcken von 10–30 Tonnen gewonnen. Der Block wird auf Seil- oder Scheibensägen in Platten von 20 oder 30 mm Dicke gesägt, dann wird die Sichtseite geschliffen und poliert. Die fertige Platte ist die Rohplatte: Bei Naturstein bestimmt der Block das Maß, bei Quarz und Feinsteinzeug das Werksformat.\n\nJede Platte hat eine Nummer, eine Charge und tatsächliche Maße, Natursteine zudem eine individuelle Zeichnung. Deshalb zeigen wir im Katalog nicht „grauen Granit“, sondern konkrete Platten mit Foto, Maßen und Verfügbarkeit."},{"heading":"Welche Platten aus Granit, Marmor und Quarzit gibt es?","body":"Granit: die größte Gruppe, ukrainisch und importiert, Dicke 20 und 30 mm, Oberfläche poliert, matt, geflammt oder Leather. Marmor: Import aus Italien, Spanien, Türkei, Dicke 20 und 30 mm, wegen der Sprödigkeit oft mit Armierungsgewebe auf der Rückseite. Quarzit: Brasilien und Indien, Dicke 20 und 30 mm, die härtesten und teuersten unter den Natursteinen.\n\nQuarz (Komposit): Werksplatten in Standardformat, Dicke 20 und 30 mm, gleichmäßige Farbe. Feinsteinzeug: 6, 12 und 20 mm, Format bis 3200 × 1600 mm, je nach Kollektion nur mit Dekor auf der Oberfläche oder durchgefärbt."},{"heading":"Welche Standardmaße hat eine Rohplatte?","body":"Granit und Marmor: von 2400 × 1200 bis 3200 × 1900 mm, meist etwa 2800 × 1600 mm. Das Maß hängt von Block und Gestein ab: Ukrainische Granite meist 2400–3000 × 1200–1500 mm. Quarz: Standard 3050 × 1400 mm, Jumbo-Format 3200 × 1600 mm in Premiumkollektionen.\n\nFeinsteinzeug: Laminam 3240 × 1620 mm, Neolith 3200 × 1600 mm, Dekton 3200 × 1440 mm. Die Nutzfläche ist immer kleiner als das Außenmaß: Die Plattenränder haben einen Rand von 20–50 mm mit Sägefehlern, und Naturstein kann Risse oder Einschlüsse haben, die wir beim Zuschnitt umgehen."},{"heading":"Wo werden Rohplatten verwendet?","body":"Arbeitsplatten und Inseln: aus Granit, Quarz, Quarzit und Feinsteinzeug. Fensterbänke und Treppen: aus Granit, Marmor. Verkleidung von Wänden, Kaminen und Fassaden: aus jedem Stein in großformatigen Platten, wenn eine „fugenlose“ Zeichnung oder Bookmatch, die spiegelnde Kombination zweier benachbarter Platten, gewünscht ist.\n\nPlattenreste nach dem Zuschnitt sind eine eigene Kategorie: Stücke von 0,5–1,5 m, aus denen Fensterbänke, Tischchen, Regale und kleine Arbeitsplatten zu niedrigerem Preis entstehen. Bei uns sind sie auf der Seite der Reststücke mit Maßen und Fotos verfügbar."}],"table":{"headers":["Kriterium","Variante","Zu beachten"],"rows":[["Granitplatte","Arbeitsplatten, Treppen, Verkleidung","2400–3200 × 1200–1900 mm, 20/30 mm"],["Marmorplatte","Bäder, Fensterbänke, Portale","Oft mit Gewebe auf der Rückseite"],["Quarzitplatte","Arbeitsplatten und Inseln","Am härtesten, bis 3 × 1,8 m"],["Quarzplatte","Arbeitsplatten in gleichmäßiger Farbe","3050 × 1400 oder 3200 × 1600 mm"],["Feinsteinzeug","Arbeitsplatten, Fassaden, Spritzschutz","3200 × 1600 mm, 6–20 mm"]]},"faq":[{"question":"Worin unterscheidet sich eine Rohplatte von einer Fliese?","answer":"In der Größe und in dem, was daraus gemacht wird. Eine Fliese ist ein fertiges Modul bis 1200 mm zum Verlegen auf Kleber. Eine Rohplatte ist ein Rohling bis 3,2 m, aus dem das Stück auf Ihr Maß geschnitten wird."},{"question":"Welche Maße hat eine Rohplatte?","answer":"Naturstein von 2,4 × 1,2 bis 3,2 × 1,9 m, Quarz 3,05 × 1,4 oder 3,2 × 1,6 m, Feinsteinzeug 3,2 × 1,6 m. Die genauen Maße sind im Katalog für jede Platte angegeben."},{"question":"Was kostet sie?","answer":"Eine Rohplatte wird pro Quadratmeter mit einem Faktor für die ganze Platte verkauft. Der Preis hängt von Gestein, Dicke und Charge ab; im Katalog steht der Preis konkreter vorrätiger Platten."},{"question":"Wie wählt man eine Rohplatte?","answer":"Die ganze Platte bei Tageslicht ansehen, nicht ein Muster: Zeichnung, Risse, Einschlüsse prüfen, die Aufteilung der Teile auf der Platte abstimmen. Wir senden Foto und Video der Platte und halten sie bis zum Zuschnitt für Sie fest."}]},"en":{"title":"What a slab is and where it is used","h1":"Slab — what it is, sizes and uses","description":"A slab is a large sheet of natural or engineered stone. Slab sizes for granite, marble, quartz and porcelain, thickness, how to choose and what a remnant is.","dek":"How to read the whole sheet, batch, tone and usable area.","intro":"A slab is a large sheet of stone sawn from a block and polished on one side. It is from slabs that countertops, window sills, stairs and cladding are cut, and it is the slab, not a 10 × 10 cm sample, that you need to look at before ordering. We explain what kinds of slabs there are, their sizes and how your countertop comes out of them.","sections":[{"heading":"What is a slab?","body":"At the quarry stone is extracted in blocks weighing 10–30 tonnes. The block is sawn into sheets 20 or 30 mm thick on wire or disc saws, then the face is ground and polished. The finished sheet is the slab: in natural stone the size is set by the block, in quartz and porcelain by the factory format.\n\nEvery slab has a number, a batch and actual dimensions, and natural stones also an individual pattern. That is why in the catalogue we show not “grey granite” but specific slabs with photos, dimensions and availability status."},{"heading":"What kinds of granite, marble and quartzite slabs are there?","body":"Granite: the largest group, Ukrainian and imported, 20 and 30 mm thick, polished, honed, flamed or leather finish. Marble: imported from Italy, Spain, Turkey, 20 and 30 mm thick, often with a reinforcing mesh on the back because of brittleness. Quartzite: Brazil and India, 20 and 30 mm thick, the hardest and most expensive of the natural stones.\n\nQuartz (engineered): factory sheets of standard format, 20 and 30 mm thick, uniform colour. Porcelain: 6, 12 and 20 mm, format up to 3200 × 1600 mm, with a decor only on the surface or through-body depending on the collection."},{"heading":"What standard sizes does a slab have?","body":"Granite and marble: from 2400 × 1200 to 3200 × 1900 mm, most often about 2800 × 1600 mm. The size depends on the block and the stone: Ukrainian granites are usually 2400–3000 × 1200–1500 mm. Quartz: standard 3050 × 1400 mm, Jumbo format 3200 × 1600 mm in premium collections.\n\nPorcelain: Laminam 3240 × 1620 mm, Neolith 3200 × 1600 mm, Dekton 3200 × 1440 mm. The usable area is always smaller than the overall size: the edges of the sheet have a 20–50 mm margin with sawing defects, and natural stone may have cracks or inclusions that we avoid when cutting."},{"heading":"Where are slabs used?","body":"Countertops and islands: from granite, quartz, quartzite and porcelain. Window sills and stairs: from granite, marble. Cladding of walls, fireplaces and facades: from any stone in large-format sheets when a “seamless” pattern or bookmatch, the mirror pairing of two adjacent slabs, is wanted.\n\nSlab remnants after cutting are a separate category: 0.5–1.5 m pieces that become window sills, small tables, shelves and small countertops at a lower price. Ours are available on the remnants page with dimensions and photos."}],"table":{"headers":["Criterion","Option","What to consider"],"rows":[["Granite slab","Countertops, stairs, cladding","2400–3200 × 1200–1900 mm, 20/30 mm"],["Marble slab","Bathrooms, sills, surrounds","Often with mesh on the back"],["Quartzite slab","Countertops and islands","The hardest, up to 3 × 1.8 m"],["Quartz slab","Uniform-colour countertops","3050 × 1400 or 3200 × 1600 mm"],["Porcelain","Countertops, facades, splashbacks","3200 × 1600 mm, 6–20 mm"]]},"faq":[{"question":"How does a slab differ from a tile?","answer":"In size and in what is made from it. A tile is a finished module up to 1200 mm to be laid on adhesive. A slab is a blank up to 3.2 m from which the piece is cut to your size."},{"question":"What sizes does a slab have?","answer":"Natural stone from 2.4 × 1.2 to 3.2 × 1.9 m, quartz 3.05 × 1.4 or 3.2 × 1.6 m, porcelain 3.2 × 1.6 m. Exact dimensions are given for each sheet in the catalogue."},{"question":"How much does it cost?","answer":"A slab is sold per square metre with a factor for the whole sheet. The price depends on the stone, thickness and batch; the catalogue shows the price of specific slabs in stock."},{"question":"How to choose a slab?","answer":"Look at the whole sheet in daylight, not a sample: check the pattern, cracks, inclusions, agree the layout of the parts on the sheet. We send photos and video of the slab and hold it for you until cutting."}]},"lt":{"title":"Kas yra plokštė (slab) ir kur ji naudojama","h1":"Plokštė (slab) — kas tai, matmenys ir pritaikymas","description":"Plokštė (slab) — didelė natūralaus ar inžinerinio akmens plokštė. Granito, marmuro, kvarco ir keraminio granito plokščių matmenys, storis, kaip rinktis ir kas yra likutis.","dek":"Kaip skaityti visą plokštę, partiją, toną ir naudingą plotą.","intro":"Plokštė (nuo angliško slab) — tai didelė akmens plokštė, išpjauta iš bloko ir nupoliruota iš vienos pusės. Būtent iš plokščių pjaunami stalviršiai, palangės, laiptai ir apdaila, ir būtent plokštę, o ne 10 × 10 cm pavyzdį, reikia žiūrėti prieš užsakant. Paaiškiname, kokios būna plokštės, kokie jų matmenys ir kaip iš jų gaunasi jūsų stalviršis.","sections":[{"heading":"Kas yra plokštė?","body":"Karjere akmuo kasamas 10–30 tonų blokais. Blokas pjaunamas į 20 arba 30 mm storio plokštes lyninėmis arba diskinėmis staklėmis, paskui šlifuojama ir poliruojama priekinė pusė. Gatava plokštė ir yra slab: natūralaus akmens dydį lemia blokas, kvarco ir keraminio granito — gamyklos formatas.\n\nKiekviena plokštė turi numerį, partiją ir faktinius matmenis, o natūralūs akmenys — dar ir individualų raštą. Todėl kataloge rodome ne „pilką granitą“, o konkrečias plokštes su nuotraukomis, matmenimis ir prieinamumo būsena."},{"heading":"Kokios būna granito, marmuro ir kvarcito plokštės?","body":"Granito: didžiausia grupė, ukrainietiškos ir importuotos, storis 20 ir 30 mm, apdaila poliruota, matinė, deginta arba leather. Marmuro: importas iš Italijos, Ispanijos, Turkijos, storis 20 ir 30 mm, dažnai su armuojančiu tinkleliu kitoje pusėje dėl trapumo. Kvarcito: Brazilija ir Indija, storis 20 ir 30 mm, kiečiausios ir brangiausios iš natūralių.\n\nKvarco (aglomeratas): gamyklinės standartinio formato plokštės, storis 20 ir 30 mm, vienalytė spalva. Keraminio granito: 6, 12 ir 20 mm, formatas iki 3200 × 1600 mm, su dekoru tik paviršiuje arba su pilnu prasidažymu priklausomai nuo kolekcijos."},{"heading":"Kokie standartiniai plokštės matmenys?","body":"Granitas ir marmuras: nuo 2400 × 1200 iki 3200 × 1900 mm, dažniausiai apie 2800 × 1600 mm. Dydis priklauso nuo bloko ir uolienos: ukrainietiški granitai paprastai 2400–3000 × 1200–1500 mm. Kvarcas: standartas 3050 × 1400 mm, Jumbo formatas 3200 × 1600 mm premium kolekcijose.\n\nKeraminis granitas: Laminam 3240 × 1620 mm, Neolith 3200 × 1600 mm, Dekton 3200 × 1440 mm. Naudingas plotas visada mažesnis už gabaritą: plokštės kraštai turi 20–50 mm atstumą su pjovimo defektais, o natūraliame akmenyje gali būti įtrūkimų ar intarpų, kuriuos apeiname pjaustydami."},{"heading":"Kur naudojamos plokštės?","body":"Stalviršiai ir salos: iš granito, kvarco, kvarcito ir keraminio granito. Palangės ir laiptai: iš granito, marmuro. Sienų, židinių ir fasadų apdaila: iš bet kokio akmens didelio formato plokštėmis, kai reikia „besiūlio“ rašto arba bookmatch — veidrodinio dviejų gretimų plokščių derinimo.\n\nPlokščių likučiai po pjaustymo — atskira kategorija: 0,5–1,5 m fragmentai, iš kurių išeina palangės, staliukai, lentynos ir nedideli stalviršiai už žemesnę kainą. Pas mus jie prieinami likučių puslapyje su matmenimis ir nuotraukomis."}],"table":{"headers":["Kriterijus","Variantas","Į ką atsižvelgti"],"rows":[["Granito plokštė","Stalviršiai, laiptai, apdaila","2400–3200 × 1200–1900 mm, 20/30 mm"],["Marmuro plokštė","Vonios, palangės, portalai","Dažnai su tinkleliu kitoje pusėje"],["Kvarcito plokštė","Stalviršiai ir salos","Kiečiausia, iki 3 × 1,8 m"],["Kvarco plokštė","Vienalytės spalvos stalviršiai","3050 × 1400 arba 3200 × 1600 mm"],["Keraminio granito","Stalviršiai, fasadai, sienelės","3200 × 1600 mm, 6–20 mm"]]},"faq":[{"question":"Kuo plokštė skiriasi nuo plytelės?","answer":"Dydžiu ir tuo, kas iš jos daroma. Plytelė — gatavas modulis iki 1200 mm klijuoti. Plokštė — ruošinys iki 3,2 m, iš kurio gaminys pjaunamas pagal jūsų matmenis."},{"question":"Kokie plokštės matmenys?","answer":"Natūralus akmuo nuo 2,4 × 1,2 iki 3,2 × 1,9 m, kvarcas 3,05 × 1,4 arba 3,2 × 1,6 m, keraminis granitas 3,2 × 1,6 m. Tikslūs matmenys nurodyti kiekvienai plokštei kataloge."},{"question":"Kiek ji kainuoja?","answer":"Plokštė parduodama už kvadratinį metrą su koeficientu visai plokštei. Kaina priklauso nuo uolienos, storio ir partijos; kataloge nurodyta konkrečių turimų plokščių kaina."},{"question":"Kaip rinktis plokštę?","answer":"Žiūrėti visą plokštę dienos šviesoje, o ne pavyzdį: patikrinti raštą, įtrūkimus, intarpus, suderinti detalių išdėstymą ant plokštės. Atsiunčiame plokštės nuotraukas ir vaizdo įrašą ir rezervuojame ją jums iki pjaustymo."}]},"pl":{"title":"Czym jest sląb i gdzie się go stosuje","h1":"Sląb — co to jest, wymiary i zastosowanie","description":"Sląb to duża płyta kamienia naturalnego lub inżynieryjnego. Wymiary sląbów granitu, marmuru, kwarcu i gresu, grubość, jak wybrać i czym jest resztka.","dek":"Jak czytać całą płytę, partię, ton i powierzchnię użyteczną.","intro":"Sląb (od angielskiego slab, „płyta”) to duża płyta kamienia przecięta z bloku i wypolerowana z jednej strony. Właśnie ze sląbów tnie się blaty, parapety, schody i okładziny, i właśnie sląb, a nie próbkę 10 × 10 cm, trzeba oglądać przed zamówieniem. Wyjaśniamy, jakie bywają sląby, jakie mają wymiary i jak powstaje z nich Twój blat.","sections":[{"heading":"Czym jest sląb?","body":"W kamieniołomie kamień wydobywa się blokami o wadze 10–30 ton. Blok przecina się na płyty o grubości 20 lub 30 mm na trakach linowych lub tarczowych, następnie szlifuje i poleruje stronę licową. Gotowa płyta to właśnie sląb: w kamieniu naturalnym wymiar określa blok, w kwarcu i gresie — format fabryki.\n\nKażdy sląb ma numer, partię i rzeczywiste wymiary, a kamienie naturalne dodatkowo indywidualny rysunek. Dlatego w katalogu pokazujemy nie „granit szary”, lecz konkretne płyty ze zdjęciami, wymiarami i statusem dostępności."},{"heading":"Jakie bywają sląby z granitu, marmuru i kwarcytu?","body":"Granitowe: największa grupa, ukraińskie i importowane, grubość 20 i 30 mm, wykończenie polerowane, matowe, płomieniowane lub leather. Marmurowe: import z Włoch, Hiszpanii, Turcji, grubość 20 i 30 mm, często z siatką zbrojącą na spodzie z powodu kruchości. Kwarcytowe: Brazylia i Indie, grubość 20 i 30 mm, najtwardsze i najdroższe z naturalnych.\n\nKwarcowe (konglomerat): fabryczne płyty standardowego formatu, grubość 20 i 30 mm, jednolity kolor. Gresowe: 6, 12 i 20 mm, format do 3200 × 1600 mm, z dekorem tylko na powierzchni lub barwione w masie zależnie od kolekcji."},{"heading":"Jakie standardowe wymiary ma sląb?","body":"Granit i marmur: od 2400 × 1200 do 3200 × 1900 mm, najczęściej około 2800 × 1600 mm. Wymiar zależy od bloku i skały: ukraińskie granity zwykle 2400–3000 × 1200–1500 mm. Kwarc: standard 3050 × 1400 mm, format Jumbo 3200 × 1600 mm w kolekcjach premium.\n\nGres: Laminam 3240 × 1620 mm, Neolith 3200 × 1600 mm, Dekton 3200 × 1440 mm. Powierzchnia użyteczna jest zawsze mniejsza od gabarytu: brzegi płyty mają odsadzkę 20–50 mm z wadami cięcia, a na kamieniu naturalnym mogą być pęknięcia lub wtrącenia, które omijamy przy rozkroju."},{"heading":"Gdzie stosuje się sląby?","body":"Blaty i wyspy: z granitu, kwarcu, kwarcytu i gresu. Parapety i schody: z granitu, marmuru. Okładziny ścian, kominków i elewacji: z każdego kamienia płytami dużego formatu, gdy potrzebny jest „bezspoinowy” rysunek lub bookmatch, lustrzane zestawienie dwóch sąsiednich sląbów.\n\nResztki sląbów po rozkroju to osobna kategoria: fragmenty 0,5–1,5 m, z których powstają parapety, stoliki, półki i małe blaty w niższej cenie. U nas są dostępne na stronie resztek z wymiarami i zdjęciami."}],"table":{"headers":["Kryterium","Wariant","Co uwzględnić"],"rows":[["Sląb granitowy","Blaty, schody, okładziny","2400–3200 × 1200–1900 mm, 20/30 mm"],["Sląb marmurowy","Łazienki, parapety, portale","Często z siatką na spodzie"],["Sląb kwarcytowy","Blaty i wyspy","Najtwardszy, do 3 × 1,8 m"],["Sląb kwarcowy","Blaty w jednolitym kolorze","3050 × 1400 lub 3200 × 1600 mm"],["Gresowy","Blaty, elewacje, fartuchy","3200 × 1600 mm, 6–20 mm"]]},"faq":[{"question":"Czym sląb różni się od płytki?","answer":"Wymiarem i tym, co się z niego robi. Płytka to gotowy moduł do 1200 mm do układania na klej. Sląb to półprodukt do 3,2 m, z którego wyrób tnie się na Twój wymiar."},{"question":"Jakie wymiary ma sląb?","answer":"Kamień naturalny od 2,4 × 1,2 do 3,2 × 1,9 m, kwarc 3,05 × 1,4 lub 3,2 × 1,6 m, gres 3,2 × 1,6 m. Dokładne wymiary podane są dla każdej płyty w katalogu."},{"question":"Ile kosztuje?","answer":"Sląb sprzedaje się za metr kwadratowy ze współczynnikiem na całą płytę. Cena zależy od skały, grubości i partii; w katalogu podana jest cena konkretnych sląbów dostępnych w magazynie."},{"question":"Jak wybrać sląb?","answer":"Oglądać całą płytę w świetle dziennym, a nie próbkę: sprawdzić rysunek, pęknięcia, wtrącenia, uzgodnić rozkład detali na płycie. Wysyłamy zdjęcia i wideo sląba i rezerwujemy go dla Ciebie do rozkroju."}]}}'::jsonb) where slug = 'shcho-take-slyab';
update stilnytsi_articles set data = data || jsonb_build_object('i18n', '{"de":{"title":"Wie man Stein für die Küche wählt: der komplette Ratgeber 2026","h1":"Wie man Stein für die Küchenarbeitsplatte wählt — der komplette Ratgeber","description":"Wie man Stein für die Küche wählt: Granit, Quarz, Quarzit, Feinsteinzeug oder Marmor. Vergleich nach Festigkeit, Hitze, Pflege, Zeichnung und Budget, Dicke und Kante.","dek":"Der Hauptratgeber nach Festigkeit, Hitze, Pflege und Charakter der Zeichnung.","intro":"Die Wahl des Steins für die Küche beginnt nicht mit dem Namen des Materials, sondern mit drei Fragen: Wie kochen Sie, wie viel Aufmerksamkeit wollen Sie der Pflege widmen, und welchen Charakter soll die Küche haben? Beantworten Sie sie, und Sie erhalten fast automatisch eines von fünf Materialien. In diesem Ratgeber haben wir alles gesammelt, was wir Kunden in der Fertigung erklären, mit Links zu den ausführlichen Artikeln.","sections":[{"heading":"Welchen Stein für die Küche wählen?","body":"Sie kochen viel, stellen Heißes irgendwohin, lieben natürliche Zeichnung: Granit. Sie wollen eine helle gleichmäßige Fläche und minimale Pflege, Heißes auf den Untersetzer: Quarz. Sie wollen einen hellen Naturstein mit Adern, der Zitrone nicht fürchtet: Quarzit. Sie brauchen eine dünne moderne Platte, auf die man Heißes stellen kann: Feinsteinzeug. Sie sind für schönen Marmor zur Patina bereit: Marmor, aber im Wissen um die Folgen.\n\nDas ist ein vereinfachtes Schema, aber es funktioniert in den meisten Fällen. Weiter die Nuancen."},{"heading":"Granit, Quarz, Quarzit, Feinsteinzeug oder Marmor — was ist der Unterschied?","body":"Granit: natürliches Gestein, Härte 6–7, verträgt Hitze, braucht alle 1–3 Jahre Imprägnierung, jede Platte einzigartig, ukrainische Gesteine preisgünstig.\n\nQuarz: 90 % Quarz mit Harz, ohne Poren, wiederholbare Farbe, empfindlich gegen Temperaturen über 150 °C und UV, nicht für außen.\n\nQuarzit: natürlich, Härte 7, säurebeständig, braucht Imprägnierung, helle warme Töne, der teuerste unter den Natursteinen.\n\nFeinsteinzeug: gesinterte 12-mm-Platte, fürchtet nichts außer einem Schlag auf die Kante, am leichtesten, braucht vollflächige Auflage und Fase an der Kante.\n\nMarmor: Kalzit, Härte 3–4, wird von Säuren geätzt, die schönste Zeichnung, für eine Küche mit sorgsamem Besitzer oder für eine Insel, an der nicht gekocht wird."},{"heading":"Was ist bei Festigkeit, Pflege und Budget zu beachten?","body":"Stoß- und Kratzfestigkeit: Quarzit und Granit, dann Quarz und Feinsteinzeug (spröde Kanten), dann Marmor. Fleckenbeständigkeit ohne Imprägnierung: Quarz und Feinsteinzeug, dann Quarzit und Granit mit Imprägnierung, dann Marmor.\n\nPflege: Quarz und Feinsteinzeug nichts außer Waschen; Granit und Quarzit Wassertest und Imprägnierung; Marmor jährliche Imprägnierung und immer neutrale Chemie. Budget aufsteigend: ukrainische Granite und Basis-Feinsteinzeug, dann Quarz und Gabbro, dann Marmor, Quarzit und Premiumkollektionen von Quarz und Feinsteinzeug."},{"heading":"Welche Dicke und Bearbeitung sind nötig?","body":"Dicke: 20 mm für die Standardküche bei allen Materialien, 30 mm für lange Konsolen oder massiven Stil, 12 mm für Feinsteinzeug mit verleimter Kante. Kante: gerade oder Fase als Basis, Rundung R3 für Familien mit Kindern, verleimte 40 mm für die Optik einer dicken Platte.\n\nOberfläche: Poliert zeigt die Zeichnung und lässt sich leichter waschen, matt (honed) verbirgt Fingerabdrücke und Ätzungen auf Marmor, Leather auf dunklem Granit bringt Haptik und verbirgt Kratzer. In einer Küche mit Südfenster blendet dunkler polierter Stein — bedenken Sie das."},{"heading":"Wie bestellt und kalkuliert man?","body":"Ermitteln Sie einen Richtwert im Rechner, wählen Sie zwei bis drei Kollektionen im Katalog und schreiben Sie uns mit dem Küchenplan. Wir senden Fotos der vorrätigen Platten, einen Kostenvoranschlag mit Zuschnitt und einen Aufmaßtermin. Nach dem Aufmaß geben Sie die Aufteilung der Teile auf der konkreten Platte frei, und in ein bis zwei Wochen steht die Arbeitsplatte in der Küche.\n\nWenn Sie zwischen zwei Materialien schwanken, kommen Sie in die Fertigung nach Kostopil oder bestellen Sie Muster: Daran können Sie den Haustest mit Zitrone, heißer Tasse und Messer machen, nach dem die Wahl offensichtlich wird."}],"table":{"headers":["Material","Stärke","Zu beachten"],"rows":[["Granit","Hitze, Stöße, einzigartige Zeichnung","Imprägnierung alle 1–3 Jahre"],["Quarz","Porenfrei, wiederholbare Farbe","Untersetzer für Heißes, nicht für außen"],["Quarzit","Härte und heller natürlicher Ton","Plattenfreigabe, höherer Preis"],["Feinsteinzeug","Dünn, hitzefest, UV-beständig","Spröde Kanten, vollflächige Auflage"],["Marmor","Die schönste Zeichnung","Säuren, Patina, jährliche Pflege"]]},"faq":[{"question":"Was ist am praktischsten?","answer":"Quarz für eine helle Küche, Granit für jede andere. Beide verzeihen den täglichen Gebrauch, der Unterschied liegt nur in heißem Geschirr und Imprägnierung."},{"question":"Was für eine Familie mit Kindern?","answer":"Quarz oder Granit mit abgerundeter Kante R3. Feinsteinzeug verträgt Stöße von Spielzeug auf die Kante schlechter, Marmor braucht Aufmerksamkeit, die in einer Familie mit Kindern meist fehlt."},{"question":"Was braucht eine Imprägnierung?","answer":"Granit, Quarzit und Marmor. Quarz und Feinsteinzeug haben keine Poren und werden nicht imprägniert."},{"question":"Womit beginnt man die Wahl?","answer":"Mit dem Szenario: wie Sie kochen und wie viel Pflege Sie geben wollen. Dann mit Farbe und Zeichnung im Katalog, dann mit dem Rechner und Mustern."}]},"en":{"title":"How to choose stone for a kitchen: the complete 2026 guide","h1":"How to choose stone for a kitchen countertop — the complete guide","description":"How to choose stone for a kitchen: granite, quartz, quartzite, porcelain or marble. Comparison by strength, heat, care, pattern and budget, thickness and edge.","dek":"The main guide by strength, heat, care and the character of the pattern.","intro":"Choosing stone for a kitchen starts not with the name of the material but with three questions: how you cook, how much attention you are willing to give to care, and what character the kitchen should have. Answer them and you almost automatically get one of five materials. In this guide we have gathered everything we explain to clients at the workshop, with links to the detailed articles.","sections":[{"heading":"Which stone to choose for a kitchen?","body":"You cook a lot, put hot things wherever, love a natural pattern: granite. You want a light uniform surface and minimal care, hot things on a trivet: quartz. You want a light natural stone with veins that is not afraid of lemon: quartzite. You need a thin modern countertop you can put hot things on: porcelain. You are ready for patina for the sake of beautiful marble: marble, but understanding the consequences.\n\nIt is a simplified scheme, but it works in most cases. Now the nuances."},{"heading":"Granite, quartz, quartzite, porcelain or marble — what is the difference?","body":"Granite: natural rock, hardness 6–7, takes heat, needs sealing every 1–3 years, every slab unique, Ukrainian stones affordable.\n\nQuartz: 90 % quartz with resin, no pores, repeatable colour, sensitive to temperatures above 150 °C and to ultraviolet, not for outdoors.\n\nQuartzite: natural, hardness 7, acid-resistant, needs sealing, light warm tones, the most expensive of the natural stones.\n\nPorcelain: a sintered 12 mm sheet, afraid of nothing except a blow to the edge, the lightest, needs a continuous substrate and a bevelled edge.\n\nMarble: calcite, hardness 3–4, etched by acids, the most beautiful pattern, for a kitchen with a careful owner or for an island where no cooking is done."},{"heading":"What to consider for strength, care and budget?","body":"Impact and scratch resistance: quartzite and granite, then quartz and porcelain (brittle edges), then marble. Stain resistance without sealing: quartz and porcelain, then quartzite and granite with sealing, then marble.\n\nCare: quartz and porcelain nothing but washing; granite and quartzite a water test and sealing; marble sealing every year and always neutral chemistry. Budget in ascending order: Ukrainian granites and basic porcelain, then quartz and gabbro, then marble, quartzite and premium collections of quartz and porcelain."},{"heading":"What thickness and finish are needed?","body":"Thickness: 20 mm for a standard kitchen in all materials, 30 mm for long consoles or a massive style, 12 mm for porcelain with a laminated edge. Edge: straight or bevel as standard, R3 rounding for families with children, a 40 mm laminated edge for the look of a thick slab.\n\nFinish: polished shows the pattern and is easier to wash; honed hides fingerprints and etching on marble; leather on dark granite adds tactility and hides scratches. In a kitchen with a south-facing window dark polished stone will give glare — keep that in mind."},{"heading":"How to order and calculate the cost?","body":"Get a guide price in the calculator, pick two or three collections in the catalogue and write to us with the kitchen plan. We will send photos of the slabs in stock, an estimate with the cutting layout and a measurement date. After the measurement you approve the layout of the parts on the specific slab, and within one to two weeks the countertop is in the kitchen.\n\nIf you are torn between two materials, come to the workshop in Kostopil or order samples: you can run a home test on them with lemon, a hot cup and a knife, after which the choice becomes obvious."}],"table":{"headers":["Material","Strong point","What to consider"],"rows":[["Granite","Heat, impact, unique pattern","Sealing every 1–3 years"],["Quartz","No pores, repeatable colour","Trivet for hot things, not for outdoors"],["Quartzite","Hardness and light natural tone","Slab approval, higher price"],["Porcelain","Thinness, heat, UV resistance","Brittle edges, continuous substrate"],["Marble","The most beautiful pattern","Acids, patina, care every year"]]},"faq":[{"question":"What is the most practical?","answer":"Quartz for a light kitchen, granite for any other. Both forgive daily use; the difference is only in hot pans and sealing."},{"question":"What to choose for a family with children?","answer":"Quartz or granite with a rounded R3 edge. Porcelain takes knocks from toys on the edge worse, and marble needs attention that a family with children usually does not have."},{"question":"What needs sealing?","answer":"Granite, quartzite and marble. Quartz and porcelain have no pores and are not sealed."},{"question":"Where to start the choice?","answer":"With the scenario: how you cook and how much care you are willing to give. Then with the colour and pattern in the catalogue, then with the calculator and samples."}]},"lt":{"title":"Kaip išsirinkti akmenį virtuvei: išsamus gidas 2026","h1":"Kaip išsirinkti akmenį virtuvės stalviršiui — išsamus gidas","description":"Kaip išsirinkti akmenį virtuvei: granitas, kvarcas, kvarcitas, keraminis granitas ar marmuras. Palyginimas pagal tvirtumą, karštį, priežiūrą, raštą ir biudžetą, storį ir kraštą.","dek":"Pagrindinis gidas pagal tvirtumą, karštį, priežiūrą ir rašto charakterį.","intro":"Akmens pasirinkimas virtuvei prasideda ne nuo medžiagos pavadinimo, o nuo trijų klausimų: kaip gaminate, kiek dėmesio pasiryžę skirti priežiūrai ir kokį charakterį turi turėti virtuvė. Atsakę į juos, beveik automatiškai gausite vieną iš penkių medžiagų. Šiame gide surinkome viską, ką aiškiname klientams gamyboje, su nuorodomis į išsamius straipsnius.","sections":[{"heading":"Kokį akmenį rinktis virtuvei?","body":"Daug gaminate, statote karštus indus kur pakliūva, mėgstate natūralų raštą: granitas. Norite šviesaus vienalyčio paviršiaus ir minimalios priežiūros, karštus indus ant padėklo: kvarcas. Norite šviesaus natūralaus akmens su gyslomis, kuris nebijo citrinos: kvarcitas. Reikia plono modernaus stalviršio, ant kurio galima statyti karštus indus: keraminis granitas. Pasiryžę patinai dėl gražaus marmuro: marmuras, bet suprantant pasekmes.\n\nTai supaprastinta schema, bet ji veikia daugumoje atvejų. Toliau niuansai."},{"heading":"Granitas, kvarcas, kvarcitas, keraminis granitas ar marmuras — koks skirtumas?","body":"Granitas: natūrali uoliena, kietumas 6–7, atlaiko karštį, reikia impregnuoti kartą per 1–3 metus, kiekviena plokštė unikali, ukrainietiškos uolienos prieinamos kaina.\n\nKvarcas: 90 % kvarco su derva, be porų, kartojama spalva, jautrus temperatūrai virš 150 °C ir ultravioletui, ne laukui.\n\nKvarcitas: natūralus, kietumas 7, atsparus rūgštims, reikia impregnuoti, šviesūs šilti tonai, brangiausias iš natūralių.\n\nKeraminis granitas: sukepinta 12 mm plokštė, nebijo nieko, išskyrus smūgio į briauną, lengviausias, reikia vientiso pagrindo ir nuožulnos ant krašto.\n\nMarmuras: kalcitas, kietumas 3–4, ėsdinamas rūgštimis, gražiausias raštas, virtuvei su atsargiu šeimininku arba salai, kur negaminama."},{"heading":"Į ką atsižvelgti pagal tvirtumą, priežiūrą ir biudžetą?","body":"Atsparumas smūgiams ir įbrėžimams: kvarcitas ir granitas, paskui kvarcas ir keraminis granitas (trapūs kraštai), paskui marmuras. Atsparumas dėmėms be impregnavimo: kvarcas ir keraminis granitas, paskui kvarcitas ir granitas su impregnavimu, paskui marmuras.\n\nPriežiūra: kvarcas ir keraminis granitas nieko, išskyrus plovimą; granitas ir kvarcitas — vandens testas ir impregnavimas; marmuras — impregnavimas kasmet ir visada neutrali chemija. Biudžetas didėjimo tvarka: ukrainietiški granitai ir bazinis keraminis granitas, toliau kvarcas ir gabras, toliau marmuras, kvarcitas ir premium kvarco bei keraminio granito kolekcijos."},{"heading":"Kokio storio ir apdirbimo reikia?","body":"Storis: 20 mm standartinei virtuvei visose medžiagose, 30 mm ilgoms konsolėms ar masyviam stiliui, 12 mm keraminiam granitui su suklijuotu kraštu. Kraštas: tiesus kraštas arba nuožulna baziniai, suapvalinimas R3 šeimoms su vaikais, suklijuotas 40 mm storos plokštės išvaizdai.\n\nApdaila: poliruota parodo raštą ir lengviau plaunama, matinė (honed) paslepia pirštų atspaudus ir ėsdinimą ant marmuro, leather ant tamsaus granito prideda lytėjimo pojūčio ir paslepia įbrėžimus. Virtuvėje su langu į pietus tamsus poliruotas akmuo duos atspindžių, atsižvelkite į tai."},{"heading":"Kaip užsakyti ir apskaičiuoti kainą?","body":"Paskaičiuokite orientyrą skaičiuoklėje, išsirinkite dvi–tris kolekcijas kataloge ir parašykite mums su virtuvės planu. Atsiųsime turimų plokščių nuotraukas, sąmatą su pjaustymu ir matavimo datą. Po matavimo patvirtinate detalių išdėstymą konkrečioje plokštėje, ir per vieną–dvi savaites stalviršis stovi virtuvėje.\n\nJei dvejojate tarp dviejų medžiagų, atvykite į gamybą Kostopilyje arba užsisakykite pavyzdžių: ant jų galima atlikti namų testą su citrina, karštu puodeliu ir peiliu, po kurio pasirinkimas tampa akivaizdus."}],"table":{"headers":["Medžiaga","Stiprioji pusė","Į ką atsižvelgti"],"rows":[["Granitas","Karštis, smūgiai, unikalus raštas","Impregnavimas kartą per 1–3 metus"],["Kvarcas","Be porų, kartojama spalva","Padėklas karštiems indams, ne laukui"],["Kvarcitas","Kietumas ir šviesus natūralus tonas","Plokštės suderinimas, aukštesnė kaina"],["Keraminis granitas","Plonumas, karštis, atsparumas UV","Trapūs kraštai, vientisas pagrindas"],["Marmuras","Gražiausias raštas","Rūgštys, patina, priežiūra kasmet"]]},"faq":[{"question":"Kas praktiškiausia?","answer":"Kvarcas šviesiai virtuvei, granitas bet kuriai kitai. Abu atleidžia kasdienį naudojimą, skirtumas tik karštuose induose ir impregnavime."},{"question":"Ką rinktis šeimai su vaikais?","answer":"Kvarcą arba granitą su suapvalintu kraštu R3. Keraminis granitas blogiau atlaiko žaislų smūgius į briauną, marmuras reikalauja dėmesio, kurio šeimoje su vaikais paprastai nėra."},{"question":"Ką reikia impregnuoti?","answer":"Granitą, kvarcitą ir marmurą. Kvarcas ir keraminis granitas neturi porų ir neimpregnuojami."},{"question":"Nuo ko pradėti pasirinkimą?","answer":"Nuo scenarijaus: kaip gaminate ir kiek priežiūros pasiryžę skirti. Paskui nuo spalvos ir rašto kataloge, paskui nuo skaičiuoklės ir pavyzdžių."}]},"pl":{"title":"Jak wybrać kamień do kuchni: pełny przewodnik 2026","h1":"Jak wybrać kamień na blat kuchenny — pełny przewodnik","description":"Jak wybrać kamień do kuchni: granit, kwarc, kwarcyt, gres czy marmur. Porównanie wytrzymałości, odporności na ciepło, pielęgnacji, rysunku i budżetu, grubość i krawędź.","dek":"Główny przewodnik według wytrzymałości, ciepła, pielęgnacji i charakteru rysunku.","intro":"Wybór kamienia do kuchni zaczyna się nie od nazwy materiału, lecz od trzech pytań: jak gotujesz, ile uwagi jesteś gotów poświęcić pielęgnacji i jaki charakter ma mieć kuchnia. Odpowiadając na nie, niemal automatycznie dostajesz jeden z pięciu materiałów. W tym przewodniku zebraliśmy wszystko, co wyjaśniamy klientom na produkcji, z linkami do szczegółowych artykułów.","sections":[{"heading":"Który kamień wybrać do kuchni?","body":"Gotujesz dużo, stawiasz gorące gdzie popadnie, lubisz naturalny rysunek: granit. Chcesz jasnej jednolitej powierzchni i minimum pielęgnacji, gorące na podkładkę: kwarc. Chcesz jasnego kamienia naturalnego z żyłkami, który nie boi się cytryny: kwarcyt. Potrzebujesz cienkiego nowoczesnego blatu, na który można stawiać gorące: gres. Jesteś gotów na patynę dla pięknego marmuru: marmur, ale ze zrozumieniem konsekwencji.\n\nTo uproszczony schemat, ale działa w większości przypadków. Dalej niuanse."},{"heading":"Granit, kwarc, kwarcyt, gres czy marmur — jaka różnica?","body":"Granit: skała naturalna, twardość 6–7, wytrzymuje gorące, wymaga impregnacji raz na 1–3 lata, każdy sląb unikalny, ukraińskie skały przystępne cenowo.\n\nKwarc: 90 % kwarcu z żywicą, bez porów, powtarzalny kolor, wrażliwy na temperaturę powyżej 150 °C i na ultrafiolet, nie na zewnątrz.\n\nKwarcyt: naturalny, twardość 7, odporny na kwasy, wymaga impregnacji, jasne ciepłe tony, najdroższy z naturalnych.\n\nGres: spiekana płyta 12 mm, nie boi się nic poza uderzeniem w krawędź, najlżejszy, wymaga pełnego podłoża i fazy na krawędzi.\n\nMarmur: kalcyt, twardość 3–4, wytrawiany przez kwasy, najpiękniejszy rysunek, do kuchni z ostrożnym gospodarzem lub na wyspę, na której się nie gotuje."},{"heading":"Co uwzględnić pod kątem wytrzymałości, pielęgnacji i budżetu?","body":"Odporność na uderzenia i zarysowania: kwarcyt i granit, potem kwarc i gres (kruche krawędzie), potem marmur. Odporność na plamy bez impregnacji: kwarc i gres, potem kwarcyt i granit z impregnacją, potem marmur.\n\nPielęgnacja: kwarc i gres nic poza myciem; granit i kwarcyt test wodny i impregnacja; marmur impregnacja co roku i zawsze neutralna chemia. Budżet rosnąco: ukraińskie granity i podstawowy gres, dalej kwarc i gabro, dalej marmur, kwarcyt i kolekcje premium kwarcu i gresu."},{"heading":"Jaka grubość i obróbka są potrzebne?","body":"Grubość: 20 mm do standardowej kuchni we wszystkich materiałach, 30 mm do długich konsol lub masywnego stylu, 12 mm dla gresu z klejoną krawędzią. Krawędź: prosta lub faza bazowo, zaokrąglenie R3 dla rodzin z dziećmi, klejona 40 mm dla wyglądu grubej płyty.\n\nWykończenie: polerowane pokazuje rysunek i łatwiej się myje, matowe (honed) ukrywa odciski i wytrawienia na marmurze, leather na ciemnym granicie dodaje dotykowości i ukrywa rysy. W kuchni z oknem na południe ciemny polerowany kamień da odblaski, uwzględnij to."},{"heading":"Jak zamówić i wyliczyć koszt?","body":"Policz orientację w kalkulatorze, wybierz dwie–trzy kolekcje w katalogu i napisz do nas z planem kuchni. Wyślemy zdjęcia sląbów w magazynie, kosztorys z rozkrojem i termin pomiaru. Po pomiarze zatwierdzasz rozkład detali na konkretnej płycie i za tydzień–dwa blat stoi w kuchni.\n\nJeśli wahasz się między dwoma materiałami, przyjedź na produkcję do Kostopola lub zamów próbki: można na nich zrobić domowy test cytryną, gorącym kubkiem i nożem, po którym wybór staje się oczywisty."}],"table":{"headers":["Materiał","Mocna strona","Co uwzględnić"],"rows":[["Granit","Ciepło, uderzenia, unikalny rysunek","Impregnacja raz na 1–3 lata"],["Kwarc","Bez porów, powtarzalny kolor","Podkładka pod gorące, nie na zewnątrz"],["Kwarcyt","Twardość i jasny naturalny ton","Uzgodnienie sląba, wyższa cena"],["Gres","Cienkość, gorące, odporność na UV","Kruche krawędzie, pełne podłoże"],["Marmur","Najpiękniejszy rysunek","Kwasy, patyna, pielęgnacja co roku"]]},"faq":[{"question":"Co jest najpraktyczniejsze?","answer":"Kwarc do jasnej kuchni, granit do każdej innej. Oba wybaczają codzienne użytkowanie, różnica tylko w gorących naczyniach i impregnacji."},{"question":"Co wybrać dla rodziny z dziećmi?","answer":"Kwarc lub granit z zaokrągloną krawędzią R3. Gres gorzej znosi uderzenia zabawkami w krawędź, marmur wymaga uwagi, której w rodzinie z dziećmi zwykle brakuje."},{"question":"Co wymaga impregnacji?","answer":"Granit, kwarcyt i marmur. Kwarc i gres nie mają porów i nie są impregnowane."},{"question":"Od czego zacząć wybór?","answer":"Od scenariusza: jak gotujesz i ile pielęgnacji jesteś gotów dać. Potem od koloru i rysunku w katalogu, potem od kalkulatora i próbek."}]}}'::jsonb) where slug = 'yak-vybraty-kamin-dlya-kukhni';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"Rodzina w nowym budownictwie potrzebuje blatu, którego nie trzeba oszczędzać: jasny kwarc łatwo sprzątać po codziennym gotowaniu.","solution":"Blat w kształcie L, zlew podwieszany, krótki fartuch.","alt":"Standardowa kuchnia w nowym budownictwie z blatem Vicostone BQ8270 Calacatta"},"en":{"story":"A family in a new-build needs a countertop they don''t have to baby: light quartz is easy to clean after everyday cooking.","solution":"L-shaped countertop, undermount sink, short splashback.","alt":"Standard new-build kitchen with a Vicostone BQ8270 Calacatta countertop"},"de":{"story":"Eine Familie im Neubau braucht eine Arbeitsplatte, die man nicht schonen muss: Heller Quarz lässt sich nach dem täglichen Kochen leicht reinigen.","solution":"L-förmige Arbeitsplatte, Unterbauspüle, kurzer Spritzschutz.","alt":"Standardküche im Neubau mit Arbeitsplatte Vicostone BQ8270 Calacatta"},"lt":{"story":"Šeimai naujame name reikia stalviršio, kurio nereikia gailėti: šviesų kvarcą lengva nuvalyti po kasdienio gaminimo.","solution":"L formos stalviršis, apatinio montavimo plautuvė, trumpa sienelė.","alt":"Standartinė virtuvė naujame name su stalviršiu Vicostone BQ8270 Calacatta"}}'::jsonb) where slug = 'kitchen-everyday';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"W kuchni domu prywatnego wyspa zbiera rodzinę na śniadanie, a jasnoszary granit wytrzymuje codzienną pracę.","solution":"Kompaktowa wyspa, matowa powierzchnia, prosta krawędź.","alt":"Rodzinna kuchnia z wyspą z granitu pokostiwskiego Grey Ukraine"},"en":{"story":"In the kitchen of a private house the island gathers the family for breakfast, and light grey granite withstands daily work.","solution":"Compact island, honed surface, simple straight edge.","alt":"Family kitchen with an island in Pokostivka granite Grey Ukraine"},"de":{"story":"In der Küche eines Privathauses versammelt die Insel die Familie zum Frühstück, und hellgrauer Granit hält die tägliche Arbeit aus.","solution":"Kompakte Insel, matte Oberfläche, einfache gerade Kante.","alt":"Familienküche mit Insel aus Pokostivka-Granit Grey Ukraine"},"lt":{"story":"Privataus namo virtuvėje sala suburia šeimą pusryčiams, o šviesiai pilkas granitas atlaiko kasdienį darbą.","solution":"Kompaktiška sala, matinis paviršius, paprastas tiesus kraštas.","alt":"Šeimos virtuvė su sala iš Pokostivkos granito Grey Ukraine"}}'::jsonb) where slug = 'family-island';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"W standardowej łazience beżowy marmur ogrzewa szafkę i jedną ścianę akcentową, nie przeciążając niewielkiego pomieszczenia.","solution":"Blat pod umywalkę, jeden panel ścienny, impregnacja ochronna.","alt":"Zwykła łazienka z marmurem Crema Marfil"},"en":{"story":"In a standard bathroom beige marble warms the vanity and one accent wall without overloading the small room.","solution":"Vanity top, one wall panel, protective sealing.","alt":"Ordinary bathroom with Crema Marfil marble"},"de":{"story":"In einem Standardbad wärmt beiger Marmor den Waschtisch und eine Akzentwand, ohne den kleinen Raum zu überladen.","solution":"Waschtischplatte, ein Wandpaneel, Schutzimprägnierung.","alt":"Gewöhnliches Badezimmer mit Marmor Crema Marfil"},"lt":{"story":"Standartinėje vonioje smėlinis marmuras sušildo spintelę ir vieną akcentinę sieną, neperkraudamas nedidelio kambario.","solution":"Stalviršis po praustuvu, viena sienos plokštė, apsauginis impregnavimas.","alt":"Paprastas vonios kambarys su marmuru Crema Marfil"}}'::jsonb) where slug = 'bathroom-without-excess';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"Schody w domu dwupiętrowym mają przeżyć dzieci i wnuki, dlatego rodzina wybrała mocny lokalny granit.","solution":"Matowe stopnice, prosty cokół, obróbka antypoślizgowa.","alt":"Jasne domowe schody ze stopnicami z granitu pokostiwskiego Grey Ukraine"},"en":{"story":"The stairs in a two-storey house must outlive children and grandchildren, so the family chose strong local granite.","solution":"Honed treads, simple skirting, anti-slip finish.","alt":"Light home stairs with treads in Pokostivka granite Grey Ukraine"},"de":{"story":"Die Treppe in einem zweigeschossigen Haus soll Kinder und Enkel überdauern, deshalb wählte die Familie festen heimischen Granit.","solution":"Matte Trittstufen, einfacher Sockel, rutschhemmende Bearbeitung.","alt":"Helle Haustreppe mit Trittstufen aus Pokostivka-Granit Grey Ukraine"},"lt":{"story":"Laiptai dviaukščiame name turi pergyventi vaikus ir anūkus, todėl šeima pasirinko tvirtą vietinį granitą.","solution":"Matinės pakopos, paprasta grindjuostė, neslidus apdirbimas.","alt":"Šviesūs namų laiptai su pakopomis iš Pokostivkos granito Grey Ukraine"}}'::jsonb) where slug = 'stairs-in-house';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"Właściciele domu potrzebują schodów, które nie boją się śniegu, soli i codziennego obuwia. Płomieniowane gabro daje pewną przyczepność.","solution":"Płomieniowane stopnice, odprowadzenie wody, dobrze widoczne krawędzie.","alt":"Zadbane wejście do domu prywatnego ze schodami z płomieniowanego gabro Kometa Black"},"en":{"story":"The homeowners need steps that aren''t afraid of snow, salt and everyday shoes. Flamed gabbro gives reliable grip.","solution":"Flamed treads, drainage, clearly visible edges.","alt":"Well-kept private house entrance with steps in flamed Kometa Black gabbro"},"de":{"story":"Die Hausbesitzer brauchen eine Treppe, die weder Schnee, Salz noch Alltagsschuhe fürchtet. Geflammter Gabbro gibt sicheren Halt.","solution":"Geflammte Trittstufen, Wasserableitung, gut sichtbare Kanten.","alt":"Gepflegter Eingang eines Privathauses mit Treppe aus geflammtem Gabbro Kometa Black"},"lt":{"story":"Namo savininkams reikia laiptų, kurie nebijo sniego, druskos ir kasdienių batų. Degintas gabras suteikia patikimą sukibimą.","solution":"Degintos pakopos, vandens nuvedimas, gerai matomi kraštai.","alt":"Tvarkingas įėjimas į privatų namą su laiptais iš deginto gabro Kometa Black"}}'::jsonb) where slug = 'winterproof-entry';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"Na zwykłej działce podmiejskiej połączono czerwony Maple Red z szarym Grey Ukraine w ścieżce i miejscu parkingowym.","solution":"Kostka cięto-płomieniowana, prosty dwukolorowy moduł, spadki dla wody.","alt":"Zadbane prywatne podwórze z czerwoną kostką Maple Red i jasnoszarymi akcentami Grey Ukraine"},"en":{"story":"On an ordinary suburban plot red Maple Red was combined with grey Grey Ukraine in the path and parking space.","solution":"Sawn-flamed paving, simple two-colour module, slopes for water.","alt":"Well-kept private yard with red Maple Red paving and light grey Grey Ukraine accents"},"de":{"story":"Auf einem gewöhnlichen Vorstadtgrundstück wurden roter Maple Red und grauer Grey Ukraine in Weg und Stellplatz kombiniert.","solution":"Gesägt-geflammtes Pflaster, einfaches zweifarbiges Modul, Gefälle für Wasser.","alt":"Gepflegter Privathof mit rotem Pflaster Maple Red und hellgrauen Akzenten Grey Ukraine"},"lt":{"story":"Paprastame priemiesčio sklype take ir stovėjimo vietoje suderintas raudonas Maple Red su pilku Grey Ukraine.","solution":"Pjautas-degintas grindinys, paprastas dvispalvis modulis, nuolydžiai vandeniui.","alt":"Tvarkingas privatus kiemas su raudonu grindiniu Maple Red ir šviesiai pilkais Grey Ukraine akcentais"}}'::jsonb) where slug = 'turnkey-yard';
update stilnytsi_projects set data = data || jsonb_build_object('i18n', '{"pl":{"story":"Głęboki parapet w mieszkaniu pracuje jak półka na kwiaty i kubek, a kwarc w kolorze betonu łatwo wytrzeć.","solution":"Głęboka płyta, niewielki nawis, staranne przyleganie do okna.","alt":"Przytulny parapet do czytania z kwarcu Caesarstone 4001 Fresh Concrete"},"en":{"story":"A deep window sill in a flat works as a shelf for plants and a cup, and concrete-look quartz is easy to wipe.","solution":"Deep slab, small overhang, neat fit to the window.","alt":"Cosy reading window sill in Caesarstone 4001 Fresh Concrete quartz"},"de":{"story":"Eine tiefe Fensterbank in einer Wohnung dient als Ablage für Blumentöpfe und Tasse, und Quarz in Betonoptik lässt sich leicht abwischen.","solution":"Tiefe Platte, kleiner Überstand, sauberer Anschluss ans Fenster.","alt":"Gemütliche Lesefensterbank aus Quarz Caesarstone 4001 Fresh Concrete"},"lt":{"story":"Gili palangė bute dirba kaip lentyna vazonams ir puodeliui, o betono imitacijos kvarcą lengva nušluostyti.","solution":"Gili plokštė, nedidelė iškyša, tvarkingas priglaudimas prie lango.","alt":"Jauki skaitymo palangė iš kvarco Caesarstone 4001 Fresh Concrete"}}'::jsonb) where slug = 'windowsill-for-years';
